@app.after_request
def add_security_headers(response):
    response.headers["X-Content-Type-Options"] = "nosniff"

    response.headers["Referrer-Policy"] = (
        "strict-origin-when-cross-origin"
    )

    response.headers["X-Frame-Options"] = "DENY"

    response.headers["Cross-Origin-Embedder-Policy"] = (
        "unsafe-none"
    )

    response.headers["Cross-Origin-Opener-Policy"] = (
        "same-origin"
    )

    response.headers["Permissions-Policy"] = (
        "camera=(), microphone=(), geolocation=()"
    )

    s3_csp_source = ""
    if S3_BUCKET_NAME:
        s3_csp_source = (
            f"https://{S3_BUCKET_NAME}.s3.{AWS_REGION}.amazonaws.com "
        )

    response.headers["Content-Security-Policy"] = (
        "default-src 'self'; "
        "script-src 'self'; "
        "style-src 'self'; "
        f"img-src 'self' data: blob: {s3_csp_source}; "
        "media-src 'self' blob:; "
        "font-src 'self' data:; "
        "connect-src 'self'; "
        "object-src 'none'; "
        "base-uri 'self'; "
        "frame-ancestors 'none'; "
        "form-action 'self'; "
        "frame-src 'none'; "
        "worker-src 'self' blob:; "
        "manifest-src 'self'"
    )
    
    protected_static_file = (
        request.path.startswith("/static/uploads/")
        or request.path.startswith("/static/manuals/")
    )

    if request.path == "/static/manifest.webmanifest":
        response.headers["Cache-Control"] = (
            "no-cache, must-revalidate"
        )

    if (
        protected_static_file
        or not request.path.startswith("/static/")
    ):
        response.headers["Cache-Control"] = (
            "no-store, no-cache, must-revalidate, max-age=0"
        )
        response.headers["Pragma"] = "no-cache"
        
    if os.environ.get("RENDER") == "true":
        response.headers["Strict-Transport-Security"] = (
            "max-age=31536000; includeSubDomains"
        )

    return response

