def checklist_for_date(
    checklist,
    year,
    month,
    day
):
    current_checklist = {
        key: value
        for key, value in checklist.items()
        if key != "version_history"
    }

    try:
        target_date = datetime(
            int(year),
            int(month),
            int(day)
        ).date()
    except (TypeError, ValueError):
        return current_checklist

    version_history = []

    for version in checklist.get(
        "version_history",
        []
    ):
        try:
            change_datetime = datetime.strptime(
                version.get("effective_until", ""),
                "%Y-%m-%d %H:%M:%S"
            )
        except (TypeError, ValueError):
            continue

        snapshot = version.get("snapshot") or {}

        if not isinstance(snapshot, dict):
            continue

        version_history.append({
            "change_date": change_datetime.date(),
            "snapshot": snapshot
        })

    version_history.sort(
        key=lambda version: version["change_date"]
    )

    for version in version_history:
        if target_date < version["change_date"]:
            return version["snapshot"]

    return current_checklist


def checklists_for_current_company():
    query = ordered_master_query(Checklist, session.get("company_code"))

    return [
        checklist_to_dict(checklist)
        for checklist in query.all()
    ]

def safe_json_list(value):
    try:
        parsed = json.loads(value or "[]")
    except (TypeError, ValueError):
        return []

    return parsed if isinstance(parsed, list) else []

def safe_json_str_list(value):
    return [
        item
        for item in safe_json_list(value)
        if isinstance(item, str) and item.strip()
    ]

def safe_json_dict_list(value):
    return [
        item
        for item in safe_json_list(value)
        if isinstance(item, dict)
    ]

def safe_json_dict(value):
    try:
        parsed = json.loads(value or "{}")
    except (TypeError, ValueError):
        return {}

    return parsed if isinstance(parsed, dict) else {}

def find_vehicle_pending_cross_source_group(company_code, source_kind, identity):
    """Only reuse one unambiguous full-plate group across CSV/document sources."""
    plate = get_vehicle_import_pending_plate(identity)
    if plate is None:
        return None
    matches = [
        group for group in VehicleImportPending.query.filter_by(
            company_code=company_code, status="pending"
        ).with_for_update().all()
        if get_vehicle_import_pending_plate(safe_json_dict(group.identity_json)) == plate
    ]
    if len(matches) != 1:
        return None
    group = matches[0]
    existing = safe_json_dict(group.identity_json)
    unknown = {"", "不明", "記載なし", "未設定", "なし", "unknown", "none", "n/a"}
    for field in ("chassis_number", "source_vehicle_code"):
        left = normalize_vehicle_operation_plate(existing.get(field))
        right = normalize_vehicle_operation_plate(identity.get(field))
        if left not in unknown and right not in unknown and left != right:
            return None
    kinds = {
        row.source_kind for row in VehicleImportPendingRecord.query.filter_by(
            company_code=company_code, pending_id=group.id, status="pending"
        ).all()
    }
    has_other_source = (
        bool(kinds - {"operation"}) if source_kind == "operation"
        else "operation" in kinds
    )
    if not has_other_source:
        return None
    # Preserve the identifiers supplied by each source for subsequent conflicts.
    for field in ("chassis_number", "source_vehicle_code"):
        if (
            normalize_vehicle_operation_plate(existing.get(field)) in unknown
            and normalize_vehicle_operation_plate(identity.get(field)) not in unknown
        ):
            existing[field] = identity[field]
    group.identity_json = json.dumps(existing, ensure_ascii=False)
    return group


def save_vehicle_import_pending_record(
    *, company_code, username, source_kind, source_draft_id,
    source_record_index, group_identity, identity,
    record_identity, payload, record_date=None
):
    document_kinds = {"driving_report", "inspection", "maintenance"}
    if source_kind not in document_kinds | {"operation"}:
        raise UploadValidationError("取込データの種類が不正です。")
    if not company_code or not username:
        raise UploadValidationError("会社・利用者を確認してください。")
    if (
        isinstance(source_record_index, bool)
        or not isinstance(source_record_index, int)
        or source_record_index < 0
        or not isinstance(identity, dict)
        or not isinstance(payload, dict)
        or not group_identity
        or not record_identity
    ):
        raise UploadValidationError("登録待ちデータの形式が不正です。")

    draft_model = (
        VehicleOperationImportDraft
        if source_kind == "operation"
        else VehicleDocumentImportDraft
    )
    draft = draft_model.query.filter_by(
        id=source_draft_id, company_code=company_code
    ).first()
    if draft is None or (
        source_kind != "operation"
        and draft.document_type != source_kind
    ):
        raise UploadValidationError("同じ会社の取込原本を確認できません。")

    def serialize(value):
        return json.dumps(
            value, ensure_ascii=False, sort_keys=True,
            separators=(",", ":"), default=str
        )

    # Serialize creation as well as reuse, including when no group exists yet.
    if Company.query.filter_by(company_code=company_code).with_for_update().first() is None:
        raise UploadValidationError("会社情報を確認できません。")

    record_key = hashlib.sha256(
        serialize(record_identity).encode("utf-8")
    ).hexdigest()
    payload_json = serialize(payload)
    existing = VehicleImportPendingRecord.query.filter_by(
        company_code=company_code,
        source_kind=source_kind,
        record_key=record_key
    ).first()
    if existing is not None:
        if serialize(safe_json_dict(existing.payload_json)) != payload_json:
            raise UploadValidationError(
                "同じ識別子で内容が異なるデータがあります。確認してください。"
            )
        return existing, False

    match_key = hashlib.sha256(
        serialize(group_identity).encode("utf-8")
    ).hexdigest()
    pending = VehicleImportPending.query.filter_by(
        company_code=company_code, match_key=match_key, status="pending"
    ).first()
    if pending is None:
        previous = VehicleImportPending.query.filter_by(
            company_code=company_code, match_key=match_key
        ).first()
        if previous is not None:
            raise UploadValidationError(
                "対応済みの車両があります。登録先を再確認してください。"
            )
        pending = find_vehicle_pending_cross_source_group(
            company_code, source_kind, identity
        )
        if pending is None:
            pending = VehicleImportPending(
                id=str(uuid4()), company_code=company_code,
                match_key=match_key, identity_json=serialize(identity),
                created_by_username=username
            )
            db.session.add(pending)
            db.session.flush()

    record = VehicleImportPendingRecord(
        id=str(uuid4()), company_code=company_code,
        pending_id=pending.id, source_kind=source_kind,
        record_key=record_key,
        operation_draft_id=draft.id if source_kind == "operation" else None,
        document_draft_id=draft.id if source_kind != "operation" else None,
        source_record_index=source_record_index,
        record_date=record_date,
        payload_json=payload_json,
        created_by_username=username
    )
    db.session.add(record)
    db.session.flush()
    return record, True


def parse_password_history(value):
    try:
        parsed = json.loads(value or "[]")
    except (TypeError, ValueError):
        return None

    if not isinstance(parsed, list):
        return None

    if not all(
        isinstance(item, str)
        for item in parsed
    ):
        return None

    return parsed

