@app.route("/api/push/vapid-public-key")
def push_vapid_public_key():
    if not VAPID_PUBLIC_KEY:
        return {
            "publicKey": "",
            "error": "VAPID public key is not configured."
        }, 503

    return {
        "publicKey": VAPID_PUBLIC_KEY
    }

@app.route("/api/push/subscribe", methods=["POST"])
def push_subscribe():
    company_code = session.get("company_code")
    username = session.get("username")

    if not company_code or not username:
        return {"error": "Unauthorized"}, 401

    data = request.get_json(silent=True) or {}

    endpoint = str(
        data.get("endpoint") or ""
    ).strip()

    keys = data.get("keys") or {}

    p256dh = str(
        keys.get("p256dh") or ""
    ).strip()

    auth = str(
        keys.get("auth") or ""
    ).strip()

    if not endpoint or not p256dh or not auth:
        return {
            "error": "Invalid push subscription."
        }, 400

    if (
        len(endpoint) > 4000
        or len(p256dh) > 1000
        or len(auth) > 1000
    ):
        return {
            "error": "Push subscription is too large."
        }, 400

    subscription = PushSubscription.query.filter_by(
        endpoint=endpoint
    ).first()

    if subscription:
        subscription.company_code = company_code
        subscription.username = username
        subscription.p256dh = p256dh
        subscription.auth = auth

    else:
        subscription = PushSubscription(
            company_code=company_code,
            username=username,
            endpoint=endpoint,
            p256dh=p256dh,
            auth=auth,
            created_at=datetime.now().strftime(
                "%Y-%m-%d %H:%M:%S"
            )
        )

        db.session.add(subscription)

    db.session.commit()

    return {
        "success": True
    }


@app.route("/api/push/unsubscribe", methods=["POST"])
def push_unsubscribe():
    company_code = session.get("company_code")
    username = session.get("username")

    if not company_code or not username:
        return {"error": "Unauthorized"}, 401

    data = request.get_json(silent=True) or {}
    endpoint = str(
        data.get("endpoint") or ""
    ).strip()

    if not endpoint:
        return {"error": "Invalid push subscription."}, 400

    subscription = PushSubscription.query.filter_by(
        endpoint=endpoint,
        company_code=company_code,
        username=username
    ).first()

    if subscription:
        db.session.delete(subscription)
        db.session.commit()

    return {"success": True}


def send_web_push_notification(
    user,
    title,
    message,
    link=""
):
    if not user:
        return False

    if (
        not VAPID_PRIVATE_KEY
        or not VAPID_PUBLIC_KEY
        or not VAPID_SUBJECT
    ):
        print(
            "Web Push未送信：VAPID設定がありません。"
        )
        return False

    subscriptions = PushSubscription.query.filter_by(
        company_code=user.company_code,
        username=user.username
    ).all()

    if not subscriptions:
        return False

    unread_count = Notification.query.filter(
        Notification.company_code == user.company_code,
        Notification.target_username == user.username,
        Notification.deleted_at.is_(None),
        db.or_(
            Notification.read.is_(False),
            Notification.read.is_(None)
        )
    ).count()

    payload = json.dumps(
        {
            "title": str(title or "")[:200],
            "message": str(message or "")[:10000],
            "link": build_absolute_app_url(link),
            "unread_count": unread_count,
        },
        ensure_ascii=False
    )

    sent = False

    for subscription in subscriptions:
        try:
            webpush(
                subscription_info={
                    "endpoint": subscription.endpoint,
                    "keys": {
                        "p256dh": subscription.p256dh,
                        "auth": subscription.auth,
                    },
                },
                data=payload,
                vapid_private_key=VAPID_PRIVATE_KEY,
                vapid_claims={
                    "sub": VAPID_SUBJECT
                },
                ttl=300,
                timeout=20,
            )

            sent = True

        except WebPushException as e:
            app.logger.warning(
                "Web Push送信エラー: %s",
                e
            )

            response = getattr(
                e,
                "response",
                None
            )

            if (
                response is not None
                and response.status_code in (404, 410)
            ):
                db.session.delete(subscription)
                db.session.commit()

        except Exception:
            app.logger.exception(
                "Web Push送信中に予期しないエラーが発生しました。"
            )

    return sent

@app.route("/api/push/test", methods=["POST"])
def push_test():
    company_code = session.get("company_code")
    username = session.get("username")

    if not company_code or not username:
        return {"success": False, "error": "Unauthorized"}, 401

    user = User.query.filter_by(
        company_code=company_code,
        username=username
    ).first()

    if not user:
        return {"success": False, "error": "User not found"}, 404

    sent = send_web_push_notification(
        user,
        "DKSS テスト通知",
        "端末通知のテストです。",
        "/notifications"
    )

    if not sent:
        return {
            "success": False,
            "error": "Push notification was not sent."
        }, 400

    return {"success": True}

def send_email_notification(
    user,
    title,
    message,
    link="",
    require_opt_in=True
):
    if not user:
        return False

    if require_opt_in and not user.email_notify_enabled:
        return False

    title = str(title or "").strip()

    if (
        not title
        or len(title) > 200
        or "\r" in title
        or "\n" in title
    ):
        return False

    message = str(message or "")

    if len(message) > 10000:
        return False

    if not is_valid_email_address(
        user.email_address
    ):
        return False

    smtp_host = os.environ.get("SMTP_HOST", "")
    try:
        smtp_port = int(
            os.environ.get("SMTP_PORT", "587")
        )
    except (TypeError, ValueError):
        print(
            "メール通知未送信：SMTP_PORTが不正です。"
        )
        return False
    smtp_username = os.environ.get(
        "SMTP_USERNAME",
        ""
    )
    smtp_password = os.environ.get(
        "SMTP_PASSWORD",
        ""
    )
    smtp_from = os.environ.get(
        "SMTP_FROM",
        smtp_username
    )

    if not smtp_host:
        print(
            "メール通知未送信：SMTP設定がありません。"
        )
        return False

    if not is_valid_email_address(smtp_from):
        print(
            "メール通知未送信：SMTP_FROM が不正です。"
        )
        return False

    full_link = build_absolute_app_url(link)

    email = EmailMessage()

    email["Subject"] = title
    email["From"] = smtp_from
    email["To"] = user.email_address

    body = message or ""

    if full_link:
        body += (
            "\n\n"
            "該当画面を開く：\n"
            f"{full_link}"
        )

    email.set_content(body)

    try:
        with smtplib.SMTP(
            smtp_host,
            smtp_port,
            timeout=20
        ) as server:
            server.starttls()

            if smtp_username:
                server.login(
                    smtp_username,
                    smtp_password
                )

            server.send_message(email)

        return True

    except Exception:
        app.logger.exception(
            "メール通知送信中に予期しないエラーが発生しました。"
        )
        return False
def dispatch_external_notification(
    user,
    title,
    message,
    link="",
    notification_id=None
):
    if not user:
        return

    push_link = link

    if notification_id is not None:
        if str(link or "").strip():
            push_link = f"/notifications/{notification_id}/open"
        else:
            push_link = f"/notifications/{notification_id}"

    send_web_push_notification(
        user,
        title,
        message,
        push_link
    )

    if user.email_notify_enabled:
        send_email_notification(
            user,
            title,
            message,
            link
        )

def build_notification_workflow_context(
    result_record,
    result_type,
    action,
    approval_index=None
):
    latest_event = ChecklistEvent.query.filter_by(
        company_code=result_record.company_code,
        result_type=result_type,
        result_id=result_record.id
    ).order_by(
        ChecklistEvent.id.desc()
    ).first()

    context = {
        "result_type": result_type,
        "result_id": result_record.id,
        "action": action,
        "event_id": latest_event.id if latest_event else 0,
    }

    if approval_index is not None:
        context["approval_index"] = approval_index

    return context

def add_notification(
    target_user,
    title,
    message,
    link="",
    files=None,
    company_code=None,
    target_username=None,
    workflow_context=None
):
    target_user = str(target_user or "").strip()
    title = str(title or "").strip()
    message = str(message or "")

    if not target_user:
        return

    if len(target_user) > 100:
        return

    if not title or len(title) > 200:
        return

    if len(message) > 10000:
        return

    if target_username is not None:
        target_username = str(
            target_username
        ).strip()

        if len(target_username) > 50:
            return

    notification_company_code = (
        company_code
        or session.get("company_code")
    )

    link = str(link or "").strip()

    if (
        len(link) > 200
        or (
            link
            and (
                not link.startswith("/")
                or link.startswith("//")
                or "\\" in link
                or "\r" in link
                or "\n" in link
            )
        )
    ):
        link = ""

    target_user_record = None

    if target_username:
        target_user_record = User.query.filter_by(
            company_code=notification_company_code,
            username=target_username
        ).first()

        if not target_user_record:
            return

        target_user = (
            f"{target_user_record.last_name or ''}"
            f"{target_user_record.first_name or ''}"
        )
        target_username = target_user_record.username

    notification = Notification(
        company_code=notification_company_code,
        target_user=target_user,
        target_username=target_username,
        title=title,
        message=message,
        link=link,
        files_json=json.dumps(
            files or [],
            ensure_ascii=False
        ),
        workflow_context_json=json.dumps(
            workflow_context
            if isinstance(workflow_context, dict)
            else {},
            ensure_ascii=False
        ),
        read=False,
        created_at=datetime.now(ZoneInfo("UTC")).strftime(
            "%Y-%m-%dT%H:%M:%SZ"
        )
    )

    db.session.add(notification)
    db.session.commit()

    if target_user_record:
        dispatch_external_notification(
            target_user_record,
            title,
            message,
            link,
            notification_id=notification.id
        )

def build_absolute_app_url(link=""):
    link = str(link or "").strip()

    if not link:
        return ""

    if (
        not link.startswith("/")
        or link.startswith("//")
        or "\\" in link
        or "\r" in link
        or "\n" in link
    ):
        return ""

    base_url = os.environ.get(
        "APP_BASE_URL",
        "https://dkss.onrender.com"
    ).rstrip("/")

    return base_url + link

def add_news(
    title,
    message,
    files=None,
    target_type="",
    target_value="",
    company_code=None
):
    title = str(title or "").strip()
    message = str(message or "")
    target_type = str(target_type or "").strip()
    target_value = str(target_value or "").strip()

    if not title or len(title) > 200:
        return

    if len(message) > 10000:
        return

    if len(target_type) > 50:
        return

    if len(target_value) > 100:
        return

    news_company_code = (
        company_code
        or session.get("company_code")
    )

    if not news_company_code:
        raise ValueError(
            "News company_code is required."
        )

    news = News(
        company_code=news_company_code,
        title=title,
        message=message,
        files_json=json.dumps(
            files or [],
            ensure_ascii=False
        ),
        target_type=target_type,
        target_value=target_value,
        created_at=datetime.now().strftime(
            "%Y-%m-%d %H:%M"
        )
    )

    db.session.add(news)
    db.session.flush()

    add_audit_log(
        action="news_created",
        target_type="news",
        target_id=news.id,
        detail=f"お知らせ作成: {news.title}",
        company_code=news.company_code,
    )

    db.session.commit()


def notify_mentions(text, link=""):
    if not text:
        return

    users = User.query.filter_by(
        company_code=session.get("company_code")
    ).all()

    users_by_name = {}

    for user in users:
        full_name = (
            f"{user.last_name or ''}"
            f"{user.first_name or ''}"
        )

        if not full_name or not user.username:
            continue

        users_by_name.setdefault(
            full_name,
            []
        ).append(user)

    notified_usernames = set()

    for user in users:
        name = (
            f"{user.last_name or ''}"
            f"{user.first_name or ''}"
        )
        username = user.username

        if not name or not username:
            continue

        stable_tag = f"[[{username}|{name}]]"

        if stable_tag in text:
            add_notification(
                name,
                "メンションされました",
                text,
                link,
                target_username=username
            )
            notified_usernames.add(username)
            continue

        name_matches = users_by_name.get(
            name,
            []
        )

        if len(name_matches) != 1:
            continue

        legacy_mention = "@" + name
        legacy_tag = f"[[{name}]]"

        if (
            legacy_mention in text
            or legacy_tag in text
        ):
            if username in notified_usernames:
                continue

            add_notification(
                name,
                "メンションされました",
                text,
                link,
                target_username=username
            )
            notified_usernames.add(username)

def is_same_company_result(result):
    company_code = result.get("company_code")
    return company_code == session.get("company_code")


def can_view_patrol_result(result):
    role = session.get("role")

    if role in ["itc", "admin"]:
        return is_same_company_result(result)

    if not is_same_company_result(result):
        return False

    if result.get("target_type") == "delivery_place":
        return True

    if result.get("created_by_username") == session.get("username"):
        return True

    return (
        result.get("target_type") == "user"
        and result.get("target_username")
        == session.get("username")
    )


def can_edit_patrol_result(result):
    if not is_same_company_result(result):
        return False

    if session.get("role") in ["admin", "itc"]:
        return True

    return (
        result.get("created_by_username")
        == session.get("username")
    )


def can_countermeasure_patrol_result(result):
    if not is_same_company_result(result):
        return False

    if session.get("role") in ["admin", "itc"]:
        return True

    # 作成者
    if (
        result.get("created_by_username")
        == session.get("username")
    ):
        return True

    # 個人対象なら対象本人
    return (
        result.get("target_type") == "user"
        and result.get("target_username")
        == session.get("username")
    )


def can_delete_patrol_result(result):
    return can_edit_patrol_result(result)


def can_approve_patrol_result(result):
    if not is_same_company_result(result):
        return False

    return session.get("role") in ["admin", "itc"]


def can_view_checklist_result(result):
    role = session.get("role")

    if not is_same_company_result(result):
        return False

    if role in ["admin", "itc"]:
        return True

    if (
        result.get("checked_by_username")
        == session.get("username")
    ):
        return True

    if (
        result.get("target_type") == "user"
        and result.get("target_username")
        == session.get("username")
    ):
        return True

    # Reading the result and its attachments must be possible before approving it.
    # Preserve access for selected/previous approvers after the workflow advances.
    if role != "user":
        return False
    approvals = result.get("approvals") or []
    checklist = result.get("checklist_snapshot") or {}
    if not checklist and result.get("checklist_id"):
        record = Checklist.query.filter_by(
            id=result["checklist_id"], company_code=result["company_code"]
        ).first()
        if record:
            checklist = checklist_to_dict(record)
    definitions = [item for item in checklist.get("items", [])
                   if item.get("item_type") == "approval"]
    if not approvals:
        approvals = [{} for _ in definitions]
    approvals = [
        dict(approval, allow_general=approval.get(
            "allow_general",
            definitions[index].get("approval_allow_general", False)
            if index < len(definitions) else False,
        ))
        for index, approval in enumerate(approvals)
    ]
    username = session.get("username")
    if any(
        username and (
            approval.get("approved_by_username") == username
            or (approval.get("allow_general")
                and username in (approval.get("candidate_usernames") or []))
        )
        for approval in approvals
    ):
        return True
    current = next((approval for approval in approvals
                    if not (approval.get("approved_by")
                            or approval.get("approved_by_username"))), None)
    return (result.get("status") == "承認待ち"
            and can_approve_checklist_result(result, current))


def can_manage_checklist_result(result):
    role = session.get("role")

    if not is_same_company_result(result):
        return False

    if role in ["admin", "itc"]:
        return True

    return (
        result.get("checked_by_username")
        == session.get("username")
    )


def can_approve_checklist_result(result, approval=None):
    if not is_same_company_result(result):
        return False

    if not approval:
        return False

    approval_user = User.query.filter_by(
        company_code=result.get("company_code"),
        username=session.get("username")
    ).first()

    if not approval_user:
        return False

    if approval_user.role == "admin":
        return True

    return (
        approval.get("allow_general", False)
        and approval_user.role == "user"
    )


def can_reject_checklist_result(result, approval=None):
    if not is_same_company_result(result):
        return False

    if not approval:
        return False

    approval_user = User.query.filter_by(
        company_code=result.get("company_code"),
        username=session.get("username")
    ).first()

    if not approval_user:
        return False

    if approval_user.role == "admin":
        return True

    return (
        approval.get("allow_general", False)
        and approval_user.role == "user"
    )

