def send_mfa_code_email(user, code):
    if not user or not user.email_address:
        return False

    return send_email_notification(
        user=user,
        title="ログイン認証コード",
        message=(
            "ログイン認証コードは以下です。\n\n"
            f"{code}\n\n"
            "このコードの有効期限は10分です。"
        ),
        require_opt_in=False,
    )

def is_valid_email_address(value):
    value = str(value or "").strip()

    if (
        not value
        or len(value) > 255
        or "\r" in value
        or "\n" in value
    ):
        return False

    _, parsed_address = parseaddr(value)

    if parsed_address != value:
        return False

    if "@" not in parsed_address:
        return False

    local_part, domain = parsed_address.rsplit("@", 1)

    return bool(
        local_part
        and domain
        and "." in domain
    )

def send_email_change_code_email(
    email_address,
    code
):
    if not is_valid_email_address(
        email_address
    ):
        return False

    smtp_host = os.environ.get("SMTP_HOST", "")
    try:
        smtp_port = int(
            os.environ.get("SMTP_PORT", "587")
        )
    except (TypeError, ValueError):
        print(
            "メールアドレス変更確認メール未送信：SMTP_PORTが不正です。"
        )
        return False
    smtp_username = os.environ.get(
        "SMTP_USERNAME",
        ""
    )
    smtp_password = os.environ.get(
        "SMTP_PASSWORD",
        ""
    )
    smtp_from = os.environ.get(
        "SMTP_FROM",
        smtp_username
    )

    if not smtp_host:
        return False

    if not is_valid_email_address(smtp_from):
        return False

    email = EmailMessage()

    email["Subject"] = "メールアドレス変更確認コード"
    email["From"] = smtp_from
    email["To"] = email_address

    email.set_content(
        "メールアドレス変更確認コードは以下です。\n\n"
        f"{code}\n\n"
        "このコードの有効期限は10分です。"
    )

    try:
        with smtplib.SMTP(
            smtp_host,
            smtp_port,
            timeout=20
        ) as server:
            server.starttls()

            if smtp_username:
                server.login(
                    smtp_username,
                    smtp_password
                )

            server.send_message(email)

        return True

    except Exception:
        app.logger.exception(
            "メールアドレス変更確認メール送信中に予期しないエラーが発生しました。"
        )
        return False
def create_email_change_code(
    user,
    new_email_address
):
    code = f"{secrets.randbelow(1000000):06d}"

    user.pending_email_address = new_email_address

    user.email_change_code_hash = (
        generate_password_hash(code)
    )

    user.email_change_code_expires_at = (
        datetime.now() + timedelta(minutes=10)
    ).strftime("%Y-%m-%d %H:%M:%S")

    return code
        
def create_mfa_code(user):
    now = datetime.now()

    if user.mfa_code_sent_at:
        try:
            last_sent_at = datetime.strptime(
                user.mfa_code_sent_at,
                "%Y-%m-%d %H:%M:%S"
            )

            if (
                now - last_sent_at
                < timedelta(seconds=60)
            ):
                return None

        except ValueError:
            pass

    code = f"{secrets.randbelow(1000000):06d}"

    user.mfa_code_hash = generate_password_hash(
        code
    )

    user.mfa_code_expires_at = (
        now + timedelta(minutes=10)
    ).strftime("%Y-%m-%d %H:%M:%S")

    user.mfa_code_sent_at = now.strftime(
        "%Y-%m-%d %H:%M:%S"
    )

    db.session.commit()

    return code

@app.route("/login/csrf-token", methods=["GET"])
def login_csrf_token():
    from flask_wtf.csrf import generate_csrf

    response = jsonify({
        "csrf_token": generate_csrf()
    })
    response.headers["Cache-Control"] = "no-store"
    return response


@app.route("/login", methods=["GET", "POST"])
@limiter.limit("10 per minute", methods=["POST"])
def login():
    error = None

    if request.method == "GET" and session.get("username"):
        if session.get("role") == "itc":
            return redirect("/itc")

        return redirect("/")

    if request.method == "POST":
        company_code = request.form.get(
            "company_code",
            ""
        ).strip()
        username = request.form.get(
            "username",
            ""
        ).strip()
        password = request.form.get(
            "password",
            ""
        )

        if (
            len(company_code) > 50
            or len(username) > 50
            or len(password) > 255
        ):
            error = (
                "会社コード、ユーザーID、"
                "またはパスワードが違います。"
            )
            return render_template(
                "login.html",
                error=error
            )

        matching_company_codes = (
            db.session.query(User.company_code)
            .filter(
                db.func.lower(User.company_code)
                == company_code.lower()
            )
            .distinct()
            .limit(2)
            .all()
        )

        if len(matching_company_codes) > 1:
            return render_template(
                "login.html",
                error=(
                    "会社コードを特定できません。"
                    "管理者へお問い合わせください。"
                )
            )

        if matching_company_codes:
            company_code = matching_company_codes[0][0]

        user = User.query.filter_by(
            company_code=company_code,
            username=username
        ).first()

        if user and user.login_locked:
            error = (
                "アカウントがロックされています。"
                "管理者へお問い合わせください。"
            )

        elif user and check_password_hash(
            user.password,
            password
        ):

            now = datetime.now()

            if user.last_login_at:
                try:
                    last_login_at = datetime.strptime(
                        user.last_login_at,
                        "%Y-%m-%d %H:%M:%S"
                    )

                    if (
                        now - last_login_at
                        >= timedelta(days=90)
                    ):
                        user.login_locked = True

                        add_audit_log(
                            action="account_locked",
                            target_type="user",
                            target_id=user.username,
                            detail="90日以上未使用によるアカウントロック",
                            company_code=user.company_code,
                            username=user.username,
                        )

                        db.session.commit()

                        return render_template(
                            "login.html",
                            error=(
                                "90日以上ログインがなかったため、"
                                "アカウントがロックされました。"
                                "管理者へお問い合わせください。"
                            )
                        )

                except ValueError:
                    pass

            user.failed_login_count = 0

            password_expired = False

            if user.password_changed_at:
                try:
                    password_changed_at = datetime.strptime(
                        user.password_changed_at,
                        "%Y-%m-%d %H:%M:%S"
                    )

                    password_expired = (
                        datetime.now() - password_changed_at
                        >= timedelta(days=90)
                    )

                except ValueError:
                    password_expired = True
            else:
                # 既存ユーザーは導入時点から90日を数える
                user.password_changed_at = datetime.now().strftime(
                    "%Y-%m-%d %H:%M:%S"
                )

            db.session.commit()

            company = get_company(user.company_code)
            if (
                user.role != "itc"
                and (
                    not company
                    or not company.active
                )
            ):
                return render_template(
                    "login.html",
                    error=(
                        "この会社は現在利用停止中です。"
                        "ITCへお問い合わせください。"
                    )
                )

            if not MFA_ENABLED:
                user.last_login_at = datetime.now().strftime(
                    "%Y-%m-%d %H:%M:%S"
                )

                add_audit_log(
                    action="login_success",
                    target_type="user",
                    target_id=user.username,
                    detail="パスワード認証成功（MFA一時無効）",
                    company_code=user.company_code,
                    username=user.username,
                )

                update_company_usage_summary(
                    user.company_code,
                    increment_login=True
                )
                
                db.session.commit()

                session.clear()
                session.permanent = True
                session["company_code"] = user.company_code
                session["username"] = user.username
                session["role"] = user.role
                session["name"] = (
                    f"{user.last_name or ''}"
                    f"{user.first_name or ''}"
                )
                session["office"] = user.office

                session["password_changed_at"] = (
                    user.password_changed_at
                )
                session["password_expired"] = password_expired

                if password_expired:
                    return redirect("/settings")

                if user.role == "itc":
                    return redirect("/itc")

                return redirect("/")
          
            code = create_mfa_code(user)
            if code is None:
                return render_template(
                    "login.html",
                    error=(
                        "認証コードは60秒に1回まで送信できます。"
                        "少し待ってからもう一度お試しください。"
                    )
                )
            if not send_mfa_code_email(user, code):
                user.mfa_code_hash = None
                user.mfa_code_expires_at = None
                user.mfa_code_sent_at = None
                db.session.commit()

                return render_template(
                    "login.html",
                    error=(
                        "認証コードを送信できませんでした。"
                        "登録メールアドレスまたは"
                        "メール設定を確認してください。"
                    )
                )

            session.clear()
            session.permanent = True
            session["mfa_pending_company_code"] = (
                user.company_code
            )
            session["mfa_pending_username"] = (
                user.username
            )
            session["mfa_password_expired"] = (
                password_expired
            )
            session["mfa_password_changed_at"] = (
                user.password_changed_at
            )
            session["mfa_attempts"] = 0

            return redirect("/mfa")
            
        else:
            if user:
                user.failed_login_count = (
                    user.failed_login_count or 0
                ) + 1

                if user.failed_login_count >= 10:
                    user.login_locked = True

                    add_audit_log(
                        action="account_locked",
                        target_type="user",
                        target_id=user.username,
                        detail="パスワード認証10回失敗によるアカウントロック",
                        company_code=user.company_code,
                        username=user.username,
                    )

            add_audit_log(
                action="login_failed",
                target_type="user",
                target_id=username,
                detail="パスワード認証失敗",
                company_code=company_code,
                username=username,
            )

            db.session.commit()

            error = (
                "会社コード、ユーザーID、"
                "またはパスワードが違います。"
            )

    return render_template("login.html", error=error)

@app.route("/mfa", methods=["GET", "POST"])
@limiter.limit("5 per minute", methods=["POST"])
def mfa():
    company_code = session.get(
        "mfa_pending_company_code"
    )
    username = session.get(
        "mfa_pending_username"
    )

    if not company_code or not username:
        return redirect("/login")

    user = User.query.filter_by(
        company_code=company_code,
        username=username
    ).first()

    if not user or user.login_locked:
        session.clear()
        return redirect("/login")

    if user.role != "itc":
        company = Company.query.filter_by(
            company_code=user.company_code
        ).first()

        if not company or not company.active:
            session.clear()
            return redirect("/login")

    if (
        session.get("mfa_password_changed_at")
        != user.password_changed_at
    ):
        session.clear()
        return redirect("/login")
    
    error = None

    if request.method == "POST":
        code = request.form.get(
            "code",
            ""
        ).strip()

        if (
            not user.mfa_code_hash
            or not user.mfa_code_expires_at
        ):
            error = "認証コードが無効です。"

        else:
            try:
                expires_at = datetime.strptime(
                    user.mfa_code_expires_at,
                    "%Y-%m-%d %H:%M:%S"
                )
            except ValueError:
                expires_at = datetime.min

            if datetime.now() > expires_at:
                user.mfa_code_hash = None
                user.mfa_code_expires_at = None
                db.session.commit()

                session.clear()

                return render_template(
                    "login.html",
                    error=(
                        "認証コードの有効期限が切れています。"
                        "もう一度ログインしてください。"
                    )
                )

            elif (
                len(code) != 6
                or not code.isdigit()
                or not check_password_hash(
                    user.mfa_code_hash,
                    code
                )
            ):
                attempts = (
                    session.get("mfa_attempts", 0) + 1
                )
                session["mfa_attempts"] = attempts

                add_audit_log(
                    action="mfa_failed",
                    target_type="user",
                    target_id=user.username,
                    detail=f"MFA認証失敗 {attempts}回目",
                    company_code=user.company_code,
                    username=user.username,
                )

                db.session.commit()

                if attempts >= 5:
                    user.mfa_code_hash = None
                    user.mfa_code_expires_at = None

                    add_audit_log(
                        action="mfa_code_invalidated",
                        target_type="user",
                        target_id=user.username,
                        detail="MFA認証5回失敗による認証コード無効化",
                        company_code=user.company_code,
                        username=user.username,
                    )

                    db.session.commit()

                    session.clear()

                    return render_template(
                        "login.html",
                        error=(
                            "認証コードを5回間違えたため、"
                            "認証コードを無効化しました。"
                            "もう一度ログインしてください。"
                        )
                    )

                error = (
                    "認証コードが違います。"
                    f"あと{5 - attempts}回入力できます。"
                )

            else:
                password_expired = session.get(
                    "mfa_password_expired",
                    False
                )

                user.mfa_code_hash = None
                user.mfa_code_expires_at = None
                user.last_login_at = datetime.now().strftime(
                    "%Y-%m-%d %H:%M:%S"
                )

                add_audit_log(
                    action="login_success",
                    target_type="user",
                    target_id=user.username,
                    detail="MFA認証成功",
                    company_code=user.company_code,
                    username=user.username,
                )

                update_company_usage_summary(
                    user.company_code,
                    increment_login=True
                )

                db.session.commit()

                session.clear()
                session.permanent = True
                session["company_code"] = user.company_code
                session["username"] = user.username
                session["role"] = user.role
                session["name"] = (
                    f"{user.last_name or ''}"
                    f"{user.first_name or ''}"
                )
                session["office"] = user.office
                session["password_changed_at"] = (
                    user.password_changed_at
                )
                session["password_expired"] = (
                    password_expired
                )

                if password_expired:
                    return redirect("/settings")

                if user.role == "itc":
                    return redirect("/itc")

                return redirect("/")

    return render_template(
        "mfa.html",
        error=error
    )

@app.route("/itc/news/new", methods=["GET", "POST"])
@limiter.limit("10 per minute", methods=["POST"])
def itc_new_news():
    if not require_itc():
        return redirect("/")

    company_code = session.get("company_code")

    if request.method == "POST":
        form_errors = []
        form_error_status = 400

        title = request.form.get("title", "").strip()
        message = request.form.get("message", "")

        if not title:
            form_errors.append((
                "タイトルを入力してください。",
                "title"
            ))
        elif len(title) > 200:
            form_errors.append((
                "タイトルは200文字以内で入力してください。",
                "title"
            ))

        if len(message) > 10000:
            form_errors.append((
                "本文は10000文字以内で入力してください。",
                "message_editor"
            ))

        target_type = request.form.get("target_type")
        target_value = request.form.get("target_value", "").strip()

        # =========================
        # 通知対象を現在の会社内だけに限定
        # =========================

        user_query = User.query.filter_by(
            company_code=company_code
        )

        target_users = []

        if target_type == "all":
            target_users = user_query.all()

        elif target_type == "admins":
            target_users = user_query.filter_by(
                role="admin"
            ).all()

        elif target_type == "company":
            # 他社コードをPOSTされても無視する
            if target_value != company_code:
                form_errors.append((
                    "対象会社が不正です。",
                    "target_company"
                ))
                form_error_status = 403
            else:
                target_users = user_query.all()

        elif target_type == "office":
            valid_office = Office.query.filter_by(
                company_code=company_code,
                name=target_value
            ).first()

            if not valid_office:
                form_errors.append((
                    "対象営業所が不正です。",
                    "target_office"
                ))
                form_error_status = 403
            else:
                target_users = user_query.filter_by(
                    office=target_value
                ).all()

        elif target_type == "user":
            target_user = User.query.filter_by(
                company_code=company_code,
                username=target_value
            ).first()

            if not target_user:
                form_errors.append((
                    "対象ユーザーが不正です。",
                    "target_user_search"
                ))
                form_error_status = 403
            else:
                target_users = [target_user]

        else:
            form_errors.append((
                "通知対象が不正です。",
                "target_type"
            ))

        if form_errors:
            return return_form_errors(
                form_errors,
                form_error_status
            )

        file_names = []

        uploaded_files = [
            file
            for file in request.files.getlist("files")
            if file and file.filename
        ]

        for file in uploaded_files:
            original_filename = os.path.basename(
                str(file.filename or "")
            )

            extension = os.path.splitext(
                original_filename
            )[1].lower()

            if (
                extension not in ALLOWED_UPLOAD_EXTENSIONS
                or not is_valid_uploaded_file(
                    file,
                    extension
                )
            ):
                return "添付ファイルの検証に失敗しました。", 400

        for file in uploaded_files:
            filename = save_uploaded_file(file)

            if filename:
                file_names.append(filename)

        # =========================
        # News登録
        # =========================

        add_news(
            title,
            message,
            files=file_names,
            target_type=target_type,
            target_value=target_value
        )

        # =========================
        # 通知登録
        # =========================

        for user in target_users:
            add_notification(
                (
                    f"{user.last_name or ''}"
                    f"{user.first_name or ''}"
                ),
                title,
                message,
                "",
                files=file_names,
                company_code=company_code,
                target_username=user.username
            )

        notify_mentions(
            message,
            "/notifications"
        )

        return redirect("/itc")

    # =========================
    # GET
    # =========================

    company = Company.query.filter_by(
        company_code=company_code
    ).first()

    companies = [company] if company else []

    users = User.query.filter(
        User.company_code == company_code,
        User.role != "itc"
    ).all()

    return render_template(
        "itc_news_form.html",
        companies=companies,
        offices=offices_for_current_company(),
        users=users,
        news=None,
        mode="new"
    )

