@app.route("/api/mention-users")
def mention_users():
    keyword = request.args.get("q", "").strip()

    if len(keyword) > 100:
        return {"users": []}, 400

    if not keyword:
        return {"users": []}

    user_query = User.query.filter_by(
        company_code=session.get("company_code")
    )

    if request.args.get("exact_username") == "1":
        user_query = user_query.filter(
            User.username == keyword
        )
    elif keyword:
        keyword_like = f"%{keyword}%"

        user_query = user_query.filter(
            db.or_(
                User.last_name.ilike(keyword_like),
                User.first_name.ilike(keyword_like),
                User.username.ilike(keyword_like),
                (
                    db.func.coalesce(User.last_name, "")
                    + db.func.coalesce(User.first_name, "")
                ).ilike(keyword_like)
            )
        )

    approval_scope = request.args.get("approval_scope", "")
    if approval_scope == "admin":
        user_query = user_query.filter(User.role == "admin")
    elif approval_scope == "admin_user":
        user_query = user_query.filter(User.role.in_(["admin", "user"]))

    matched_users = (
        user_query
        .order_by(
            User.last_name.asc(),
            User.first_name.asc()
        )
        .limit(5)
        .all()
    )

    users = [
        {
            "name": (
                f"{user.last_name or ''}"
                f"{user.first_name or ''}"
            ),
            "username": user.username,
            "office": user.office or "",
            "role": user.role or "user"
        }
        for user in matched_users
    ]

    return {"users": users}

@app.route("/api/vehicles")
def search_vehicles():

    keyword = request.args.get("q", "").strip()

    if len(keyword) > 100:
        return {"results": []}, 400

    company_code = session.get("company_code")

    query = Vehicle.query.filter_by(
        company_code=company_code,
        deleted=False
    )
    normalized = normalize_vehicle_operation_plate(keyword)
    vehicles = []
    # Match the whole displayed registration as well as individual attributes.
    # Apply the result limit after matching so later vehicle IDs remain searchable.
    candidates = query.order_by(Vehicle.id.asc()).yield_per(200)
    for vehicle in candidates:
        plate = ''.join(str(value or '') for value in (
            vehicle.plate_area, vehicle.plate_class,
            vehicle.plate_kana, vehicle.plate_number,
        ))
        values = (plate, vehicle.chassis_number, vehicle.model_code, vehicle.manufacturer)
        if normalized and not any(
            normalized in normalize_vehicle_operation_plate(value) for value in values
        ):
            continue
        vehicles.append(vehicle)
        if len(vehicles) == 20:
            break

    results = []

    for vehicle in vehicles:

        number = " ".join(
            value
            for value in [
                vehicle.plate_area or "",
                vehicle.plate_class or "",
                vehicle.plate_kana or "",
                vehicle.plate_number or "",
            ]
            if value
        )

        results.append({
            "id": vehicle.id,
            "vehicle_record_id": vehicle.id,
            "number": number,
            "chassis_number": vehicle.chassis_number or "",
            "manufacturer": vehicle.manufacturer or "",
            "model_code": vehicle.model_code or "",
        })

    return {
        "results": results
    }

