@app.route("/safety")
def safety():
    return redirect("/pointouts")

@app.route("/pointouts")
def pointouts():
    role = session.get("role")

    view_type = request.args.get("type", "user")
    if view_type not in PATROL_VIEW_TYPES:
        view_type = "user"

    keyword = request.args.get("keyword", "").strip()
    office_filter = request.args.get("office", "").strip()
    status_filter = request.args.get("status", "").strip()
    category = request.args.get("category", "").strip()
    date_from = request.args.get("date_from", "").strip()
    date_to = request.args.get("date_to", "").strip()
    mine = request.args.get("mine") == "1"
    pending = request.args.get("pending") == "1"

    if len(keyword) > 100:
        return "検索条件が長すぎます。", 400

    for date_value in [date_from, date_to]:
        if not date_value:
            continue

        try:
            datetime.strptime(
                date_value,
                "%Y-%m-%d"
            )
        except ValueError:
            return "発生日の検索条件が不正です。", 400

    if (
        date_from
        and date_to
        and date_from > date_to
    ):
        return "発生日の開始日と終了日が不正です。", 400

    query = PatrolResult.query.filter(
        PatrolResult.company_code == session.get("company_code"),
        PatrolResult.target_type == view_type
    )

    if office_filter:
        query = query.filter(
            PatrolResult.office == office_filter
        )

    if status_filter == "not_started":
        query = query.filter(
            PatrolResult.category != "Good",
            PatrolResult.countermeasure == ""
        )
    elif status_filter == "waiting":
        query = query.filter(
            PatrolResult.category != "Good",
            PatrolResult.countermeasure != "",
            PatrolResult.approval_status == "承認待ち"
        )
    elif status_filter == "rejected":
        query = query.filter(
            PatrolResult.category != "Good",
            PatrolResult.approval_status == "差し戻し"
        )
    elif status_filter == "approved":
        query = query.filter(
            PatrolResult.category != "Good",
            PatrolResult.approval_status == "承認済み"
        )
    elif status_filter == "none":
        query = query.filter(
            PatrolResult.category == "Good"
        )

    if mine and view_type == "user":
        query = query.filter(
            PatrolResult.target_username
            == session.get("username")
        )

    if pending:
        query = query.filter(
            PatrolResult.category != "Good",
            PatrolResult.approval_status != "承認済み"
        )

    if category:
        query = query.filter(
            PatrolResult.category == category
        )

    if date_from:
        query = query.filter(
            PatrolResult.date >= date_from
        )

    if date_to:
        query = query.filter(
            PatrolResult.date <= date_to
        )

    if keyword:
        keyword_like = f"%{keyword}%"

        keyword_filters = [
            PatrolResult.office.ilike(keyword_like),
            PatrolResult.content.ilike(keyword_like),
            PatrolResult.content_type.ilike(keyword_like),
        ]

        if view_type == "user":
            keyword_filters.append(
                PatrolResult.target_user.ilike(keyword_like)
            )
        elif view_type == "delivery_place":
            keyword_filters.append(
                PatrolResult.delivery_place.ilike(keyword_like)
            )

        query = query.filter(
            or_(*keyword_filters)
        )

    result_records = query.order_by(
        PatrolResult.id.desc()
    ).all()

    visible_results = []

    for result_record in result_records:
        result = patrol_result_to_dict(result_record)

        if not can_view_patrol_result(result):
            continue

        result["can_manage"] = can_edit_patrol_result(result)
        visible_results.append(result)

    # 現在のタブの全記録を、閲覧権限に従って集計する
    # ページ分割やステータス絞り込みの影響を受けない
    summary_records = PatrolResult.query.filter(
        PatrolResult.company_code == session.get("company_code"),
        PatrolResult.target_type == view_type
    ).all()

    patrol_stats = {
        "total": 0,
        "waiting": 0,
        "approved": 0,
        "not_started": 0,
        "rejected": 0,
        "none": 0
    }

    for summary_record in summary_records:
        summary_item = patrol_result_to_dict(summary_record)

        if not can_view_patrol_result(summary_item):
            continue

        patrol_stats["total"] += 1

        if summary_item.get("category") == "Good":
            patrol_stats["none"] += 1
            continue

        if not summary_item.get("countermeasure"):
            patrol_stats["not_started"] += 1
        elif summary_item.get("approval_status") == "承認待ち":
            patrol_stats["waiting"] += 1
        elif summary_item.get("approval_status") == "承認済み":
            patrol_stats["approved"] += 1
        elif summary_item.get("approval_status") == "差し戻し":
            patrol_stats["rejected"] += 1
        else:
            patrol_stats["not_started"] += 1

    allowed_page_sizes = {5, 8, 10, 20, 50}

    try:
        page_size = int(
            request.args.get(
                "page_size",
                "10"
            )
        )
    except ValueError:
        page_size = 10

    if page_size not in allowed_page_sizes:
        page_size = 10

    try:
        page = max(
            int(
                request.args.get(
                    "page",
                    "1"
                )
            ),
            1
        )
    except ValueError:
        page = 1

    total_results = len(
        visible_results
    )

    total_pages = max(
        1,
        (
            total_results
            + page_size
            - 1
        ) // page_size
    )

    if page > total_pages:
        page = total_pages

    start_index = (
        page - 1
    ) * page_size

    paginated_results = (
        visible_results[
            start_index:
            start_index + page_size
        ]
    )

    driver_options = Driver.query.filter(
        Driver.company_code == session.get("company_code")
    ).order_by(
        Driver.name.asc()
    ).all()

    return render_template(
        "pointouts.html",
        patrol_results=paginated_results,
        patrol_stats=patrol_stats,
        total_results=total_results,
        page=page,
        page_size=page_size,
        total_pages=total_pages,
        view_type=view_type,
        keyword=keyword,
        office_filter=office_filter,
        status_filter=status_filter,
        category_filter=category,
        date_from=date_from,
        date_to=date_to,
        role=role,
        show_target_user=view_type == "user",
        drivers=driver_options,
        offices=offices_for_current_company(),
        delivery_places=delivery_places_for_current_company(),
    )


@app.route("/pointouts/new", methods=["GET", "POST"])
@limiter.limit("20 per minute", methods=["POST"])
def new_pointout():
    if request.method == "POST":
        company_code = session.get("company_code")
        form_errors = []

        target_type = request.form.get(
            "target_type",
            ""
        ).strip()

        target_user = request.form.get(
            "target_user",
            ""
        ).strip()
        target_username = ""

        delivery_place = request.form.get(
            "delivery_place",
            ""
        ).strip()

        content_type = request.form.get(
            "content_type",
            ""
        ).strip()

        category = request.form.get(
            "category",
            ""
        ).strip()

        content = request.form.get(
            "content",
            ""
        ).strip()

        date = request.form.get(
            "date",
            ""
        ).strip()
        if category not in {
            "安全",
            "品質",
            "Good"
        }:
            form_errors.append((
                "分類が不正です。",
                "category"
            ))

        if not date:
            form_errors.append((
                "発生日を入力してください。",
                "event_date"
            ))
        else:
            try:
                datetime.strptime(
                    date,
                    "%Y-%m-%d"
                )
            except ValueError:
                form_errors.append((
                    "発生日が不正です。",
                    "event_date"
                ))
        # =========================
        # 対象種別検証
        # =========================

        if target_type not in PATROL_VIEW_TYPES:
            form_errors.append((
                "対象種別が不正です。",
                "target_type"
            ))

        target_office = session.get("office") or ""

        # =========================
        # 対象ユーザー検証
        # =========================

        if target_type == "user":
            if not target_user:
                form_errors.append((
                    "対象ユーザーを選択してください。",
                    "target_user_search"
                ))
            else:
                target_driver = Driver.query.filter_by(
                    company_code=company_code,
                    employee_id=target_user
                ).first()

                if not target_driver:
                    form_errors.append((
                        "対象ユーザーが不正です。",
                        "target_user_search"
                    ))
                else:
                    target_user_record = User.query.filter_by(
                        company_code=company_code,
                        username=target_driver.employee_id
                    ).first()

                    if not target_user_record:
                        form_errors.append((
                            "対象ユーザー情報が不正です。",
                            "target_user_search"
                        ))
                    else:
                        target_username = target_user_record.username
                        target_user = target_driver.name
                        target_office = target_driver.office or ""

            delivery_place = ""

        # =========================
        # 納入先検証
        # =========================

        elif target_type == "delivery_place":
            if not delivery_place:
                form_errors.append((
                    "納入先を選択してください。",
                    "delivery_place"
                ))

            if delivery_place:
                valid_delivery_place = DeliveryPlace.query.filter_by(
                    company_code=company_code,
                    name=delivery_place
                ).first()

                if not valid_delivery_place:
                    form_errors.append((
                        "納入先が不正です。",
                        "delivery_place"
                    ))

            target_user = ""

        # =========================
        # 内容区分検証
        # =========================

        if content_type:
            valid_content_type = PatrolContentType.query.filter_by(
                company_code=company_code,
                name=content_type
            ).first()

            if not valid_content_type:
                form_errors.append((
                    "内容区分が不正です。",
                    "content_type"
                ))

        if len(content) > 5000:
            form_errors.append((
                "内容は5000文字以内で入力してください。",
                "content_editor"
            ))

        if form_errors:
            return return_form_errors(form_errors)

        # =========================
        # 添付ファイル
        # =========================

        uploaded_files = [
            file
            for file in request.files.getlist("files")
            if file and file.filename
        ]

        file_names = []

        for file in uploaded_files:
            original_filename = os.path.basename(
                str(file.filename or "")
            )

            extension = os.path.splitext(
                original_filename
            )[1].lower()

            if (
                extension not in ALLOWED_UPLOAD_EXTENSIONS
                or not is_valid_uploaded_file(
                    file,
                    extension
                )
            ):
                return "添付ファイルの検証に失敗しました。", 400

        for file in uploaded_files:
            filename = save_uploaded_file(file)

            if filename:
                file_names.append(filename)

        # =========================
        # 登録
        # =========================

        result = PatrolResult(
            company_code=company_code,
            created_by_username=session.get("username"),
            created_by_name=session.get("name"),
            date=date,
            office=target_office,
            category=category,
            content_type=content_type,
            target_type=target_type,
            target_user=target_user,
            target_username=(
                target_username
                if target_type == "user"
                else ""
            ),
            delivery_place=delivery_place,
            content=content,
            files_json=json.dumps(
                file_names,
                ensure_ascii=False
            ),
            countermeasure="",
            approval_status="未対応",
            reject_reason=""
        )

        db.session.add(result)
        db.session.commit()

        # 個人対象のときだけ通知
        if target_type == "user":
            add_notification(
                result.target_user,
                "安全パトロール確認依頼",
                "あなたに確認が必要な安全パトロールがあります。",
                f"/pointouts/{result.id}",
                company_code=company_code,
                target_username=result.target_username
            )

        notify_mentions(
            result.content,
            f"/pointouts/{result.id}"
        )

        if target_type == "delivery_place":
            return redirect(
                "/pointouts?type=delivery_place"
            )

        return redirect(
            "/pointouts?type=user"
        )
    requested_target_type = request.args.get(
        "target_type",
        ""
    ).strip()

    form_target_type = session.pop(
        "pointout_form_target_type",
        (
            requested_target_type
            if requested_target_type in {
                "user",
                "delivery_place"
            }
            else "user"
        )
    )

    form_data = session.pop(
        "pointout_form_data",
        {}
    )

    return render_template(
        "new_pointout.html",
        form_target_type=form_target_type,
        form_data=form_data,
        drivers=drivers_for_current_company(),
        delivery_places=delivery_places_for_current_company(),
        manuals=manuals_for_current_company(),
        content_types=patrol_content_types_for_current_company(),
    )

