@app.route("/master/vehicles/<int:vehicle_record_id>/karte")
@app.route("/vehicle/karte/<int:vehicle_record_id>")
def vehicle_karte(vehicle_record_id):
    vehicle = Vehicle.query.filter_by(
        id=vehicle_record_id,
        company_code=session.get("company_code")
    ).first_or_404()

    number = vehicle_number({
        "plate_area": vehicle.plate_area or "",
        "plate_class": vehicle.plate_class or "",
        "plate_kana": vehicle.plate_kana or "",
        "plate_number": vehicle.plate_number or ""
    })

    open_defects = get_vehicle_open_inspection_defects(
        vehicle.company_code,
        vehicle.id
    )

    current_user = User.query.filter_by(
        company_code=session.get("company_code"),
        username=session.get("username")
    ).first()

    if current_user is not None:
        user_settings = safe_json_dict(
            current_user.dashboard_settings_json
        )

        if user_settings.get(
            "vehicle_karte_last_vehicle_id"
        ) != vehicle.id:
            user_settings[
                "vehicle_karte_last_vehicle_id"
            ] = vehicle.id

            current_user.dashboard_settings_json = json.dumps(
                user_settings,
                ensure_ascii=False
            )
            db.session.commit()

    mileage_records = (
        VehicleOperationRecord.query
        .filter(
            VehicleOperationRecord.company_code == vehicle.company_code,
            VehicleOperationRecord.vehicle_record_id == vehicle.id,
            VehicleOperationRecord.arrival_meter.isnot(None)
        )
        .order_by(
            VehicleOperationRecord.operation_date.asc(),
            db.func.coalesce(
                VehicleOperationRecord.arrival_at,
                VehicleOperationRecord.operation_date
            ).asc(),
            VehicleOperationRecord.id.asc()
        )
        .all()
    )

    mileage_by_date = {}

    for record in mileage_records:
        mileage_by_date[record.operation_date] = float(
            record.arrival_meter
        )

    karte_mileage_points = [
        {
            "date": operation_date,
            "mileage": mileage
        }
        for operation_date, mileage in sorted(
            mileage_by_date.items()
        )
    ]

    return render_template(
        "vehicle_karte.html",
        vehicle=vehicle,
        vehicle_number=number,
        open_defects=open_defects,
        karte_mileage_points=karte_mileage_points,
        karte_parts_ranking=get_vehicle_karte_parts_context(
            vehicle
        )["part_ranking"],
    )


@app.route(
    "/vehicle/karte/<int:vehicle_record_id>/documents/<draft_id>/source"
)
def vehicle_karte_document_source(vehicle_record_id, draft_id):
    vehicle = Vehicle.query.filter_by(
        id=vehicle_record_id,
        company_code=session.get("company_code")
    ).first_or_404()

    draft = VehicleDocumentImportDraft.query.filter_by(
        id=draft_id,
        company_code=vehicle.company_code,
        status="completed"
    ).first_or_404()

    records = safe_json_dict(
        draft.result_json
    ).get("records", [])

    if not isinstance(records, list):
        raise NotFound()

    belongs_to_vehicle = any(
        isinstance(record, dict)
        and str(record.get("vehicle_record_id", ""))
        == str(vehicle.id)
        for record in records
    )

    if not belongs_to_vehicle:
        raise NotFound()

    extension = os.path.splitext(
        draft.source_filename
    )[1].lower()

    mimetype = {
        ".pdf": "application/pdf",
        ".png": "image/png",
        ".jpg": "image/jpeg",
        ".jpeg": "image/jpeg"
    }.get(extension)

    if not mimetype:
        raise NotFound()

    response = send_file(
        BytesIO(draft.source_file),
        mimetype=mimetype,
        download_name=draft.source_filename,
        as_attachment=request.args.get("download") == "1",
        conditional=False,
        etag=False,
        max_age=0
    )
    response.headers["X-Content-Type-Options"] = "nosniff"
    response.headers["Cache-Control"] = "private, no-store"

    return response


def get_vehicle_operation_imported_vehicle_ids(draft):
    result = safe_json_dict(draft.result_json)
    vehicle_ids = result.get("imported_vehicle_ids")

    if isinstance(vehicle_ids, list):
        return {
            value for value in vehicle_ids
            if isinstance(value, int) and not isinstance(value, bool)
        }

    # 従来の完了済みCSVは既存の表示・ダウンロード権限を維持する。
    if draft.status != "completed":
        return set()

    selections = safe_json_dict(draft.selection_json)
    return {
        selection["vehicle_record_id"]
        for selection in selections.values()
        if isinstance(selection, dict)
        and selection.get("include") is True
        and isinstance(selection.get("vehicle_record_id"), int)
        and not isinstance(selection.get("vehicle_record_id"), bool)
    }


@app.route(
    "/vehicle/karte/<int:vehicle_record_id>/operation-files/<draft_id>"
)
def vehicle_karte_operation_source(vehicle_record_id, draft_id):
    vehicle = Vehicle.query.filter_by(
        id=vehicle_record_id,
        company_code=session.get("company_code")
    ).first_or_404()

    draft = VehicleOperationImportDraft.query.filter(
        VehicleOperationImportDraft.id == draft_id,
        VehicleOperationImportDraft.company_code == vehicle.company_code,
        VehicleOperationImportDraft.status.in_(["preview", "completed"])
    ).first_or_404()

    if vehicle.id not in get_vehicle_operation_imported_vehicle_ids(draft):
        raise NotFound()

    response = send_file(
        BytesIO(draft.source_file),
        mimetype="text/csv",
        download_name=draft.source_filename,
        as_attachment=True,
        conditional=False,
        etag=False,
        max_age=0
    )
    response.headers["X-Content-Type-Options"] = "nosniff"
    response.headers["Cache-Control"] = "private, no-store"

    return response


def build_vehicle_karte_documents_context(vehicle, documents):
    from types import SimpleNamespace

    categories = [
        ("invoice", "請求書"),
        ("maintenance", "整備記録"),
        ("inspection_3", "3か月点検"),
        ("inspection_12", "12か月点検"),
        ("vehicle_inspection", "車検"),
        ("photo", "写真"),
        ("operation_csv", "運行実績CSV"),
        ("other", "その他"),
    ]
    labels = dict(categories)

    related = {}
    rows = VehicleMaintenanceRecord.query.filter_by(
        company_code=vehicle.company_code,
        vehicle_record_id=vehicle.id,
    ).order_by(VehicleMaintenanceRecord.id.asc()).all()

    for row in rows:
        source = safe_json_dict(row.invoice_details_json).get("source")
        if (
            isinstance(source, dict)
            and isinstance(source.get("draft_id"), str)
        ):
            related.setdefault(source["draft_id"], []).append(row)

    usernames = {
        document.get("created_by_username")
        for document in documents
    }
    usernames.discard(None)
    usernames.discard("")

    users = User.query.filter(
        User.company_code == vehicle.company_code,
        User.username.in_(list(usernames)),
    ).all() if usernames else []

    user_names = {
        user.username: (
            f"{user.last_name or ''}{user.first_name or ''}".strip()
            or user.username
        )
        for user in users
    }

    now = datetime.now(ZoneInfo("Asia/Tokyo"))

    for document in documents:
        filename = document.get("filename") or "file"
        extension = os.path.splitext(filename)[1].lower().lstrip(".")
        is_operation = document["document_type"] == "operation_csv"
        records = (
            related.get(document["draft_id"], [])
            if not is_operation else []
        )
        normalized = (
            filename.lower()
            .replace("３", "3")
            .replace("１２", "12")
        )

        if is_operation:
            kind = "operation_csv"
        elif "車検" in filename:
            kind = "vehicle_inspection"
        elif any(term in normalized for term in (
            "12か月", "12ヶ月", "12ヵ月", "12カ月",
        )):
            kind = "inspection_12"
        elif any(term in normalized for term in (
            "3か月", "3ヶ月", "3ヵ月", "3カ月",
        )):
            kind = "inspection_3"
        elif (
            "請求書" in filename
            or any(row.invoice_number for row in records)
        ):
            kind = "invoice"
        elif document["document_type"] == "maintenance":
            kind = "maintenance"
        elif extension in {"png", "jpg", "jpeg", "webp", "gif"}:
            kind = "photo"
        else:
            kind = "other"

        registered_at = document.get("completed_at")
        if registered_at is not None:
            if registered_at.tzinfo is None:
                registered_at = registered_at.replace(
                    tzinfo=ZoneInfo("UTC")
                )
            registered_at = registered_at.astimezone(
                ZoneInfo("Asia/Tokyo")
            )

        endpoint = (
            "vehicle_karte_operation_source"
            if is_operation else "vehicle_karte_document_source"
        )
        source_url = url_for(
            endpoint,
            vehicle_record_id=vehicle.id,
            draft_id=document["draft_id"],
        )
        username = document.get("created_by_username") or ""

        document.update(
            key=(
                "operation:" if is_operation else "document:"
            ) + str(document["draft_id"]),
            kind=kind,
            kind_label=labels[kind],
            extension=extension,
            source_url=source_url,
            download_url=(
                source_url if is_operation else url_for(
                    endpoint,
                    vehicle_record_id=vehicle.id,
                    draft_id=document["draft_id"],
                    download="1",
                )
            ),
            registered_at=registered_at,
            date_label=(
                registered_at.strftime("%Y/%m/%d")
                if registered_at else "—"
            ),
            registered_label=(
                registered_at.strftime("%Y/%m/%d %H:%M")
                if registered_at else "—"
            ),
            uploader=username,
            uploader_label=user_names.get(username, username) or "—",
            related_content=" / ".join(dict.fromkeys(
                row.content for row in records if row.content
            )),
            notes="\n".join(dict.fromkeys(
                row.notes for row in records if row.notes
            )),
        )

    tabs = [{
        "key": "",
        "label": "すべて",
        "count": len(documents),
    }] + [
        {
            "key": kind,
            "label": label,
            "count": sum(
                document["kind"] == kind for document in documents
            ),
        }
        for kind, label in categories
    ]

    filters = {
        "q": request.args.get("q", "").strip()[:200],
        "kind": request.args.get("kind", "").strip(),
        "period": request.args.get("period", "").strip(),
        "uploader": request.args.get("uploader", "").strip(),
    }
    if filters["kind"] not in labels:
        filters["kind"] = ""
    if filters["period"] not in {"", "30", "90", "365"}:
        filters["period"] = ""

    filtered = documents

    if filters["kind"]:
        filtered = [
            document for document in filtered
            if document["kind"] == filters["kind"]
        ]

    if filters["q"]:
        keyword = filters["q"].casefold()
        filtered = [
            document for document in filtered
            if keyword in " ".join(
                str(document.get(key) or "")
                for key in ("filename", "notes", "related_content")
            ).casefold()
        ]

    if filters["uploader"]:
        filtered = [
            document for document in filtered
            if document["uploader"] == filters["uploader"]
        ]

    if filters["period"]:
        cutoff = now - timedelta(days=int(filters["period"]))
        filtered = [
            document for document in filtered
            if document["registered_at"]
            and document["registered_at"] >= cutoff
        ]

    filtered = sorted(
        filtered,
        key=lambda document: (
            document["registered_at"].isoformat()
            if document["registered_at"] else "",
            document["key"],
        ),
        reverse=True,
    )

    per_page = request.args.get("per_page", 10, type=int)
    if per_page not in {10, 20, 50}:
        per_page = 10

    pages = max(1, (len(filtered) + per_page - 1) // per_page)
    page = min(
        pages,
        max(1, request.args.get("page", 1, type=int)),
    )
    items = filtered[(page - 1) * per_page:page * per_page]

    selected_key = request.args.get("document", "")
    selected = None
    if selected_key and selected_key != "closed":
        selected = next((
            document for document in filtered
            if document["key"] == selected_key
        ), None)
        if selected is None:
            raise NotFound()
    elif selected_key != "closed" and items:
        selected = items[0]

    return {
        "document_page": SimpleNamespace(
            items=items,
            total=len(filtered),
            page=page,
            pages=pages,
            per_page=per_page,
            has_prev=page > 1,
            has_next=page < pages,
            prev_num=page - 1,
            next_num=page + 1,
        ),
        "document_categories": tabs,
        "document_filters": filters,
        "document_uploaders": [
            {
                "username": username,
                "label": user_names.get(username, username),
            }
            for username in sorted(usernames)
        ],
        "selected_document": selected,
    }


@app.route("/vehicle/karte/<int:vehicle_record_id>/documents")
def vehicle_karte_documents(vehicle_record_id):
    vehicle = Vehicle.query.filter_by(
        id=vehicle_record_id,
        company_code=session.get("company_code")
    ).first_or_404()

    number = vehicle_number({
        "plate_area": vehicle.plate_area or "",
        "plate_class": vehicle.plate_class or "",
        "plate_kana": vehicle.plate_kana or "",
        "plate_number": vehicle.plate_number or ""
    })

    drafts = (
        VehicleDocumentImportDraft.query
        .with_entities(
            VehicleDocumentImportDraft.id,
            VehicleDocumentImportDraft.source_filename,
            VehicleDocumentImportDraft.created_by_username,
            VehicleDocumentImportDraft.document_type,
            VehicleDocumentImportDraft.result_json,
            VehicleDocumentImportDraft.completed_at
        )
        .filter(
            VehicleDocumentImportDraft.company_code
            == vehicle.company_code,
            VehicleDocumentImportDraft.status == "completed"
        )
        .order_by(
            VehicleDocumentImportDraft.completed_at.desc(),
            VehicleDocumentImportDraft.id.desc()
        )
        .all()
    )

    documents = []

    for draft in drafts:
        records = safe_json_dict(
            draft.result_json
        ).get("records", [])

        if not isinstance(records, list):
            continue

        vehicle_records = [
            record
            for record in records
            if isinstance(record, dict)
            and str(record.get("vehicle_record_id", ""))
            == str(vehicle.id)
        ]

        if not vehicle_records:
            continue

        documents.append({
            "draft_id": draft.id,
            "filename": draft.source_filename,
            "created_by_username": draft.created_by_username,
            "document_type": draft.document_type,
            "completed_at": draft.completed_at,
            "records": vehicle_records,
        })

    open_defects = get_vehicle_open_inspection_defects(
        vehicle.company_code,
        vehicle.id
    )

    operation_drafts = (
        VehicleOperationImportDraft.query
        .with_entities(
            VehicleOperationImportDraft.id,
            VehicleOperationImportDraft.source_filename,
            VehicleOperationImportDraft.created_by_username,
            VehicleOperationImportDraft.selection_json,
            VehicleOperationImportDraft.result_json,
            VehicleOperationImportDraft.status,
            VehicleOperationImportDraft.created_at,
            VehicleOperationImportDraft.completed_at
        )
        .filter(
            VehicleOperationImportDraft.company_code
            == vehicle.company_code,
            VehicleOperationImportDraft.status.in_(["preview", "completed"])
        )
        .order_by(
            VehicleOperationImportDraft.completed_at.desc(),
            VehicleOperationImportDraft.id.desc()
        )
        .all()
    )

    for draft in operation_drafts:
        if vehicle.id not in get_vehicle_operation_imported_vehicle_ids(draft):
            continue

        documents.append({
            "draft_id": draft.id,
            "filename": draft.source_filename,
            "created_by_username": draft.created_by_username,
            "document_type": "operation_csv",
            "completed_at": draft.completed_at or draft.created_at,
            "records": [],
        })

    documents.sort(
        key=lambda document: (
            document["completed_at"].isoformat()
            if document["completed_at"] is not None
            else ""
        ),
        reverse=True
    )

    return render_template(
        "vehicle_karte_documents.html",
        vehicle=vehicle,
        vehicle_number=number,
        open_defects=open_defects,
        documents=documents,
        **build_vehicle_karte_documents_context(vehicle, documents)
    )


@app.route("/vehicle/karte/<int:vehicle_record_id>/inspections")
def vehicle_karte_inspections(vehicle_record_id):
    vehicle = Vehicle.query.filter_by(
        id=vehicle_record_id,
        company_code=session.get("company_code")
    ).first_or_404()

    number = vehicle_number({
        "plate_area": vehicle.plate_area or "",
        "plate_class": vehicle.plate_class or "",
        "plate_kana": vehicle.plate_kana or "",
        "plate_number": vehicle.plate_number or ""
    })

    inspection_view = request.args.get("inspection_view", "all")
    if inspection_view not in {"all", "daily", "periodic", "3month", "12month", "certificate"}:
        inspection_view = "all"

    def valid_date_arg(name):
        value = request.args.get(name, "").strip()
        try:
            return datetime.strptime(value, "%Y-%m-%d").date().isoformat() if value else ""
        except ValueError:
            return ""

    inspection_start = valid_date_arg("start_date")
    inspection_end = valid_date_arg("end_date")
    if inspection_start and inspection_end and inspection_start > inspection_end:
        inspection_start, inspection_end = inspection_end, inspection_start

    daily_query = VehicleChecklistResult.query.filter_by(
        company_code=vehicle.company_code, vehicle_record_id=vehicle.id)
    periodic_query = VehiclePeriodicInspectionRecord.query.filter_by(
        company_code=vehicle.company_code, vehicle_record_id=vehicle.id)
    if inspection_view in {"3month", "12month"}:
        periodic_query = periodic_query.filter_by(inspection_type=inspection_view)
    for boundary, value in (("start", inspection_start), ("end", inspection_end)):
        if value:
            daily_date = db.func.substr(VehicleChecklistResult.checked_date, 1, 10)
            periodic_date = VehiclePeriodicInspectionRecord.inspection_date
            daily_query = daily_query.filter(daily_date >= value if boundary == "start" else daily_date <= value)
            periodic_query = periodic_query.filter(periodic_date >= value if boundary == "start" else periodic_date <= value)

    page = max(1, request.args.get("page", 1, type=int))

    per_page = request.args.get("per_page", 10, type=int)
    if per_page not in {10, 20, 50}:
        per_page = 10

    periodic_per_page = request.args.get("periodic_per_page", 10, type=int)
    if periodic_per_page not in {10, 20, 50}:
        periodic_per_page = 10

    inspection_page = (
        daily_query
        .order_by(
            VehicleChecklistResult.checked_date.desc(),
            VehicleChecklistResult.id.desc()
        )
        .paginate(
            page=page,
            per_page=per_page,
            error_out=False
        )
    )

    inspection_snapshots = {
        record.id: safe_json_dict(record.checklist_snapshot_json)
        for record in inspection_page.items
    }

    inspection_links = {
        record.id: url_for(
            "vehicle_checklist_results",
            index=record.checklist_id,
            vehicle_record_id=vehicle.id,
            year=record.year,
            month=record.month,
            active_day=record.day
        )
        for record in inspection_page.items
    }

    periodic_page_number = max(
        1,
        request.args.get("periodic_page", 1, type=int)
    )

    periodic_inspection_page = (
        periodic_query
        .order_by(
            VehiclePeriodicInspectionRecord.inspection_date.desc(),
            VehiclePeriodicInspectionRecord.id.desc()
        )
        .paginate(
            page=periodic_page_number,
            per_page=periodic_per_page,
            error_out=False
        )
    )

    return render_template(
        "vehicle_karte_inspections.html",
        inspection_view=inspection_view,
        inspection_start=inspection_start, inspection_end=inspection_end,
        vehicle=vehicle,
        vehicle_number=number,
        inspection_page=inspection_page,
        inspection_snapshots=inspection_snapshots,
        inspection_results={
            record.id: vehicle_checklist_result_to_dict(record)
            for record in inspection_page.items
        },
        inspection_links=inspection_links,
        periodic_inspection_page=periodic_inspection_page,
        periodic_followup_summary=periodic_followups.summary(vehicle.company_code, vehicle.id),
        manual_inspection_executions=[row for row in inspection_plans.manual_records(vehicle.company_code, vehicle.id)
            if (inspection_view not in {"3month", "12month"} or row.kind == inspection_view)
            and (not inspection_start or row.performed_date >= inspection_start)
            and (not inspection_end or row.performed_date <= inspection_end)],
        periodic_details={record.id: safe_json_dict(record.details_json)
                          for record in periodic_inspection_page.items},
        open_defects=get_vehicle_open_inspection_defects(
            vehicle.company_code,
            vehicle.id
        )
    )


def get_vehicle_karte_history_entries(company_code, vehicle_record_id):
    entries = []

    def normalize_date(value):
        text = str(value or "").strip()[:10]

        for date_format in ("%Y-%m-%d", "%Y/%m/%d"):
            try:
                return datetime.strptime(
                    text,
                    date_format
                ).strftime("%Y-%m-%d")
            except ValueError:
                continue

        return ""

    inspection_records = VehicleChecklistResult.query.filter_by(
        company_code=company_code,
        vehicle_record_id=vehicle_record_id
    ).all()

    for record in inspection_records:
        snapshot = safe_json_dict(record.checklist_snapshot_json)
        items = safe_json_dict_list(
            json.dumps(snapshot.get("items") or [])
        )
        is_daily_inspection = any(
            item.get("fixed_template_code")
            == "daily_inspection_truck_trailer"
            for item in items
        )

        inspection_date = normalize_date(
            f"{record.year}-"
            f"{str(record.month).zfill(2)}-"
            f"{str(record.day).zfill(2)}"
        )

        entries.append({
            "key": f"inspection:{record.id}",
            "date": inspection_date,
            "kind": "日常点検" if is_daily_inspection else "点検",
            "content": snapshot.get("name") or "車両チェックリスト",
            "files": list(dict.fromkeys(
                filename
                for answer in safe_json_dict_list(record.answers_json)
                for filename in (
                    answer.get("files")
                    if isinstance(answer.get("files"), list)
                    else []
                )
                if isinstance(filename, str) and filename.strip()
            )),
            "mileage": None,
            "cost": None,
            "status": record.status or "",
            "actor": record.checked_by or record.checked_by_username or "",
            "link": url_for(
                "vehicle_checklist_results",
                index=record.checklist_id,
                vehicle_record_id=vehicle_record_id,
                year=record.year,
                month=record.month,
                active_day=record.day
            ),
        })

        if is_daily_inspection:
            judgment = safe_json_dict(record.operation_judgment_json)
            stored_defects = judgment.get("defects") or []
            defects = [
                dict(defect)
                for defect in stored_defects
                if isinstance(defect, dict)
            ] if isinstance(stored_defects, list) else []

            for answer in safe_json_dict_list(record.answers_json):
                if str(answer.get("value") or "").strip() != "×":
                    continue

                item_no = str(answer.get("item_no", ""))
                accounted_for = False

                for defect in defects:
                    if str(defect.get("item_no", "")) != item_no:
                        continue

                    rechecked_answer = defect.get("rechecked_answer") or {}
                    if not isinstance(rechecked_answer, dict):
                        rechecked_answer = {}

                    if (
                        defect.get("status") != "解消"
                        or all(
                            rechecked_answer.get(field) == answer.get(field)
                            for field in ("value", "comment", "files")
                        )
                    ):
                        accounted_for = True
                        break

                if not accounted_for:
                    defects.append({
                        "item_no": item_no,
                        "status": "対応待ち",
                        "reported_answer": dict(answer),
                    })

            if isinstance(defects, list):
                for defect_index, defect in enumerate(defects):
                    if not isinstance(defect, dict):
                        continue

                    answer = defect.get("reported_answer") or {}
                    if not isinstance(answer, dict):
                        answer = {}

                    item_name = str(answer.get("content") or "").strip()
                    comment = str(answer.get("comment") or "").strip()
                    content = " / ".join(
                        value for value in (item_name, comment) if value
                    )

                    entries.append({
                        "key": (
                            f"defect:{record.id}:{defect_index}"
                        ),
                        "date": (
                            normalize_date(defect.get("reported_at"))
                            or inspection_date
                        ),
                        "kind": "異常・指摘",
                        "content": content or "日常点検の不具合",
                        "files": list(dict.fromkeys(
                            filename
                            for filename in (
                                answer.get("files")
                                if isinstance(answer.get("files"), list)
                                else []
                            )
                            if isinstance(filename, str) and filename.strip()
                        )),
                        "mileage": None,
                        "cost": None,
                        "status": defect.get("status") or "",
                        "actor": (
                            defect.get("reported_by")
                            or record.checked_by
                            or record.checked_by_username
                            or ""
                        ),
                        "link": url_for(
                            "vehicle_checklist_results",
                            index=record.checklist_id,
                            vehicle_record_id=vehicle_record_id,
                            year=record.year,
                            month=record.month,
                            active_day=record.day
                        ),
                    })

    entries.extend(periodic_followups.history(company_code, vehicle_record_id))

    periodic_records = VehiclePeriodicInspectionRecord.query.filter_by(
        company_code=company_code,
        vehicle_record_id=vehicle_record_id,
    ).all()
    for record in periodic_records:
        entries.append({
            "key": f"periodic:{record.id}",
            "date": normalize_date(record.inspection_date),
            "kind": {"3month": "3か月点検", "12month": "12か月点検"}.get(
                record.inspection_type, "定期点検"
            ),
            "content": record.content or "定期点検記録",
            "files": [],
            "mileage": record.mileage,
            "cost": None,
            "status": "登録済み",
            "actor": " / ".join(value for value in (
                record.inspection_company, record.inspector_name
            ) if value),
            "link": url_for("vehicle_periodic_inspection_source", record_id=record.id),
        })

    plan_events = db.session.query(VehicleInspectionPlanEvent, VehicleInspectionPlan).join(
        VehicleInspectionPlan, VehicleInspectionPlan.id == VehicleInspectionPlanEvent.plan_id
    ).filter(
        VehicleInspectionPlan.company_code == company_code,
        VehicleInspectionPlan.vehicle_record_id == vehicle_record_id,
        VehicleInspectionPlanEvent.company_code == company_code,
    ).all()
    for change, plan in plan_events:
        snapshot = safe_json_dict(change.detail_json)
        after = snapshot.get("after") or {}
        kind_label = {"3month": "3か月点検", "12month": "12か月点検", "vehicle_inspection": "車検"}.get(plan.kind, "点検")
        action_label = {"cancelled": "取消", "completed": "実施記録と連動", "completed_manual": "実施先行登録", "document_attached": "点検簿を関連付け", "created_from_document": "点検簿から作成"}.get(change.action, "登録・変更")
        entries.append({
            "key": f"inspection-plan:{change.id}",
            "date": normalize_date(change.created_at),
            "kind": "点検予定",
            "content": f"{kind_label} {action_label} / 予定月 {after.get('planned_month', '')} / 予約日 {after.get('reservation_date') or '未定'} / {after.get('factory') or '実施先未定'}",
            "files": [], "mileage": None, "cost": None,
            "status": {"planned": "予定", "completed": "実施済み", "cancelled": "取消"}.get(after.get("status"), ""),
            "actor": change.created_by,
            "link": url_for("vehicle_inspection_plans", scope="vehicle", vehicle_id=vehicle_record_id, kind=plan.kind),
        })

    for execution in inspection_plans.manual_records(company_code, vehicle_record_id):
        entries.append({
            "key": f"inspection-execution:{execution.id}", "date": execution.performed_date,
            "kind": {"3month": "3か月点検", "12month": "12か月点検"}.get(execution.kind, "点検"),
            "content": "点検実施（書類未受領） / " + (execution.factory or "実施先未登録") + (" / " + execution.note if execution.note else ""),
            "files": [], "mileage": None, "cost": None, "status": "実施済み・書類未受領",
            "actor": execution.created_by,
            "link": url_for("vehicle_karte_inspections", vehicle_record_id=vehicle_record_id, inspection_view="periodic") + f"#manual-execution-{execution.id}",
        })

    driving_reports = VehicleDrivingReportRecord.query.filter_by(
        company_code=company_code,
        vehicle_record_id=vehicle_record_id
    ).all()

    for record in driving_reports:
        entries.append({
            "key": f"driving-report:{record.id}",
            "date": normalize_date(record.operation_date),
            "kind": "安全運転日報",
            "content": record.content or "安全運転日報",
            "files": [],
            "mileage": record.mileage,
            "cost": None,
            "status": "",
            "actor": "",
            "link": url_for(
                "vehicle_driving_report_source",
                record_id=record.id
            ),
        })

    maintenance_records = VehicleMaintenanceRecord.query.filter_by(
        company_code=company_code,
        vehicle_record_id=vehicle_record_id
    ).all()

    for record in maintenance_records:
        invoice_details = safe_json_dict(record.invoice_details_json)
        invoice_source = invoice_details.get("source")
        if not isinstance(invoice_source, dict):
            invoice_source = {}
        source_draft_id = invoice_source.get("draft_id")

        entries.append({
            "key": f"maintenance:{record.id}",
            "date": (
                normalize_date(record.completion_date)
                or normalize_date(record.entry_date)
            ),
            "kind": record.category or "整備",
            "content": (
                record.content
                or record.repair_content
                or record.symptom
                or ""
            ),
            "files": list(dict.fromkeys(
                safe_json_str_list(record.files_json)
            )),
            "mileage": record.mileage,
            "cost": record.total_cost,
            "status": record.status or "",
            "actor": " / ".join(
                value
                for value in (
                    record.maintenance_company,
                    record.maintenance_person
                )
                if value
            ),
            "link": (
                url_for(
                    "vehicle_karte_document_source",
                    vehicle_record_id=vehicle_record_id,
                    draft_id=source_draft_id,
                )
                if source_draft_id
                else None
            ),
        })

    repair_events = (
        ChecklistEvent.query
        .join(
            VehicleChecklistResult,
            ChecklistEvent.result_id == VehicleChecklistResult.id
        )
        .filter(
            ChecklistEvent.company_code == company_code,
            ChecklistEvent.result_type == "vehicle",
            ChecklistEvent.event_type.in_(["整備中", "再確認待ち"]),
            VehicleChecklistResult.company_code == company_code,
            VehicleChecklistResult.vehicle_record_id == vehicle_record_id
        )
        .all()
    )

    for event in repair_events:
        detail = safe_json_dict(event.detail_json)
        repair = detail.get("repair") or {}
        if not isinstance(repair, dict) or not repair:
            continue

        defect = detail.get("defect") or {}
        if not isinstance(defect, dict):
            defect = {}

        answer = defect.get("reported_answer") or {}
        if not isinstance(answer, dict):
            answer = {}

        item_name = str(answer.get("content") or "").strip()
        note = str(repair.get("note") or "").strip()
        content = " / ".join(
            value for value in (item_name, note) if value
        )

        result_record = db.session.get(
            VehicleChecklistResult,
            event.result_id
        )
        if not result_record:
            continue

        entries.append({
            "key": f"inspection-repair:{event.id}",
            "date": normalize_date(repair.get("performed_at")),
            "kind": "整備",
            "content": content or "日常点検の不具合対応",
            "mileage": None,
            "cost": None,
            "status": repair.get("status") or event.event_type or "",
            "actor": (
                repair.get("performed_by")
                or event.actor_name
                or ""
            ),
            "link": url_for(
                "vehicle_checklist_results",
                index=result_record.checklist_id,
                vehicle_record_id=vehicle_record_id,
                year=result_record.year,
                month=result_record.month,
                active_day=result_record.day
            ),
        })

    entries.sort(
        key=lambda entry: (entry["date"], entry["key"]),
        reverse=True
    )

    return entries


def get_vehicle_maintenance_import_context(batch_id):
    company_code = session.get("company_code")
    drafts = VehicleDocumentImportDraft.query.filter_by(
        batch_id=batch_id,
        company_code=company_code,
        created_by_username=session.get("username"),
        document_type="maintenance",
        status="completed",
    ).order_by(VehicleDocumentImportDraft.id.asc()).all()

    requested = []
    for draft in drafts:
        rows = safe_json_dict(draft.result_json).get("records", [])
        if not isinstance(rows, list):
            continue
        for row in rows:
            if not isinstance(row, dict):
                continue
            record_id = row.get("record_id")
            vehicle_id = row.get("vehicle_record_id")
            if (
                row.get("document_type") == "maintenance"
                and type(record_id) is int and record_id > 0
                and type(vehicle_id) is int and vehicle_id > 0
            ):
                requested.append((record_id, vehicle_id))

    if not requested:
        raise NotFound()

    records = VehicleMaintenanceRecord.query.filter(
        VehicleMaintenanceRecord.company_code == company_code,
        VehicleMaintenanceRecord.id.in_([item[0] for item in requested]),
    ).all()
    record_map = {record.id: record for record in records}
    ordered_records = {}
    for record_id, vehicle_id in requested:
        record = record_map.get(record_id)
        if record is not None and record.vehicle_record_id == vehicle_id:
            ordered_records[record_id] = record

    vehicle_ids = list(dict.fromkeys(
        record.vehicle_record_id for record in ordered_records.values()
    ))
    vehicles = Vehicle.query.filter(
        Vehicle.company_code == company_code,
        Vehicle.id.in_(vehicle_ids),
    ).all()
    vehicle_map = {vehicle.id: vehicle for vehicle in vehicles}
    targets = []
    for vehicle_id in vehicle_ids:
        vehicle = vehicle_map.get(vehicle_id)
        if vehicle is None:
            continue
        record_ids = [
            record.id for record in ordered_records.values()
            if record.vehicle_record_id == vehicle_id
        ]
        targets.append({
            "id": vehicle_id,
            "number": vehicle_number({
                "plate_area": vehicle.plate_area or "",
                "plate_class": vehicle.plate_class or "",
                "plate_kana": vehicle.plate_kana or "",
                "plate_number": vehicle.plate_number or "",
            }),
            "count": len(record_ids),
            "record_ids": record_ids,
            "url": url_for(
                "vehicle_karte_maintenance",
                vehicle_record_id=vehicle_id,
                import_batch=batch_id,
            ),
        })

    if not targets:
        raise NotFound()
    return {
        "batch_id": batch_id,
        "vehicles": targets,
        "total": sum(target["count"] for target in targets),
    }


def get_vehicle_maintenance_record_events(record):
    labels = {
        "content": "整備内容",
        "category": "分類",
        "status": "状態",
        "entry_date": "入庫日",
        "completion_date": "完了日",
        "mileage": "走行距離（km）",
        "symptom": "症状",
        "cause": "原因",
        "temporary_action": "応急処置",
        "repair_content": "修理内容",
        "maintenance_company": "整備会社",
        "maintenance_person": "整備担当",
        "repair_hours": "作業時間",
        "invoice_number": "請求書番号",
        "invoice_date": "請求日",
        "parts_cost": "部品代（円）",
        "labor_cost": "工賃（円）",
        "other_cost": "その他費用（円）",
        "tax_amount": "消費税（円）",
        "total_cost": "合計金額（円）",
        "notes": "備考",
    }
    numeric_fields = {
        "mileage", "repair_hours", "parts_cost", "labor_cost",
        "other_cost", "tax_amount", "total_cost",
    }
    action_labels = {
        "created": "整備記録を登録",
        "updated": "整備記録を編集",
        "status_changed": "状態を変更",
        "imported": "資料から取り込み",
    }

    events = VehicleMaintenanceRecordEvent.query.filter_by(
        company_code=record.company_code,
        vehicle_record_id=record.vehicle_record_id,
        maintenance_record_id=record.id,
    ).order_by(
        VehicleMaintenanceRecordEvent.created_at.desc(),
        VehicleMaintenanceRecordEvent.id.desc(),
    ).limit(50).all()

    items = []
    for event in events:
        changes = []
        for change in safe_json_dict_list(event.changes_json):
            field = change.get("field")
            if field not in labels:
                continue
            if change.get("before") == change.get("after"):
                continue
            if field == "status" and event.action == "status_changed":
                continue

            def display(value):
                if field in numeric_fields:
                    return format_vehicle_maintenance_number(value)
                return str(value) if value is not None and value != "" else "—"

            changes.append({
                "label": labels[field],
                "before": display(change.get("before")),
                "after": display(change.get("after")),
            })

        items.append({
            "label": action_labels.get(event.action, "記録を更新"),
            "date": (event.created_at or "")[:16].replace("T", " "),
            "username": event.created_by_username or "",
            "status_before": event.status_before,
            "status_after": event.status_after,
            "status_changed": event.action == "status_changed",
            "changes": changes,
        })

    if record.created_at and not any(
        event.action in {"created", "imported"} for event in events
    ):
        items.append({
            "label": "登録（既存記録）",
            "date": record.created_at[:16].replace("T", " "),
            "username": record.created_by_username or "",
            "status_before": None,
            "status_after": None,
            "status_changed": False,
            "changes": [],
        })

    usernames = {
        item["username"] for item in items if item["username"]
    }
    users = User.query.filter(
        User.company_code == record.company_code,
        User.username.in_(list(usernames)),
    ).all() if usernames else []

    names = {
        user.username: (
            f"{user.last_name or ''}{user.first_name or ''}".strip()
            or user.username
        )
        for user in users
    }
    for item in items:
        item["actor"] = names.get(
            item["username"], item["username"]
        ) or "—"

    return items


def validate_vehicle_maintenance_form(form, *, entry_date_required=True):
    values = {}
    errors = []

    text_fields = {
        "content": ("整備内容", 5000),
        "category": ("分類", 50),
        "status": ("状態", 50),
        "symptom": ("症状", 5000),
        "cause": ("原因", 5000),
        "temporary_action": ("応急処置", 5000),
        "repair_content": ("修理内容", 5000),
        "maintenance_company": ("整備会社", 200),
        "maintenance_person": ("整備担当", 100),
        "invoice_number": ("請求書番号", 100),
        "notes": ("備考", 10000),
    }

    for field, (label, limit) in text_fields.items():
        text = form.get(field, "").strip()
        values[field] = text or None
        if len(text) > limit:
            errors.append((
                f"{label}は{limit}文字以内で入力してください。",
                field,
            ))

    if not values["content"]:
        errors.append(("整備内容を入力してください。", "content"))

    for field, label in (
        ("entry_date", "入庫日"),
        ("completion_date", "完了日"),
        ("invoice_date", "請求日"),
    ):
        text = form.get(field, "").strip()
        values[field] = text or None

        if not text:
            if field == "entry_date" and entry_date_required:
                errors.append(("入庫日を入力してください。", field))
            continue

        try:
            parsed = datetime.strptime(text, "%Y-%m-%d")
            if parsed.strftime("%Y-%m-%d") != text:
                raise ValueError()
        except ValueError:
            errors.append((f"{label}を正しく入力してください。", field))

    date_errors = {field for _, field in errors}
    if (
        values["entry_date"] and values["completion_date"]
        and not {"entry_date", "completion_date"} & date_errors
        and values["completion_date"] < values["entry_date"]
    ):
        errors.append((
            "完了日は入庫日以降にしてください。",
            "completion_date",
        ))

    for field, label, maximum, nonnegative in (
        ("mileage", "走行距離", "999999999999.99", True),
        ("repair_hours", "作業時間", "99999999.99", True),
        ("parts_cost", "部品代", "999999999999.99", False),
        ("labor_cost", "工賃", "999999999999.99", False),
        ("other_cost", "その他費用", "999999999999.99", False),
        ("tax_amount", "消費税", "999999999999.99", False),
        ("total_cost", "合計金額", "999999999999.99", False),
    ):
        text = form.get(field, "").strip()
        values[field] = None

        if not text:
            continue

        try:
            if len(text) > 100:
                raise ValueError()

            amount = parse_maintenance_invoice_number(text)
            if (
                not amount.is_finite()
                or abs(amount) > Decimal(maximum)
                or (nonnegative and amount < 0)
                or amount != amount.quantize(Decimal("0.01"))
            ):
                raise ValueError()

            values[field] = amount
        except (InvalidOperation, ValueError):
            errors.append((
                f"{label}は範囲内の数値を小数2桁までで入力してください。",
                field,
            ))

    return values, errors


def save_vehicle_maintenance_replacement_parts(
    record, *, allow_unconfirmed=False
):
    if (
        record.id is None
        or record.company_code != session.get("company_code")
    ):
        raise ValueError("Invalid maintenance record")

    lines = json.loads(record.line_items_json or "[]")
    if (
        not isinstance(lines, list)
        or len(lines) > 1000
        or not all(isinstance(line, dict) for line in lines)
    ):
        raise ValueError("Invalid maintenance lines")

    def number(raw, required=False, positive=False):
        if raw is None or str(raw).strip() == "":
            if required:
                raise ValueError("Missing replacement quantity")
            return None
        if isinstance(raw, bool) or len(str(raw)) > 100:
            raise ValueError("Invalid replacement number")
        value = parse_maintenance_invoice_number(raw)
        if (
            not value.is_finite()
            or abs(value) > Decimal("999999999999.99")
            or value != value.quantize(Decimal("0.01"))
            or (positive and value <= 0)
        ):
            raise ValueError("Invalid replacement number")
        return value

    prepared = []
    for index, line in enumerate(lines):
        action = line.get("replacement_action")
        if action == "not_replace":
            continue
        if action == "review" and allow_unconfirmed:
            continue
        if action != "replace":
            raise ValueError("Unconfirmed replacement line")

        part_name = str(
            line.get("replacement_part_name") or ""
        ).strip()
        part_number = str(
            line.get("part_number") or ""
        ).strip()
        if not part_name or len(part_name) > 200:
            raise ValueError("Invalid replacement part name")
        if len(part_number) > 100:
            raise ValueError("Invalid replacement part number")

        prepared.append({
            "index": index,
            "version": hashlib.sha256(json.dumps(
                line,
                sort_keys=True,
                ensure_ascii=False,
                default=str,
            ).encode("utf-8")).hexdigest(),
            "part_name": part_name,
            "part_number": part_number or None,
            "quantity": number(
                line.get("quantity"),
                required=True,
                positive=True,
            ),
            "cost": number(line.get("parts_amount")),
            "notes": line.get("notes") or None,
        })

    if not prepared:
        return 0

    replacement_date = (
        record.completion_date or record.entry_date or ""
    )
    parsed_date = datetime.strptime(
        replacement_date, "%Y-%m-%d"
    ).date()
    if parsed_date.isoformat() != replacement_date:
        raise ValueError("Invalid replacement date")

    existing_sources = {
        item.source_line_index: item
        for item in VehiclePartReplacementSource.query.filter_by(
            company_code=record.company_code,
            maintenance_record_id=record.id,
        ).all()
    }

    now = datetime.now(
        ZoneInfo("Asia/Tokyo")
    ).isoformat(timespec="seconds")
    created_count = 0

    for item in prepared:
        existing = existing_sources.get(item["index"])
        if existing is not None:
            if existing.source_line_version != item["version"]:
                raise ValueError("Registered source line has changed")
            existing_part = db.session.get(
                VehiclePartReplacement,
                existing.replacement_id,
            )
            if (
                existing_part is None
                or existing_part.company_code != record.company_code
                or existing_part.vehicle_record_id != record.vehicle_record_id
                or existing_part.maintenance_record_id != record.id
            ):
                raise ValueError("Invalid replacement source link")
            continue

        part = VehiclePartReplacement(
            company_code=record.company_code,
            vehicle_record_id=record.vehicle_record_id,
            maintenance_record_id=record.id,
            part_name=item["part_name"],
            part_number=item["part_number"],
            quantity=item["quantity"],
            replacement_date=replacement_date,
            mileage=record.mileage,
            cost=item["cost"],
            notes=item["notes"],
            created_by_username=session.get("username"),
            created_at=now,
            updated_by_username=session.get("username"),
            updated_at=now,
        )
        db.session.add(part)
        db.session.flush()

        db.session.add(VehiclePartReplacementSource(
            company_code=record.company_code,
            maintenance_record_id=record.id,
            replacement_id=part.id,
            source_line_index=item["index"],
            source_line_version=item["version"],
        ))
        db.session.flush()
        created_count += 1

    return created_count


def get_vehicle_karte_parts_context(vehicle):
    from types import SimpleNamespace

    rows = (
        db.session.query(
            VehiclePartReplacement,
            VehicleMaintenanceRecord,
        )
        .join(
            VehicleMaintenanceRecord,
            VehiclePartReplacement.maintenance_record_id
            == VehicleMaintenanceRecord.id,
        )
        .filter(
            VehiclePartReplacement.company_code == vehicle.company_code,
            VehiclePartReplacement.vehicle_record_id == vehicle.id,
            VehicleMaintenanceRecord.company_code == vehicle.company_code,
            VehicleMaintenanceRecord.vehicle_record_id == vehicle.id,
        )
        .order_by(
            VehiclePartReplacement.replacement_date.asc(),
            VehiclePartReplacement.maintenance_record_id.asc(),
            VehiclePartReplacement.id.asc(),
        )
        .all()
    )

    maintenance = {
        record.id: record
        for record in VehicleMaintenanceRecord.query.filter_by(
            company_code=vehicle.company_code,
            vehicle_record_id=vehicle.id,
        ).all()
    }

    sources = (
        VehiclePartReplacementSource.query.filter_by(
            company_code=vehicle.company_code,
        )
        .filter(
            VehiclePartReplacementSource.maintenance_record_id.in_(
                list(maintenance)
            )
        )
        .all()
        if maintenance else []
    )
    source_map = {
        source.replacement_id: source for source in sources
    }
    line_map = {
        record.id: safe_json_dict_list(record.line_items_json)
        for record in maintenance.values()
    }

    groups = {}
    history = []
    pending = []

    for record in maintenance.values():
        for index, line in enumerate(line_map[record.id]):
            if (line.get("replacement_action") or "review") == "review":
                pending.append({
                    "maintenance_record_id": record.id,
                    "invoice_number": record.invoice_number,
                    "line_index": index,
                    "description": line.get("description") or "名称未読取",
                })

    for part, record in rows:
        key = (part.part_name, part.part_number or "")
        source = source_map.get(part.id)
        line = {}

        if source and source.maintenance_record_id == record.id:
            original = line_map.get(record.id, [])
            if 0 <= source.source_line_index < len(original):
                line = original[source.source_line_index]

        category = str(
            line.get("replacement_category") or "未分類"
        ).strip()[:50] or "未分類"
        status = record.status or (
            "完了" if record.completion_date else "未設定"
        )

        group = groups.setdefault(key, {
            "part_name": part.part_name,
            "part_number": part.part_number,
            "latest": part,
            "events": {},
            "category": category,
        })

        if record.id not in group["events"]:
            previous = (
                group["latest"].mileage if group["events"] else None
            )
            distance = (
                part.mileage - previous
                if previous is not None
                and part.mileage is not None
                and part.mileage >= previous
                else None
            )
            group["events"][record.id] = (
                len(group["events"]) + 1,
                distance,
            )

        count, distance = group["events"][record.id]
        group.update(latest=part, category=category)

        history.append({
            "part": part,
            "category": category,
            "status": status,
            "replacement_count": count,
            "distance": distance,
        })

    priorities = (
        "エンジンオイル",
        "オイルエレメント",
        "タイヤ",
        "ブレーキパッド",
        "ファンベルト",
        "バッテリ",
        "フューエルフィルタ",
        "エアクリーナ",
    )

    def normalize(value):
        return (
            "".join(value.split())
            .replace("・", "")
            .replace("ー", "")
        )

    part_groups = []
    for group in groups.values():
        group["replacement_count"] = len(group.pop("events"))
        name = normalize(group["part_name"])
        if any(
            word in name
            for word in (
                "ガスケット", "パッキン", "シール",
                "キャップ", "ドレン", "オイルパン",
            )
        ):
            group["priority"] = 99
        elif "オイル" in name and any(
            word in name for word in ("エレメント", "フィルタ")
        ):
            group["priority"] = 1
        else:
            group["priority"] = next(
                (
                    index
                    for index, word in enumerate(priorities)
                    if normalize(word) in name
                ),
                99,
            )
        part_groups.append(group)

    ranking = sorted(
        part_groups,
        key=lambda group: (
            -group["replacement_count"],
            group["part_name"],
            group["part_number"] or "",
        ),
    )

    state_scope = request.args.get("parts_scope", "major")
    if state_scope not in {"major", "all"}:
        state_scope = "major"

    major = sorted(
        (
            group for group in part_groups
            if group["priority"] < 99
        ),
        key=lambda group: (
            group["priority"],
            group["part_name"],
            group["part_number"] or "",
        ),
    )[:6]

    state_groups = (
        major if state_scope == "major"
        else sorted(
            part_groups,
            key=lambda group: (
                group["part_name"],
                group["part_number"] or "",
            ),
        )
    )

    search_query = (request.args.get("q") or "").strip()[:200]
    selected_category = (
        request.args.get("part_category") or ""
    ).strip()[:50]
    selected_status = (
        request.args.get("part_status") or ""
    ).strip()[:50]

    categories = sorted({row["category"] for row in history})
    statuses = sorted({row["status"] for row in history})

    if selected_category not in categories:
        selected_category = ""
    if selected_status not in statuses:
        selected_status = ""

    filtered = [
        row for row in reversed(history)
        if (
            (
                not search_query
                or search_query.casefold() in (
                    row["part"].part_name
                    + " "
                    + (row["part"].part_number or "")
                ).casefold()
            )
            and (
                not selected_category
                or row["category"] == selected_category
            )
            and (
                not selected_status
                or row["status"] == selected_status
            )
        )
    ]

    per_page = request.args.get("per_page", 10, type=int)
    if per_page not in {10, 20, 50}:
        per_page = 10

    total = len(filtered)
    pages = max(1, (total + per_page - 1) // per_page)
    page = min(
        max(1, request.args.get("page", 1, type=int)),
        pages,
    )
    first = (page - 1) * per_page

    return {
        "part_rows": filtered[first:first + per_page],
        "part_groups": part_groups,
        "part_ranking": ranking[:5],
        "part_state_groups": state_groups,
        "part_categories": categories,
        "part_statuses": statuses,
        "part_search_query": search_query,
        "selected_part_category": selected_category,
        "selected_part_status": selected_status,
        "selected_parts_scope": state_scope,
        "pending_part_lines": pending,
        "part_page": SimpleNamespace(
            page=page,
            pages=pages,
            total=total,
            per_page=per_page,
            first=first + 1 if total else 0,
            last=min(first + per_page, total),
        ),
        "format_part_number": format_vehicle_maintenance_number,
    }


