class VehicleMaintenanceInspectionLink(db.Model):
    id = db.Column(db.Integer, primary_key=True)
    company_code = db.Column(db.String(50), nullable=False, index=True)
    vehicle_record_id = db.Column(db.Integer, db.ForeignKey("vehicle.id"), nullable=False, index=True)
    maintenance_record_id = db.Column(db.Integer, db.ForeignKey("vehicle_maintenance_record.id"), nullable=False, index=True)
    inspection_result_id = db.Column(db.Integer, db.ForeignKey("vehicle_checklist_result.id"), nullable=False, index=True)
    defect_no = db.Column(db.Integer, nullable=False)
    __table_args__ = (db.UniqueConstraint("maintenance_record_id", "inspection_result_id", "defect_no", name="uq_maintenance_inspection_defect"),)


def get_maintenance_inspection_choices(vehicle, record):
    links = VehicleMaintenanceInspectionLink.query.filter_by(
        company_code=vehicle.company_code, vehicle_record_id=vehicle.id,
        maintenance_record_id=record.id,
    ).all() if record is not None else []
    linked = {(row.inspection_result_id, row.defect_no) for row in links}
    choices = []
    results = VehicleChecklistResult.query.filter_by(
        company_code=vehicle.company_code, vehicle_record_id=vehicle.id,
    ).order_by(VehicleChecklistResult.id.asc()).all()
    for result in results:
        snapshot = safe_json_dict(result.checklist_snapshot_json)
        if not any(item.get("fixed_template_code") == "daily_inspection_truck_trailer" for item in snapshot.get("items", []) if isinstance(item, dict)):
            continue
        judgment = safe_json_dict(result.operation_judgment_json)
        for defect in judgment.get("defects", []):
            if not isinstance(defect, dict) or type(defect.get("defect_no")) is not int or defect["defect_no"] < 1:
                continue
            key = (result.id, defect["defect_no"])
            saved = key in linked
            if not saved:
                continue
            choices.append({
                "key": f"{key[0]}:{key[1]}",
                "token": f"{key[0]}:{key[1]}:{int(judgment.get('version') or 0)}",
                "linked": saved,
                "status": defect.get("status") or "",
                "label": f"{result.year}/{str(result.month).zfill(2)}/{str(result.day).zfill(2)} No.{int(defect.get('item_no', 0)) + 1} " + str((defect.get("reported_answer") or {}).get("content") or "点検指摘"),
                "link": url_for("vehicle_checklist_results", index=result.checklist_id, vehicle_record_id=vehicle.id, year=result.year, month=result.month, active_day=result.day) + f"#vehicle-flow-defect-{result.id}-{defect['defect_no']}",
            })
    if linked != {(int(c["key"].split(":")[0]), int(c["key"].split(":")[1])) for c in choices if c["linked"]}:
        raise ValueError("紐付け済みの点検指摘を確認できません。元の点検記録を確認してください。")
    return choices



def validate_maintenance_inspection_selection(choices, tokens):
    if len(tokens) > 100 or len(tokens) != len(set(tokens)):
        raise ValueError("点検指摘の選択内容を確認してください。")
    available = {choice["token"]: choice for choice in choices}
    if any(token not in available for token in tokens):
        raise ValueError("点検指摘が更新されています。画面を開き直してください。")
    selected = [available[token] for token in tokens]
    if not {c["key"] for c in choices if c["linked"]} <= {c["key"] for c in selected}:
        raise ValueError("保存済みの点検指摘との紐付けは解除できません。")
    return selected


def sync_maintenance_inspection_links(record, choices, values, intent, current_user):
    targets = []
    changed = False
    updated_results = []
    local_now = get_user_local_now(record.company_code, current_user.username)
    if intent == "complete":
        performed = datetime.strptime(values.get("completion_date") or "", "%Y-%m-%d")
        if performed.date() > local_now.date():
            raise ValueError("整備完了日に未来の日付は指定できません。")
    grouped = {}
    for choice in choices:
        result_id, defect_no = map(int, choice["key"].split(":"))
        grouped.setdefault(result_id, []).append((defect_no, choice))
    for result_id, selected in grouped.items():
        result = VehicleChecklistResult.query.filter_by(id=result_id, company_code=record.company_code, vehicle_record_id=record.vehicle_record_id).with_for_update().populate_existing().first()
        if result is None:
            raise ValueError("対象の点検記録を確認できません。")
        previous_json = result.operation_judgment_json
        previous = safe_json_dict(previous_json)
        version = int(previous.get("version") or 0)
        if any(choice["token"] != f"{result_id}:{number}:{version}" for number, choice in selected):
            raise ValueError("点検指摘が更新されています。画面を開き直してください。")
        for number, choice in selected:
            link = VehicleMaintenanceInspectionLink.query.filter_by(company_code=record.company_code, vehicle_record_id=record.vehicle_record_id, maintenance_record_id=record.id, inspection_result_id=result_id, defect_no=number).first()
            new_link = link is None
            if new_link:
                link = VehicleMaintenanceInspectionLink(company_code=record.company_code, vehicle_record_id=record.vehicle_record_id, maintenance_record_id=record.id, inspection_result_id=result_id, defect_no=number)
                db.session.add(link)
                changed = True
            defects = [dict(item) for item in previous.get("defects", [])]
            defect = next((d for d in defects if d.get("defect_no") == number), None)
            if defect is None:
                raise ValueError("対象の不具合を確認できません。")
            # Ordinary corrections do not reopen or complete an inspection defect.
            if intent != "complete":
                continue
            if defect.get("status") not in {"対応待ち", "整備中"}:
                raise ValueError("再確認中または解消済みの指摘です。元の点検画面で状態を確認してください。")
            next_status = "再確認待ち" if intent == "complete" else "整備中"
            date_text = values.get("completion_date") if intent == "complete" else values.get("entry_date")
            performed = datetime.strptime(date_text or "", "%Y-%m-%d")
            inspection_date = datetime(int(result.year), int(result.month), int(result.day)).date()
            if performed.date() < inspection_date or performed.date() > local_now.date():
                raise ValueError("整備実施日は点検日以降、今日以前にしてください。")
            repair = {
                "status": next_status,
                "note": values.get("repair_content") or values.get("content") or "",
                "performed_by": (current_user.last_name or "") + (current_user.first_name or ""),
                "performed_by_username": current_user.username,
                "performed_at": performed.strftime("%Y-%m-%d"),
                "recorded_at": local_now.strftime("%Y-%m-%d %H:%M:%S"),
                "notification_created_at": local_now.astimezone(ZoneInfo("UTC")).strftime("%Y-%m-%dT%H:%M:%SZ"),
                "timezone": str(local_now.tzinfo),
                "maintenance_record_id": record.id,
            }
            previous_defect = dict(defect)
            defect.update(status=next_status, repair=repair)
            judgment = {**previous, "defects": defects, "status": "未判定", "version": version + 1}
            for key in ("reason", "judged_by", "judged_by_username", "judged_at", "authority_role", "authority_confirmed", "checks_confirmed", "checks_evidence"):
                judgment.pop(key, None)
            targets.extend(persist_vehicle_inspection_repair(result, record.company_code, current_user, previous_json, judgment, next_status, repair, previous_defect, defect, previous, False))
            if result not in updated_results:
                updated_results.append(result)
            # The following selected defect belongs to the same transaction/version.
            previous = judgment
            previous_json = json.dumps(judgment, ensure_ascii=False)
            version += 1
            changed = True
    return targets, changed, updated_results


def dispatch_maintenance_inspection_notifications(targets):
    for user, notification in targets:
        try:
            dispatch_external_notification(user, notification.title, notification.message, notification.link, notification_id=notification.id)
        except Exception:
            app.logger.exception("不具合対応の外部通知に失敗しました。")


def carry_inspection_repair_to_maintenance(result_record, defect_no, previous_defect, repair, current_user):
    """Carry a known inspection repair into the karte in the caller's transaction."""
    company_code = result_record.company_code
    vehicle_id = result_record.vehicle_record_id
    vehicle = Vehicle.query.filter_by(id=vehicle_id, company_code=company_code).first()
    if vehicle is None or current_user.company_code != company_code:
        raise ValueError("INSPECTION_MAINTENANCE_SCOPE_INVALID")
    links = VehicleMaintenanceInspectionLink.query.filter_by(
        company_code=company_code, vehicle_record_id=vehicle_id,
        inspection_result_id=result_record.id, defect_no=defect_no,
    ).all()
    records = []
    for link in links:
        record = VehicleMaintenanceRecord.query.filter_by(
            id=link.maintenance_record_id, company_code=company_code,
            vehicle_record_id=vehicle_id,
        ).with_for_update().first()
        if record is None:
            raise ValueError("INSPECTION_MAINTENANCE_LINK_INVALID")
        records.append(record)

    previous_repair = previous_defect.get("repair") or {}
    previous_id = previous_repair.get("maintenance_record_id")
    if previous_id is not None and (
        type(previous_id) is not int or previous_id not in {row.id for row in records}
    ):
        raise ValueError("INSPECTION_MAINTENANCE_REFERENCE_INVALID")
    record = None
    if previous_defect.get("status") == "整備中" and previous_id is not None:
        record = next(row for row in records if row.id == previous_id)
        if record.status == "完了":
            raise ValueError("INSPECTION_MAINTENANCE_STATE_CONFLICT")
    else:
        unfinished = [row for row in records if row.status != "完了"]
        if len(unfinished) > 1:
            raise ValueError("INSPECTION_MAINTENANCE_AMBIGUOUS")
        record = unfinished[0] if unfinished else None

    created = record is None
    stamp = repair["recorded_at"]
    if created:
        record = VehicleMaintenanceRecord(
            company_code=company_code, vehicle_record_id=vehicle_id,
            category="修理", content=repair["note"],
            symptom=str((previous_defect.get("reported_answer") or {}).get("content") or ""),
            created_by_username=current_user.username, created_at=stamp,
        )
        db.session.add(record)
    status_before = record.status
    changes = []
    updates = {
        "repair_content": repair["note"],
        "status": "完了" if repair["status"] == "再確認待ち" else "整備中",
        "maintenance_person": repair["performed_by"],
    }
    if repair["status"] == "再確認待ち":
        updates["completion_date"] = repair["performed_at"][:10]
    for field, after in updates.items():
        before = getattr(record, field)
        if before != after:
            setattr(record, field, after)
            changes.append({"field": field, "before": before, "after": after})
    # An inspection repair date does not establish an arrival date, mileage or cost.
    record.updated_by_username = current_user.username
    record.updated_at = stamp
    db.session.flush()
    if created:
        db.session.add(VehicleMaintenanceInspectionLink(
            company_code=company_code, vehicle_record_id=vehicle_id,
            maintenance_record_id=record.id,
            inspection_result_id=result_record.id, defect_no=defect_no,
        ))
    repair["maintenance_record_id"] = record.id
    changes.append({
        "field": "inspection_repair", "before": previous_repair,
        "after": {"inspection_result_id": result_record.id, "defect_no": defect_no, **repair},
    })
    add_vehicle_maintenance_record_event(
        record, action="created" if created else "status_changed" if status_before != record.status else "updated",
        changes=changes, status_before=status_before,
    )
    return record


def persist_vehicle_inspection_repair(result_record, company_code, current_user, previous_json, judgment, next_status, repair, previous_defect, defect, previous, is_recheck):
    updated = VehicleChecklistResult.query.filter_by(
        id=result_record.id,
        company_code=company_code,
        operation_judgment_json=previous_json
    ).update(
        {"operation_judgment_json": json.dumps(judgment, ensure_ascii=False)},
        synchronize_session=False
    )
    if updated != 1:
        raise ValueError("INSPECTION_UPDATE_CONFLICT")

    invalidate_other_vehicle_operation_judgments(result_record)

    db.session.add(ChecklistEvent(
        company_code=company_code,
        result_type="vehicle",
        result_id=result_record.id,
        event_type=next_status,
        actor_username=current_user.username,
        actor_name=repair["performed_by"],
        created_at=repair["recorded_at"],
        detail_json=json.dumps({
            "previous_defect": previous_defect,
            "defect": defect,
            "repair": {} if is_recheck else repair,
            "recheck": repair if is_recheck else {},
            "previous_judgment": previous,
        }, ensure_ascii=False)
    ))

    notification_targets = []
    if next_status == "再確認待ち" or is_recheck:
        target_usernames = set(previous.get("requested_usernames") or [])

        if not target_usernames:
            inspector = User.query.filter_by(
                company_code=company_code,
                username=result_record.checked_by_username
            ).first()

            if inspector and inspector.office:
                target_usernames.update(
                    user.username
                    for user in User.query.filter_by(
                        company_code=company_code,
                        office=inspector.office,
                        role="admin"
                    ).all()
                )

        if result_record.checked_by_username:
            target_usernames.add(result_record.checked_by_username)

        vehicle = Vehicle.query.filter_by(
            id=result_record.vehicle_record_id,
            company_code=company_code
        ).first()
        vehicle_name = (
            " ".join(value for value in [
                vehicle.plate_area or "",
                vehicle.plate_class or "",
                vehicle.plate_kana or "",
                vehicle.plate_number or ""
            ] if value)
            if vehicle else ""
        ) or f"車両ID：{result_record.vehicle_record_id}"

        item_name = (
            defect.get("reported_answer", {}).get("content") or ""
        )

        if not is_recheck:
            notification_action = "再確認待ち"
            next_action = (
                "整備した箇所を再確認し、再確認結果を登録してください。"
            )
        elif next_status == "解消":
            notification_action = "再確認済み・異常なし"
            next_action = (
                "この不具合の再確認は完了しました。"
                "整備管理者は、ほかの未解消の不具合と点検結果を確認し、"
                "運行可否を判断してください。"
            )
        else:
            notification_action = "再確認で異常あり"
            next_action = (
                "異常が残っています。整備内容を確認し、"
                "追加の整備を登録してください。"
            )

        notification_title = (
            f"{vehicle_name}：{notification_action}"
        )
        notification_message = (
            f"対象車両：{vehicle_name}\n"
            f"点検日：{result_record.year}/{result_record.month}/{result_record.day}\n"
            f"項目：No.{int(defect.get('item_no', 0)) + 1} {item_name}\n"
            f"対応状況：{next_status}\n"
            f"次にすること：{next_action}\n"
            f"実施者：{repair['performed_by']}\n"
            f"実施日時：{repair['performed_at']}\n"
            f"内容：{repair['note']}"
        )
        notification_link = url_for(
            "vehicle_checklist_results",
            index=result_record.checklist_id,
            vehicle_record_id=result_record.vehicle_record_id,
            year=result_record.year,
            month=result_record.month,
            active_day=result_record.day
        ) + (
            f"#vehicle-flow-defect-{result_record.id}-"
            f"{defect.get('defect_no')}"
        )

        for target_username in sorted(target_usernames):
            target_user = User.query.filter_by(
                company_code=company_code,
                username=target_username
            ).first()
            if not target_user:
                continue

            notification = Notification(
                company_code=company_code,
                target_user=(target_user.last_name or "")
                + (target_user.first_name or ""),
                target_username=target_user.username,
                title=notification_title,
                message=notification_message,
                link=notification_link,
                files_json="[]",
                read=False,
                created_at=repair["notification_created_at"]
            )
            db.session.add(notification)
            notification_targets.append((target_user, notification))

    return notification_targets


def vehicle_maintenance_record_version(record):
    snapshot = {
        column.key: getattr(record, column.key)
        for column in inspect(record).mapper.column_attrs
    }
    return hashlib.sha256(json.dumps(
        snapshot,
        sort_keys=True,
        ensure_ascii=False,
        default=str,
    ).encode("utf-8")).hexdigest()


@app.route(
    "/vehicle/karte/<int:vehicle_record_id>/maintenance/new",
    defaults={"record_id": None},
    methods=["GET", "POST"],
)
@app.route(
    "/vehicle/karte/<int:vehicle_record_id>/maintenance/<int:record_id>/edit",
    methods=["GET", "POST"],
)
@limiter.limit("20 per minute", methods=["POST"])
def vehicle_karte_maintenance_form(vehicle_record_id, record_id):
    if not require_master_admin():
        return "整備記録の登録・編集は管理者のみ利用できます。", 403

    vehicle = Vehicle.query.filter_by(
        id=vehicle_record_id,
        company_code=session.get("company_code"),
    ).first_or_404()

    if request.method == "POST" and periodic_followups.for_maintenance(vehicle.company_code, record_id):
        periodic_followups.lock(vehicle.company_code)

    if request.method == "POST" and (
        request.form.getlist("inspection_defect")
        or (record_id is not None and VehicleMaintenanceInspectionLink.query.filter_by(
            company_code=vehicle.company_code, vehicle_record_id=vehicle.id,
            maintenance_record_id=record_id,
        ).first() is not None)
    ):
        lock_error = lock_vehicle_inspection_updates(
            vehicle.company_code, vehicle_record_id=vehicle.id,
            checklist={"items": [{"fixed_template_code": "daily_inspection_truck_trailer"}]},
        )
        if lock_error is not None:
            return lock_error

    record = None
    if record_id is not None:
        query = VehicleMaintenanceRecord.query.filter_by(
            id=record_id,
            company_code=vehicle.company_code,
            vehicle_record_id=vehicle.id,
        )
        if request.method == "POST":
            query = query.with_for_update()
        record = query.first_or_404()

    field_names = (
        "content", "category", "status",
        "entry_date", "completion_date", "mileage",
        "symptom", "cause", "temporary_action", "repair_content",
        "maintenance_company", "maintenance_person", "repair_hours",
        "invoice_number", "invoice_date",
        "parts_cost", "labor_cost", "other_cost",
        "tax_amount", "total_cost", "notes",
    )
    form_values = {
        field: getattr(record, field) if record is not None else ""
        for field in field_names
    }
    record_version = (
        vehicle_maintenance_record_version(record) if record else ""
    )
    try:
        inspection_choices = get_maintenance_inspection_choices(vehicle, record)
    except ValueError:
        app.logger.warning("Unable to load maintenance inspection choices", exc_info=True)
        return "点検情報を確認できませんでした。画面を再読み込みしてください。", 409
    periodic_issues = periodic_followups.for_maintenance(vehicle.company_code, record_id)
    selected_inspection_tokens = [c["token"] for c in inspection_choices if c["linked"]]
    # Inspection repairs do not establish an arrival date. Keep that unknown
    # value editable without requiring the user to invent a date.
    entry_date_required = not (
        record is not None
        and not record.entry_date
        and (any(choice["linked"] for choice in inspection_choices) or periodic_issues)
    )
    selected_inspections = []
    intent = ""
    notification_targets = []
    inspection_results_updated = []
    errors = []
    response_status = 200

    if request.method == "POST":
        form_values = {
            field: request.form.get(field, "")
            for field in field_names
        }
        values, errors = validate_vehicle_maintenance_form(
            request.form, entry_date_required=entry_date_required,
        )
        intent = request.form.get("maintenance_action", "save")
        selected_inspection_tokens = request.form.getlist("inspection_defect")
        try:
            selected_inspections = validate_maintenance_inspection_selection(
                inspection_choices, selected_inspection_tokens,
            )
            if intent not in {"save", "draft", "complete"}:
                raise ValueError("保存操作を確認してください。")
            if intent == "complete":
                if not values.get("completion_date"):
                    raise ValueError("整備完了日を入力してください。")
                values["status"] = "完了"
            elif intent in {"draft", "save"}:
                values["status"] = record.status if record and record.status == "完了" else "整備中"
        except ValueError as error:
            errors.append((str(error), "inspection_defects"))

        if record is not None:
            submitted_version = request.form.get("record_version", "")
            if not secrets.compare_digest(
                submitted_version.encode("utf-8"),
                record_version.encode("ascii"),
            ):
                errors.append((
                    "この記録は別の操作で更新されています。最新の記録を確認してください。",
                    "record_version",
                ))
                response_status = 409
            record_version = submitted_version

        if errors:
            db.session.rollback()
            if response_status == 200:
                response_status = 400
        else:
            is_new = record is None
            changed_fields = [
                field for field in field_names
                if is_new or getattr(record, field) != values[field]
            ]
            status_before = record.status if record is not None else None
            changes = [
                {
                    "field": field,
                    "before": (
                        getattr(record, field) if not is_new else None
                    ),
                    "after": values[field],
                }
                for field in changed_fields
            ]

            if not changed_fields and intent != "complete" and all(c["linked"] for c in selected_inspections):
                flash("変更はありませんでした。", "success")
                return redirect(url_for(
                    "vehicle_karte_maintenance",
                    vehicle_record_id=vehicle.id,
                    record_id=record.id,
                ))

            try:
                now = datetime.now(
                    ZoneInfo("Asia/Tokyo")
                ).isoformat(timespec="seconds")

                if is_new:
                    record = VehicleMaintenanceRecord(
                        company_code=vehicle.company_code,
                        vehicle_record_id=vehicle.id,
                        created_by_username=session.get("username"),
                        created_at=now,
                    )
                    db.session.add(record)

                if not is_new and {
                    "mileage", "entry_date", "completion_date"
                }.intersection(changed_fields):
                    previous_date = (
                        record.completion_date or record.entry_date or ""
                    )
                    replacement_date = (
                        values["completion_date"] or values["entry_date"] or ""
                    )
                    previous_mileage = record.mileage
                    source_lines = safe_json_dict_list(record.line_items_json)
                    part_sources = (
                        VehiclePartReplacementSource.query.filter_by(
                            company_code=record.company_code,
                            maintenance_record_id=record.id,
                        ).all()
                    )

                    for source in part_sources:
                        index = source.source_line_index
                        if (
                            type(index) is not int
                            or not 0 <= index < len(source_lines)
                        ):
                            continue

                        line = source_lines[index]
                        line_version = hashlib.sha256(json.dumps(
                            line,
                            sort_keys=True,
                            ensure_ascii=False,
                            default=str,
                        ).encode("utf-8")).hexdigest()
                        if (
                            line.get("replacement_action") != "replace"
                            or source.source_line_version != line_version
                        ):
                            continue

                        part = (
                            VehiclePartReplacement.query.filter_by(
                                id=source.replacement_id,
                                company_code=record.company_code,
                                vehicle_record_id=record.vehicle_record_id,
                                maintenance_record_id=record.id,
                            )
                            .with_for_update()
                            .populate_existing()
                            .first()
                        )
                        if part is None:
                            continue

                        part_changes = []
                        if (
                            previous_date != replacement_date
                            and part.replacement_date == previous_date
                        ):
                            part_changes.append((
                                "replacement_date",
                                part.replacement_date,
                                replacement_date,
                            ))
                        if (
                            previous_mileage != values["mileage"]
                            and part.mileage == previous_mileage
                        ):
                            part_changes.append((
                                "mileage", part.mileage, values["mileage"],
                            ))

                        for field, before, after in part_changes:
                            setattr(part, field, after)
                            changes.append({
                                "field": f"part_replacement:{part.id}:{field}",
                                "before": before,
                                "after": after,
                            })
                        if part_changes:
                            part.updated_by_username = session.get("username")
                            part.updated_at = now

                for field in field_names:
                    setattr(record, field, values[field])

                record.updated_by_username = session.get("username")
                record.updated_at = now
                db.session.flush()
                saved_id = record.id
                if selected_inspections or intent == "complete":
                    current_user = User.query.filter_by(
                        company_code=vehicle.company_code,
                        username=session.get("username"),
                    ).first()
                    if not current_user:
                        raise ValueError("操作ユーザーを確認できません。")
                    notification_targets, links_changed, inspection_results_updated = sync_maintenance_inspection_links(
                        record, selected_inspections, values, intent, current_user,
                    )
                    if links_changed:
                        changes.append({
                            "field": "inspection_links",
                            "before": [c["key"] for c in inspection_choices if c["linked"]],
                            "after": [c["key"] for c in selected_inspections],
                        })

                if periodic_issues:
                    periodic_user = User.query.filter_by(company_code=vehicle.company_code, username=session.get("username")).first()
                    if periodic_user is None:
                        raise ValueError("操作ユーザーを確認できません。")
                    periodic_followups.sync_maintenance(record, intent, periodic_user)

                add_vehicle_maintenance_record_event(
                    record,
                    action=(
                        "created" if is_new
                        else "status_changed" if "status" in changed_fields
                        else "updated"
                    ),
                    changes=changes,
                    status_before=status_before,
                )

                add_audit_log(
                    action=(
                        "maintenance_created"
                        if is_new else "maintenance_updated"
                    ),
                    target_type="vehicle_maintenance_record",
                    target_id=saved_id,
                    detail=json.dumps({
                        "vehicle_record_id": vehicle.id,
                        "changed_fields": changed_fields,
                    }, ensure_ascii=False),
                    company_code=vehicle.company_code,
                )
                db.session.commit()

            except ValueError as error:
                db.session.rollback()
                errors.append((str(error), "inspection_defects"))
                response_status = 409

            except SQLAlchemyError:
                db.session.rollback()
                app.logger.exception("Maintenance record save failed")
                errors.append((
                    "保存できませんでした。時間をおいて再度お試しください。",
                    "",
                ))
                response_status = 500

            else:
                for result in inspection_results_updated:
                    try:
                        dispatch_vehicle_defect_notifications(result)
                    except Exception:
                        app.logger.exception("不具合対応の通知配信に失敗しました。")
                dispatch_maintenance_inspection_notifications(notification_targets)
                flash(
                    "整備記録を登録しました。"
                    if is_new else "整備記録を更新しました。",
                    "success",
                )
                return redirect(url_for(
                    "vehicle_karte_maintenance",
                    vehicle_record_id=vehicle.id,
                    record_id=saved_id,
                ))

    number = vehicle_number({
        "plate_area": vehicle.plate_area or "",
        "plate_class": vehicle.plate_class or "",
        "plate_kana": vehicle.plate_kana or "",
        "plate_number": vehicle.plate_number or "",
    })

    return render_template(
        "vehicle_karte_maintenance_form.html",
        vehicle=vehicle,
        vehicle_number=number,
        maintenance_record=record if record_id is not None else None,
        form_values=form_values,
        form_errors=errors,
        record_version=record_version,
        inspection_choices=inspection_choices,
        periodic_issues=periodic_issues,
        selected_inspection_tokens=selected_inspection_tokens,
        entry_date_required=entry_date_required,
    ), response_status


def format_vehicle_maintenance_number(value):
    if value is None or value == "" or isinstance(value, bool):
        return "—"
    try:
        amount = Decimal(str(value).replace(",", ""))
    except (InvalidOperation, TypeError, ValueError):
        return "—"
    if not amount.is_finite() or abs(amount) > Decimal("99999999999999.99"):
        return "—"
    text = format(amount, ",.2f")
    return text.rstrip("0").rstrip(".")


@app.route(
    "/vehicle/karte/<int:vehicle_record_id>/maintenance",
    defaults={"record_id": None},
)
@app.route(
    "/vehicle/karte/<int:vehicle_record_id>/maintenance/<int:record_id>"
)
def vehicle_karte_maintenance(vehicle_record_id, record_id):
    vehicle = Vehicle.query.filter_by(
        id=vehicle_record_id,
        company_code=session.get("company_code"),
    ).first_or_404()

    number = vehicle_number({
        "plate_area": vehicle.plate_area or "",
        "plate_class": vehicle.plate_class or "",
        "plate_kana": vehicle.plate_kana or "",
        "plate_number": vehicle.plate_number or "",
    })

    query = VehicleMaintenanceRecord.query.filter_by(
        company_code=vehicle.company_code,
        vehicle_record_id=vehicle.id,
    )
    import_batch = request.args.get("import_batch", "").strip()
    import_context = (
        get_vehicle_maintenance_import_context(import_batch)
        if import_batch else None
    )
    imported_record_ids = []
    if import_context:
        target = next((
            item for item in import_context["vehicles"]
            if item["id"] == vehicle.id
        ), None)
        if target is None:
            raise NotFound()
        imported_record_ids = target["record_ids"]

    selected_scope = request.args.get(
        "scope", "import" if import_context else "all"
    )
    if not import_context or selected_scope != "import":
        selected_scope = "all"

    selected_category = request.args.get("category", "").strip()
    selected_status = request.args.get("status", "").strip()
    start_date = request.args.get("start_date", "").strip()
    end_date = request.args.get("end_date", "").strip()

    maintenance_categories = [
        row[0] for row in query.with_entities(
            VehicleMaintenanceRecord.category
        ).filter(
            VehicleMaintenanceRecord.category.isnot(None),
            VehicleMaintenanceRecord.category != "",
        ).distinct().order_by(
            VehicleMaintenanceRecord.category
        ).all()
    ]
    maintenance_statuses = [
        row[0] for row in query.with_entities(
            VehicleMaintenanceRecord.status
        ).filter(
            VehicleMaintenanceRecord.status.isnot(None),
            VehicleMaintenanceRecord.status != "",
        ).distinct().order_by(
            VehicleMaintenanceRecord.status
        ).all()
    ]

    try:
        for date_value in (start_date, end_date):
            if date_value:
                parsed = datetime.strptime(date_value, "%Y-%m-%d")
                if parsed.strftime("%Y-%m-%d") != date_value:
                    raise ValueError()
        if start_date and end_date and start_date > end_date:
            raise ValueError()
    except ValueError:
        flash("期間を正しく指定してください。", "error")
        return redirect(url_for(
            "vehicle_karte_maintenance",
            vehicle_record_id=vehicle.id,
            import_batch=import_batch,
            scope=selected_scope,
        ))

    maintenance_date = db.func.coalesce(
        db.func.nullif(VehicleMaintenanceRecord.entry_date, ""),
        db.func.nullif(VehicleMaintenanceRecord.completion_date, ""),
        "",
    )

    if selected_scope == "import":
        query = query.filter(
            VehicleMaintenanceRecord.id.in_(imported_record_ids)
        )
    if selected_category:
        query = query.filter_by(category=selected_category)
    if selected_status:
        query = query.filter_by(status=selected_status)
    if start_date:
        query = query.filter(maintenance_date >= start_date)
    if end_date:
        query = query.filter(maintenance_date <= end_date)

    per_page = request.args.get("per_page", 10, type=int)
    if per_page not in {10, 20, 50}:
        per_page = 10

    maintenance_page = query.order_by(
        maintenance_date.desc(),
        VehicleMaintenanceRecord.id.desc(),
    ).paginate(
        page=max(1, request.args.get("page", 1, type=int)),
        per_page=per_page,
        error_out=False,
    )

    maintenance_record = None
    invoice_details = {}
    maintenance_lines = []
    source_url = None
    source_page = 1

    if record_id is not None:
        maintenance_record = query.filter_by(id=record_id).first_or_404()
    elif maintenance_page.items:
        maintenance_record = maintenance_page.items[0]

    if maintenance_record is not None:
        invoice_details = safe_json_dict(
            maintenance_record.invoice_details_json
        )
        maintenance_lines = safe_json_dict_list(
            maintenance_record.line_items_json
        )
        source = invoice_details.get("source")
        if isinstance(source, dict):
            draft_id = source.get("draft_id")
            if isinstance(draft_id, str) and draft_id.strip():
                source_url = url_for(
                    "vehicle_karte_document_source",
                    vehicle_record_id=vehicle.id,
                    draft_id=draft_id,
                )
            pages = source.get("pages")
            if isinstance(pages, list):
                valid_pages = [
                    page for page in pages
                    if isinstance(page, int)
                    and not isinstance(page, bool)
                    and page > 0
                ]
                if valid_pages:
                    source_page = min(valid_pages)

    return render_template(
        "vehicle_karte_maintenance.html",
        vehicle=vehicle,
        vehicle_number=number,
        maintenance_page=maintenance_page,
        import_context=import_context,
        imported_record_ids=imported_record_ids,
        selected_scope=selected_scope,
        maintenance_categories=maintenance_categories,
        maintenance_statuses=maintenance_statuses,
        selected_category=selected_category,
        selected_status=selected_status,
        start_date=start_date,
        end_date=end_date,
        maintenance_record=maintenance_record,
        periodic_issues=periodic_followups.for_maintenance(vehicle.company_code, maintenance_record.id if maintenance_record else None),
        maintenance_parts=(
            VehiclePartReplacement.query.filter_by(
                company_code=vehicle.company_code,
                vehicle_record_id=vehicle.id,
                maintenance_record_id=maintenance_record.id,
            ).order_by(
                VehiclePartReplacement.replacement_date.desc(),
                VehiclePartReplacement.id.desc(),
            ).all()
            if maintenance_record is not None else []
        ),
        format_part_number=format_vehicle_maintenance_number,
        maintenance_events=(
            get_vehicle_maintenance_record_events(maintenance_record)
            if maintenance_record is not None else []
        ),
        invoice_details=invoice_details,
        maintenance_lines=maintenance_lines,
        maintenance_number=format_vehicle_maintenance_number,
        source_url=source_url,
        source_page=source_page,
        open_defects=get_vehicle_open_inspection_defects(
            vehicle.company_code,
            vehicle.id,
        ),
    )


@app.route("/master/vehicles/<int:vehicle_record_id>/karte/history")
@app.route("/vehicle/karte/<int:vehicle_record_id>/history")
def vehicle_karte_history(vehicle_record_id):
    vehicle = Vehicle.query.filter_by(
        id=vehicle_record_id,
        company_code=session.get("company_code")
    ).first_or_404()

    number = vehicle_number({
        "plate_area": vehicle.plate_area or "",
        "plate_class": vehicle.plate_class or "",
        "plate_kana": vehicle.plate_kana or "",
        "plate_number": vehicle.plate_number or ""
    })

    page = max(1, request.args.get("page", 1, type=int))
    selected_event_type = request.args.get("event_type", "").strip()
    selected_start_date = request.args.get("start_date", "").strip()
    selected_end_date = request.args.get("end_date", "").strip()

    history_date_errors = []

    for field_id, label, value in [
        ("history_start_date", "開始日", selected_start_date),
        ("history_end_date", "終了日", selected_end_date),
    ]:
        if not value:
            continue

        try:
            parsed_date = datetime.strptime(value, "%Y-%m-%d")
            if parsed_date.strftime("%Y-%m-%d") != value:
                raise ValueError
        except ValueError:
            history_date_errors.append((
                field_id,
                label + "を正しい日付で入力してください。",
            ))

    if (
        not history_date_errors
        and selected_start_date
        and selected_end_date
        and selected_start_date > selected_end_date
    ):
        history_date_errors.append((
            "history_end_date",
            "終了日は開始日以降の日付を選択してください。",
        ))

    for field_id, message in history_date_errors:
        flash(message, "error:" + field_id)

    from types import SimpleNamespace

    history_entries = get_vehicle_karte_history_entries(
        vehicle.company_code,
        vehicle.id
    )

    history_event_types = sorted({
        entry["kind"]
        for entry in history_entries
        if entry["kind"]
    })

    history_statuses = sorted({
        entry["status"]
        for entry in history_entries
        if entry["status"]
    })

    selected_status = request.args.get("status", "").strip()

    if history_date_errors:
        history_entries = []
    else:
        history_entries = [
            entry
            for entry in history_entries
            if (
                (
                    not selected_event_type
                    or entry["kind"] == selected_event_type
                )
                and (
                    not selected_status
                    or entry["status"] == selected_status
                )
                and (
                    not selected_start_date
                    or entry["date"] >= selected_start_date
                )
                and (
                    not selected_end_date
                    or (
                        entry["date"]
                        and entry["date"] <= selected_end_date
                    )
                )
            )
        ]

    per_page = request.args.get("per_page", 10, type=int)
    if per_page not in {10, 20, 50}:
        per_page = 10

    total = len(history_entries)
    pages = max(1, (total + per_page - 1) // per_page)
    page = min(page, pages)
    offset = (page - 1) * per_page

    history_page = SimpleNamespace(
        items=history_entries[offset:offset + per_page],
        total=total,
        page=page,
        pages=pages,
        per_page=per_page,
        first=offset + 1 if total else 0,
        last=min(offset + per_page, total),
        has_prev=page > 1,
        has_next=page < pages,
        prev_num=page - 1 if page > 1 else None,
        next_num=page + 1 if page < pages else None
    )

    return render_template(
        "vehicle_karte_history.html",
        vehicle=vehicle,
        vehicle_number=number,
        history_page=history_page,
        history_links={},
        history_details={},
        history_event_types=history_event_types,
        history_statuses=history_statuses,
        selected_event_type=selected_event_type,
        selected_status=selected_status,
        selected_start_date=selected_start_date,
        selected_end_date=selected_end_date,
        open_defects=get_vehicle_open_inspection_defects(
            vehicle.company_code,
            vehicle.id
        )
    ), (400 if history_date_errors else 200)


def get_vehicle_karte_usage_vehicles():
    company_code = session.get("company_code")
    username = session.get("username")

    if not company_code or not username:
        return []

    current_driver = Driver.query.filter_by(
        company_code=company_code,
        employee_id=username
    ).first()

    if current_driver is None:
        return []

    vehicle_ids = []
    for value in safe_json_str_list(
        current_driver.vehicles_json
    ):
        if not value.isdigit() or len(value) > 18:
            continue

        vehicle_id = int(value)
        if vehicle_id > 0 and vehicle_id not in vehicle_ids:
            vehicle_ids.append(vehicle_id)

    if not vehicle_ids:
        return []

    records = Vehicle.query.filter(
        Vehicle.company_code == company_code,
        Vehicle.deleted == False,
        Vehicle.id.in_(vehicle_ids)
    ).all()

    record_map = {
        record.id: record
        for record in records
    }

    return [
        record_map[vehicle_id]
        for vehicle_id in vehicle_ids
        if vehicle_id in record_map
    ]


# PREVENTIVE_SYNTHETIC_SOURCE_V1
def vehicle_maintenance_synthetic_evidence(row):
    """Explicit synthetic-document declarations only; never infer from 'test'."""
    import unicodedata
    details = safe_json_dict(getattr(row, "invoice_details_json", "{}"))
    for field, value in (
        ("notes", getattr(row, "notes", None)),
        ("attached_invoice_notes", details.get("attached_invoice_notes")),
    ):
        if not isinstance(value, str):
            continue
        normalized = re.sub(r"\s+", "", unicodedata.normalize("NFKC", value))
        # A compound declaration from the source, not a generic maintenance/test term.
        declarations = ("テスト用資料・支払不要(発行元・取引内容は架空です)",)
        matched = next((text for text in declarations if normalized.startswith(text)), None)
        if matched is None:
            continue
        source = details.get("source")
        source = source if isinstance(source, dict) else {}
        return {
            "source_id": f"maintenance:{row.id}",
            "company_code": row.company_code,
            "vehicle_record_id": row.vehicle_record_id,
            "reason": "explicit_synthetic_document_declaration",
            "evidence_field": field,
            "declaration": matched,
            "document_source": {
                key: source.get(key) for key in ("sha256", "pages", "record_index")
            },
            "scope": "Excluded from factual calculations; stored records retained.",
        }
    return None


def filter_vehicle_maintenance_factual_history(maintenance, parts=()):
    """Apply one parent decision to children, retaining company/vehicle boundaries."""
    kept, excluded, parents = [], [], {}
    for row in maintenance:
        evidence = vehicle_maintenance_synthetic_evidence(row)
        key = (row.company_code, row.vehicle_record_id, row.id)
        if evidence is not None:
            excluded.append(evidence)
        else:
            kept.append(row)
            parents[key] = row
    kept_parts = [
        row for row in parts
        if (row.company_code, row.vehicle_record_id, row.maintenance_record_id) in parents
    ]
    return kept, kept_parts, excluded


def build_vehicle_karte_mileage_reference(
    maintenance_records, operation_records, as_of,
    periodic_records=(),
):
    """記録距離と出典を選ぶ。現在の実測値とは断定しない。"""
    from decimal import Decimal, InvalidOperation

    def day(value):
        try:
            return datetime.strptime(
                str(value or "").strip()[:10].replace("/", "-"),
                "%Y-%m-%d",
            ).date()
        except ValueError:
            return None

    today = datetime.now(ZoneInfo("Asia/Tokyo")).date()
    requested = day(as_of)
    if requested is None:
        raise ValueError("走行距離の基準日が不正です。")
    limit = min(requested, today)

    readings = []
    excluded = {
        "invalid_value": 0,
        "unknown_date": 0,
        "future_date": 0,
        "after_as_of": 0,
    }

    def add(value, date_value, source_id, source, date_basis, time=""):
        if value is None or str(value).strip() == "":
            return
        try:
            if isinstance(value, bool):
                raise ValueError()
            number = Decimal(str(value))
            if not number.is_finite() or number < 0:
                raise ValueError()
        except (InvalidOperation, ValueError, TypeError):
            excluded["invalid_value"] += 1
            return

        recorded = day(date_value)
        if recorded is None:
            excluded["unknown_date"] += 1
            return
        if recorded > today:
            excluded["future_date"] += 1
            return
        if recorded > limit:
            excluded["after_as_of"] += 1
            return

        readings.append({
            "value": number,
            "date": recorded.isoformat(),
            "time": str(time or "").strip(),
            "source_id": source_id,
            "source": source,
            "date_basis": date_basis,
        })

    for row in operation_records:
        add(
            row.arrival_meter,
            row.operation_date,
            f"operation:{row.id}",
            "運行実績",
            "operation_date",
            row.arrival_at,
        )

    maintenance_records, _, synthetic_exclusions = filter_vehicle_maintenance_factual_history(maintenance_records)
    excluded["explicit_synthetic_document"] = len(synthetic_exclusions)
    for row in maintenance_records:
        entry = str(row.entry_date or "").strip()
        add(
            row.mileage,
            entry or row.completion_date,
            f"maintenance:{row.id}",
            "整備・修理記録",
            "entry_date" if entry else "completion_date",
        )

    for row in periodic_records:
        if periodic_inspection_synthetic_evidence(row):
            excluded["explicit_synthetic_document"] += 1
            continue
        add(
            row.mileage,
            row.inspection_date,
            f"periodic:{row.id}",
            "定期点検記録",
            "inspection_date",
        )

    by_date = {}
    for reading in readings:
        by_date.setdefault(reading["date"], []).append(reading)

    daily = []
    conflicts = []
    decreases = []
    previous = None

    for recorded, rows in sorted(by_date.items()):
        operations = [
            row for row in rows if row["source"] == "運行実績"
        ]
        others = [
            row for row in rows if row["source"] != "運行実績"
        ]

        timed_operations = []
        for row in operations:
            try:
                timestamp = datetime.fromisoformat(row["time"])
            except ValueError:
                break
            if timestamp.tzinfo is not None:
                timestamp = timestamp.astimezone(
                    ZoneInfo("Asia/Tokyo")
                )
            if timestamp.date().isoformat() != recorded:
                break
            timed_operations.append((
                timestamp.replace(tzinfo=None), row,
            ))

        if operations and len(timed_operations) == len(operations):
            timed_operations.sort(key=lambda item: item[0])
            previous_values = (
                {previous} if previous is not None else None
            )
            for timestamp in sorted({
                item[0] for item in timed_operations
            }):
                values_at_time = {
                    row["value"]
                    for time_value, row in timed_operations
                    if time_value == timestamp
                }
                if len(values_at_time) != 1:
                    if recorded not in conflicts:
                        conflicts.append(recorded)
                if (
                    previous_values is not None
                    and min(values_at_time) < max(previous_values)
                    and recorded not in decreases
                ):
                    decreases.append(recorded)
                previous_values = values_at_time

            latest_time = timed_operations[-1][0]
            operations = [
                row for timestamp, row in timed_operations
                if timestamp == latest_time
            ]

        candidates = operations + others
        values = {row["value"] for row in candidates}
        if len(values) != 1:
            conflicts.append(recorded)
            daily.append({
                "date": recorded,
                "value": None,
                "sources": candidates,
            })
            continue

        value = next(iter(values))
        if previous is not None and value < previous:
            decreases.append(recorded)
        previous = value
        daily.append({
            "date": recorded,
            "value": value,
            "sources": candidates,
        })

    latest = daily[-1] if daily else None
    status = (
        "unknown" if latest is None
        else "conflicting" if latest["value"] is None
        else "recorded"
    )
    return {
        "as_of": limit.isoformat(),
        "status": status,
        "value": latest["value"] if latest else None,
        "date": latest["date"] if latest else None,
        "sources": latest["sources"] if latest else [],
        "conflict_dates": conflicts,
        "decrease_dates": decreases,
        "distance_usable": (
            status == "recorded"
            and not conflicts
            and not decreases
            and all(
                row["date_basis"] == "operation_date"
                for row in latest["sources"]
            )
        ),
        "excluded": excluded,
        "note": (
            "最後に登録された距離であり、現在の実測値ではありません。"
            "整備の入庫日・完了日は距離の計測日とは限りません。"
            "距離の減少だけでメーター交換や入力誤りを確定しません。"
        ),
    }


def build_vehicle_karte_analysis_summary(
    maintenance_records, operation_records, part_records,
    defect_records, start_date, end_date,
    periodic_records=(),
):
    from collections import Counter

    def parse_date(value):
        try:
            return datetime.strptime(
                str(value or "")[:10], "%Y-%m-%d"
            ).date()
        except ValueError:
            return None

    start = parse_date(start_date)
    end = parse_date(end_date)
    if start is None or end is None or start > end:
        raise ValueError("分析期間が不正です。")

    def in_period(value):
        day = parse_date(value)
        return day is not None and start <= day <= end

    maintenance, factual_parts, synthetic_exclusions = filter_vehicle_maintenance_factual_history(maintenance_records, part_records)
    periodic_records = list(periodic_records)
    synthetic_exclusions.extend(evidence for row in periodic_records if (evidence := periodic_inspection_synthetic_evidence(row)))
    periodic_records = [row for row in periodic_records if not periodic_inspection_synthetic_evidence(row)]
    operations = list(operation_records)
    parts = factual_parts
    defects = list(defect_records)

    selected_maintenance = [
        row for row in maintenance
        if in_period(row.entry_date or row.completion_date)
    ]
    selected_operations = [
        row for row in operations
        if in_period(row.operation_date)
    ]
    selected_parts = [
        row for row in parts
        if in_period(row.replacement_date)
    ]
    failures = [
        row for row in defects
        if row.category == "故障"
        and in_period(row.occurred_date)
    ]

    def known_total(rows, field):
        values = [getattr(row, field) for row in rows]
        known = [
            Decimal(str(value))
            for value in values if value is not None
        ]
        return sum(known, Decimal("0")) if known else None

    monthly = {}
    month_count = (
        (end.year - start.year) * 12
        + end.month - start.month + 1
    )
    for offset in range(month_count):
        year, month = divmod(
            start.year * 12 + start.month - 1 + offset,
            12,
        )
        key = f"{year:04d}-{month + 1:02d}"
        monthly[key] = {
            "month": key,
            "cost": None,
            "distance": None,
            "failures": 0,
        }

    for rows, field, date_field, result_field in (
        (
            selected_maintenance,
            "total_cost", "entry_date", "cost",
        ),
        (
            selected_operations,
            "distance", "operation_date", "distance",
        ),
    ):
        for row in rows:
            day = parse_date(
                getattr(row, date_field)
                or getattr(row, "completion_date", None)
            )
            value = getattr(row, field)
            if value is not None:
                bucket = monthly[day.strftime("%Y-%m")]
                bucket[result_field] = (
                    bucket[result_field] or Decimal("0")
                ) + Decimal(str(value))

    for row in failures:
        key = parse_date(
            row.occurred_date
        ).strftime("%Y-%m")
        monthly[key]["failures"] += 1

    cost = known_total(selected_maintenance, "total_cost")
    distance = known_total(selected_operations, "distance")
    missing_cost = sum(
        row.total_cost is None
        for row in selected_maintenance
    )
    missing_distance = sum(
        row.distance is None
        for row in selected_operations
    )

    mileage_reference = build_vehicle_karte_mileage_reference(
        maintenance,
        operations,
        end.isoformat(),
        periodic_records=periodic_records,
    )

    mileage_reference["excluded"]["explicit_synthetic_document"] += len(synthetic_exclusions)

    category_costs = {}
    for row in selected_maintenance:
        if row.total_cost is not None:
            category = (
                row.category or ""
            ).strip() or "未分類"
            category_costs[category] = (
                category_costs.get(category, Decimal("0"))
                + Decimal(str(row.total_cost))
            )

    return {
        "source_exclusions": synthetic_exclusions,
        "start_date": start.isoformat(),
        "end_date": end.isoformat(),
        "total_cost": cost,
        "all_time_cost": known_total(
            maintenance, "total_cost"
        ),
        "distance": distance,
        "mileage_reference": mileage_reference,
        "current_mileage": (
            mileage_reference["value"]
            if mileage_reference["distance_usable"] else None
        ),
        "current_mileage_date": (
            mileage_reference["date"]
            if mileage_reference["distance_usable"] else None
        ),
        "cost_per_km": (
            cost / distance
            if cost is not None
            and distance is not None
            and distance > 0
            and not missing_cost
            and not missing_distance
            else None
        ),
        "maintenance_count": len(selected_maintenance),
        "failure_count": len(failures),
        "part_replacement_count": len({
            (
                row.maintenance_record_id,
                row.part_name,
                row.part_number or "",
            )
            for row in selected_parts
        }),
        "missing_cost_count": missing_cost,
        "missing_distance_count": missing_distance,
        "undated_maintenance_count": sum(
            parse_date(
                row.entry_date or row.completion_date
            ) is None
            for row in maintenance
        ),
        "monthly": list(monthly.values()),
        "category_costs": sorted(
            category_costs.items(),
            key=lambda item: (-item[1], item[0]),
        ),
        "repeated_failure_contents": Counter(
            (row.content or "内容未登録").strip()
            or "内容未登録"
            for row in failures
        ).most_common(5),
    }


def vehicle_karte_analysis_matches_input(bundle, payload):
    previous = bundle.get("fingerprints")
    current = payload["_fingerprints"]
    return isinstance(previous, dict) and all(
        key in previous and key in current and previous[key] == current[key]
        for key in ("policy_version", "important_hash", "routine_hash")
    )


@app.route("/vehicle/karte/<int:vehicle_record_id>/analysis/result")
def vehicle_karte_analysis_result(vehicle_record_id):
    if not session.get("username"):
        return jsonify(
            ok=False,
            message="ログインし直してください。",
        ), 401

    vehicle = Vehicle.query.filter_by(
        id=vehicle_record_id,
        company_code=session.get("company_code"),
        deleted=False,
    ).first_or_404()

    state = VehicleKarteAnalysis.query.filter_by(
        company_code=vehicle.company_code,
        vehicle_record_id=vehicle.id,
    ).first()

    bundle = safe_json_dict(state.result_json) if state else {}
    analysis = bundle.get("analysis")
    has_result = isinstance(analysis, dict)
    status = state.status if state else "waiting"

    # PREVENTIVE_ANALYSIS_UI_FRESHNESS_V1: completed alone does not prove freshness.
    is_current = None
    input_summary = None
    scheduled_comparison = None
    try:
        current_payload, _current_sources = get_vehicle_karte_analysis_job_data(vehicle)
        scheduled_comparison = current_payload.get("comparison")
        input_records = current_payload.get("records", [])
        input_summary = {
            label: sum(str(row.get("source_id", "")).startswith(prefix) for row in input_records)
            for label, prefix in (("daily_inspections", "inspection:"), ("periodic_inspections", "periodic:"), ("maintenance", "maintenance:"), ("parts", "part:"))
        }
        if has_result:
            is_current = vehicle_karte_analysis_matches_input(bundle, current_payload)
    except Exception:
        app.logger.warning("車両分析の入力・更新状態を確認できませんでした。vehicle_id=%s", vehicle.id)

    if status == "completed" and is_current is True:
        message = "現在の登録内容に対応する分析結果です。"
    elif status == "completed" and is_current is False:
        message = "更新待ち"
    elif status == "completed":
        message = "状態未確認"
    elif status == "running":
        message = "新しい情報を分析しています。"
    elif status == "pending":
        message = (
            "登録内容の変更を確認しました。"
            "自動更新を予定しています。"
        )
    elif status == "error":
        message = (
            "自動更新に失敗しました。"
            "時間をおいて自動で再試行します。"
        )
    else:
        message = "自動分析の準備中です。"

    if has_result and status in {"running", "pending", "error"}:
        message += " 現在は前回の結果を表示しています。"

    response = jsonify(
        ok=True,
        status=status,
        has_result=has_result,
        is_current=is_current,
        input_summary=input_summary,
        scheduled_comparison=scheduled_comparison,
        message=message,
        analysis=analysis_with_vehicle_feedback(analysis, vehicle) if has_result else None,
        sources=bundle.get("sources") if has_result else {},
        coverage=bundle.get("coverage") if has_result else {},
        comparison=(
            bundle["comparison"]
            if has_result and isinstance(bundle.get("comparison"), dict)
            else None
        ),
        generated_at=(
            bundle.get("generated_at") if has_result else None
        ),
        analysis_method=(
            bundle.get("analysis_method") if has_result else None
        ),
    )
    response.headers["Cache-Control"] = "no-store"
    return response


def get_vehicle_karte_analysis_job_data(vehicle):
    today = datetime.now(ZoneInfo("Asia/Tokyo")).date()
    start = today.replace(
        year=today.year - 2,
        day=min(
            today.day,
            calendar.monthrange(today.year - 2, today.month)[1],
        ),
    )

    maintenance = VehicleMaintenanceRecord.query.filter_by(
        company_code=vehicle.company_code,
        vehicle_record_id=vehicle.id,
    ).all()

    operations = VehicleOperationRecord.query.filter_by(
        company_code=vehicle.company_code,
        vehicle_record_id=vehicle.id,
    ).filter(
        VehicleOperationRecord.operation_date <= today.isoformat(),
    ).all()

    parts = (
        VehiclePartReplacement.query.join(
            VehicleMaintenanceRecord,
            VehiclePartReplacement.maintenance_record_id
            == VehicleMaintenanceRecord.id,
        )
        .filter(
            VehiclePartReplacement.company_code == vehicle.company_code,
            VehiclePartReplacement.vehicle_record_id == vehicle.id,
            VehicleMaintenanceRecord.company_code == vehicle.company_code,
            VehicleMaintenanceRecord.vehicle_record_id == vehicle.id,
        )
        .all()
    )

    defects = VehiclePatrol.query.filter_by(
        company_code=vehicle.company_code,
        vehicle_record_id=vehicle.id,
    ).all()

    summary = build_vehicle_karte_analysis_summary(
        maintenance,
        operations,
        parts,
        defects,
        start.isoformat(),
        today.isoformat(),
        periodic_records=(
            VehiclePeriodicInspectionRecord.query.filter_by(
                company_code=vehicle.company_code,
                vehicle_record_id=vehicle.id,
            ).all()
        ),
    )
    import os

    registration_scope = os.environ.get(
        "VEHICLE_KARTE_AI_PEER_REGISTRATION", "same_year"
    ).strip()
    inactive_setting = os.environ.get(
        "VEHICLE_KARTE_AI_PEER_INCLUDE_INACTIVE", "0"
    ).strip()

    if registration_scope not in {"same_year", "all_years"}:
        raise ValueError(
            "VEHICLE_KARTE_AI_PEER_REGISTRATION must be "
            "same_year or all_years"
        )
    if inactive_setting not in {"0", "1"}:
        raise ValueError(
            "VEHICLE_KARTE_AI_PEER_INCLUDE_INACTIVE must be 0 or 1"
        )

    comparison = get_vehicle_karte_peer_comparison(
        vehicle,
        summary,
        registration_scope=registration_scope,
        include_inactive=inactive_setting == "1",
    )
    comparison["comparison_scope"]["condition_source"] = (
        "automatic_analysis_configuration"
    )

    return build_vehicle_karte_analysis_payload(
        vehicle,
        summary,
        comparison,
        maintenance,
        parts,
        defects,
    )


def run_vehicle_karte_analysis_job(state_id):
    """専用のバックグラウンド処理から呼び出す。"""
    now = datetime.now(ZoneInfo("UTC"))
    state = db.session.get(VehicleKarteAnalysis, state_id)
    if state is None:
        return False

    claimed_hash = state.input_hash
    token = str(uuid4())

    claimed = VehicleKarteAnalysis.query.filter(
        VehicleKarteAnalysis.id == state_id,
        VehicleKarteAnalysis.input_hash == claimed_hash,
        VehicleKarteAnalysis.status.in_({"pending", "error", "running"}),
        VehicleKarteAnalysis.next_analysis_at <= now,
        db.or_(
            VehicleKarteAnalysis.lease_expires_at.is_(None),
            VehicleKarteAnalysis.lease_expires_at <= now,
        ),
    ).update(
        {
            "status": "running",
            "lease_token": token,
            "lease_expires_at": now + timedelta(minutes=3),
        },
        synchronize_session=False,
    )
    db.session.commit()

    if not claimed:
        return False

    try:
        vehicle = Vehicle.query.filter_by(
            id=state.vehicle_record_id,
            company_code=state.company_code,
            deleted=False,
        ).first()

        if vehicle is None:
            VehicleKarteAnalysis.query.filter_by(
                id=state_id,
                lease_token=token,
            ).update(
                {
                    "status": "skipped",
                    "next_analysis_at": None,
                    "lease_token": None,
                    "lease_expires_at": None,
                    "last_error": "対象車両が存在しないか、無効になっています。",
                },
                synchronize_session=False,
            )
            db.session.commit()
            return True

        with app.test_request_context("/"):
            payload, sources = get_vehicle_karte_analysis_job_data(vehicle)

        fingerprints = payload["_fingerprints"]
        snapshot_hash = hashlib.sha256(
            json.dumps(
                fingerprints,
                sort_keys=True,
                ensure_ascii=False,
            ).encode("utf-8")
        ).hexdigest()

        method = (
            "ai"
            if fingerprints["has_important_history"]
            else "record_check"
        )

        if method == "ai":
            def renew_analysis_lease():
                renewed = VehicleKarteAnalysis.query.filter_by(
                    id=state_id,
                    lease_token=token,
                    status="running",
                ).update(
                    {
                        "lease_expires_at": (
                            datetime.now(ZoneInfo("UTC"))
                            + timedelta(minutes=3)
                        ),
                    },
                    synchronize_session=False,
                )
                if renewed != 1:
                    db.session.rollback()
                    raise RuntimeError("ANALYSIS_LEASE_LOST")
                db.session.commit()

            analysis = analyze_vehicle_karte(
                payload,
                on_progress=renew_analysis_lease,
            )
        else:
            analysis = {
                "overview": (
                    "AIの対応候補を作るための"
                    "整備・不具合・点検指摘の履歴はありません。"
                ),
                "recommendations": [],
            }

        finished = datetime.now(ZoneInfo("UTC"))
        bundle = {
            "analysis": analysis,
            "sources": sources,
            "coverage": payload["coverage"],
            "comparison": payload.get("comparison"),
            "fingerprints": fingerprints,
            "analysis_method": method,
            "generated_at": finished.astimezone(
                ZoneInfo("Asia/Tokyo")
            ).strftime("%Y/%m/%d %H:%M"),
        }

        db.session.expire_all()
        state = (
            VehicleKarteAnalysis.query.filter_by(
                id=state_id,
                lease_token=token,
            )
            .with_for_update()
            .first()
        )

        if state is None:
            db.session.rollback()
            return False

        changed = state.input_hash not in {
            claimed_hash,
            snapshot_hash,
        }

        state.result_json = json.dumps(
            bundle,
            ensure_ascii=False,
            default=str,
        )
        state.last_analyzed_at = (
            finished if method == "ai" else None
        )
        state.last_error = None
        state.lease_token = None
        state.lease_expires_at = None

        if changed:
            state.status = "pending"
            state.next_analysis_at = finished + timedelta(minutes=2)
        else:
            state.status = "completed"
            state.input_hash = snapshot_hash
            state.next_analysis_at = None

        db.session.commit()
        return True

    except Exception as error:
        db.session.rollback()

        code = f"{type(error).__name__}: {error}"
        key = os.environ.get("OPENAI_API_KEY", "")
        if key:
            code = code.replace(key, "[REDACTED]")
        code = code[:500]

        app.logger.warning(
            "車両自動分析に失敗しました: %s",
            code,
        )

        VehicleKarteAnalysis.query.filter_by(
            id=state_id,
            lease_token=token,
        ).update(
            {
                "status": "error",
                "last_error": code,
                "next_analysis_at": (
                    datetime.now(ZoneInfo("UTC"))
                    + timedelta(hours=1)
                ),
                "lease_token": None,
                "lease_expires_at": None,
            },
            synchronize_session=False,
        )
        db.session.commit()
        return False


@app.cli.command("vehicle-karte-analysis-worker")
def vehicle_karte_analysis_worker():
    """自動分析を専用プロセスで継続実行する。"""
    import time

    print(
        "車両分析の自動更新を開始します。停止する場合は Ctrl+C。",
        flush=True,
    )

    try:
        while True:
            try:
                from click import get_current_context

                get_current_context().invoke(
                    app.cli.commands["vehicle-karte-analysis-tick"]
                )

            except Exception:
                db.session.rollback()
                app.logger.exception(
                    "車両分析の定期処理に失敗しました。"
                )

            finally:
                db.session.remove()

            time.sleep(60)

    except KeyboardInterrupt:
        print(
            "車両分析の自動更新を停止しました。",
            flush=True,
        )


@app.cli.command("vehicle-karte-analysis-tick")
def vehicle_karte_analysis_tick():
    """公開資料と登録内容の変更を確認し、予約済み分析を実行する。"""
    try:
        public_result = public_knowledge_tick()
        if public_result:
            print(public_result, flush=True)
    except Exception:
        db.session.rollback()
        app.logger.exception("公開整備資料の更新確認に失敗しました。")
    finally:
        db.session.remove()

    targets = (
        db.session.query(Vehicle.id, Vehicle.company_code)
        .join(
            Company,
            Company.company_code == Vehicle.company_code,
        )
        .filter(
            Vehicle.deleted.is_(False),
            Company.active.is_(True),
        )
        .order_by(Vehicle.id)
        .all()
    )

    scanned = 0
    scan_errors = 0

    for vehicle_id, company_code in targets:
        try:
            vehicle = Vehicle.query.filter_by(
                id=vehicle_id,
                company_code=company_code,
                deleted=False,
            ).first()

            if vehicle is None:
                continue

            with app.test_request_context("/"):
                payload, _ = get_vehicle_karte_analysis_job_data(vehicle)

            queue_vehicle_karte_analysis(vehicle, payload)
            db.session.commit()
            scanned += 1

        except Exception:
            db.session.rollback()
            scan_errors += 1
            app.logger.exception(
                "車両分析の変更確認に失敗しました: vehicle_id=%s",
                vehicle_id,
            )

        finally:
            db.session.remove()

    now = datetime.now(ZoneInfo("UTC"))
    due_ids = (
        db.session.query(VehicleKarteAnalysis.id)
        .join(
            Vehicle,
            db.and_(
                Vehicle.id == VehicleKarteAnalysis.vehicle_record_id,
                Vehicle.company_code == VehicleKarteAnalysis.company_code,
            ),
        )
        .join(
            Company,
            Company.company_code == Vehicle.company_code,
        )
        .filter(
            Vehicle.deleted.is_(False),
            Company.active.is_(True),
            VehicleKarteAnalysis.status.in_(
                {"pending", "error", "running"}
            ),
            VehicleKarteAnalysis.next_analysis_at <= now,
            db.or_(
                VehicleKarteAnalysis.lease_expires_at.is_(None),
                VehicleKarteAnalysis.lease_expires_at <= now,
            ),
        )
        .order_by(
            VehicleKarteAnalysis.next_analysis_at,
            VehicleKarteAnalysis.id,
        )
        .limit(20)
        .all()
    )
    db.session.remove()

    completed = 0
    failed = 0

    for (state_id,) in due_ids:
        try:
            if run_vehicle_karte_analysis_job(state_id):
                completed += 1
            else:
                failed += 1

        except Exception:
            db.session.rollback()
            failed += 1
            app.logger.exception(
                "車両分析ジョブの実行に失敗しました: state_id=%s",
                state_id,
            )

        finally:
            db.session.remove()

    print(
        f"変更確認: {scanned}台 / 確認エラー: {scan_errors}台 / "
        f"分析完了: {completed}台 / 未完了: {failed}台"
    )


def queue_vehicle_karte_analysis(vehicle, payload):
    """バックグラウンド処理用。コミットは呼出元が行う。"""
    utc = ZoneInfo("UTC")
    now = datetime.now(utc)

    def aware(value):
        if value is None:
            return None
        if value.tzinfo is None:
            return value.replace(tzinfo=utc)
        return value.astimezone(utc)

    state = VehicleKarteAnalysis.query.filter_by(
        company_code=vehicle.company_code,
        vehicle_record_id=vehicle.id,
    ).first()

    if state is None:
        try:
            with db.session.begin_nested():
                state = VehicleKarteAnalysis(
                    company_code=vehicle.company_code,
                    vehicle_record_id=vehicle.id,
                )
                db.session.add(state)
                db.session.flush()
        except IntegrityError:
            state = VehicleKarteAnalysis.query.filter_by(
                company_code=vehicle.company_code,
                vehicle_record_id=vehicle.id,
            ).one()

    fingerprints = payload["_fingerprints"]
    signature = hashlib.sha256(
        json.dumps(
            fingerprints,
            sort_keys=True,
            ensure_ascii=False,
        ).encode("utf-8")
    ).hexdigest()

    old_result = safe_json_dict(state.result_json)
    previous = old_result.get("fingerprints") or {}
    if not isinstance(previous, dict):
        previous = {}

    active = (
        state.status == "running"
        and aware(state.lease_expires_at) is not None
        and aware(state.lease_expires_at) > now
    )

    if state.input_hash == signature and (
        state.status in {"pending", "error"} or active
    ):
        return state

    important_changed = (
        previous.get("policy_version")
        != fingerprints["policy_version"]
        or previous.get("important_hash")
        != fingerprints["important_hash"]
    )
    routine_changed = (
        previous.get("routine_hash")
        != fingerprints["routine_hash"]
    )
    state.input_hash = signature

    if previous and not important_changed and not routine_changed:
        if not active:
            state.status = "completed"
            state.next_analysis_at = None
            state.last_error = None
            state.lease_token = None
            state.lease_expires_at = None
        return state

    if important_changed:
        due = now + timedelta(minutes=2)
        reason = (
            "初回分析" if not previous
            else "整備・不具合・点検指摘などの変更"
        )
    elif routine_changed:
        local = now.astimezone(ZoneInfo("Asia/Tokyo"))
        due = local.replace(
            hour=3,
            minute=0,
            second=0,
            microsecond=0,
        )
        if due <= local:
            due += timedelta(days=1)
        due = due.astimezone(utc)
        reason = "走行距離・期限などの日次確認"
    else:
        due = now + timedelta(minutes=2)
        reason = "中断した分析の再実行"

    existing_due = aware(state.next_analysis_at)
    if state.status in {"pending", "running"} and existing_due:
        due = min(existing_due, due)

    state.next_analysis_at = due
    state.request_reason = reason

    if not active:
        state.status = "pending"
        state.lease_token = None
        state.lease_expires_at = None

    return state


def get_vehicle_karte_analysis_fingerprints(
    vehicle, summary, records,
):
    def digest(value):
        text = json.dumps(
            value,
            ensure_ascii=False,
            sort_keys=True,
            default=str,
        )
        return hashlib.sha256(
            text.encode("utf-8")
        ).hexdigest()

    important = []
    inspection_patterns = {}
    normal_patterns = {}
    deadlines = {}

    for record in records:
        if record["source_id"].startswith("inspection:"):
            pattern = {
                key: value
                for key, value in record.items()
                if key not in {"source_id", "date"}
            }
            signature = digest(pattern)

            if record.get("has_attention"):
                inspection_patterns[signature] = pattern
            else:
                normal_patterns[signature] = pattern
            continue

        important.append(record)

        if record["source_id"].startswith("periodic:"):
            category = record.get("category") or "other"
            if category not in deadlines:
                deadlines[category] = record.get(
                    "next_inspection_date"
                )

    important.extend(inspection_patterns.values())
    important.sort(key=digest)

    vehicle_context = {
        "model_code": vehicle.model_code,
            "engine_code": getattr(vehicle, "engine_code", None),
        "manufacturer": vehicle.manufacturer,
        "first_registration_date": (
            vehicle.first_registration_date
        ),
    }

    deadlines["vehicle_inspection"] = (
        vehicle.inspection_expiry
    )
    today = datetime.now(
        ZoneInfo("Asia/Tokyo")
    ).date()
    deadline_states = {}

    for key, value in deadlines.items():
        text = (
            str(value or "").strip()[:10]
            .replace("/", "-")
        )
        try:
            day = datetime.strptime(
                text, "%Y-%m-%d"
            ).date()
        except ValueError:
            continue

        deadline_states[key] = {
            "date": day.isoformat(),
            "status": (
                "期限経過" if day < today
                else "期限当日" if day == today
                else "期限前"
            ),
        }

    return {
        # PREVENTIVE_BASELINE_GUIDANCE_V1
        "policy_version": 12,
        "important_hash": digest({
            "factual_history_policy": "explicit-synthetic-document-v1",
            "source_exclusions": summary.get("source_exclusions", []),
            "vehicle": vehicle_context,
            "records": important,
        }),
        "routine_hash": digest({
            "evaluation_date": today.isoformat(),
            "distance": summary["distance"],
            "current_mileage": summary["current_mileage"],
            "current_mileage_date": summary.get(
                "current_mileage_date"
            ),
            "mileage_reference": summary.get(
                "mileage_reference"
            ),
            "total_cost": summary["total_cost"],
            "failure_count": summary["failure_count"],
            "part_replacement_count": (
                summary["part_replacement_count"]
            ),
            "deadlines": deadline_states,
            "normal_checks": sorted(normal_patterns),
            "inspection_attention_count": sum(
                record["source_id"].startswith("inspection:")
                and bool(record.get("has_attention"))
                for record in records
            ),
        }),
        "has_important_history": bool(important),
    }


def build_vehicle_karte_service_progress(maintenance, summary):
    def day(value):
        try:
            return datetime.strptime(
                str(value or "")[:10], "%Y-%m-%d"
            ).date()
        except ValueError:
            return None

    def meter(value):
        try:
            number = Decimal(str(value))
            return number if number.is_finite() and number >= 0 else None
        except (InvalidOperation, ValueError, TypeError):
            return None

    as_of = day(summary.get("end_date"))
    if as_of:
        as_of = min(
            as_of,
            datetime.now(ZoneInfo("Asia/Tokyo")).date(),
        )

    measured = day(summary.get("current_mileage_date"))
    current = meter(summary.get("current_mileage"))
    result = {
        "as_of": as_of,
        "last_date": None,
        "last_mileage": None,
        "measured_date": measured,
        "current_mileage": current,
        "distance_since": None,
        "days_since": None,
        "note": "比較できる整備記録がありません。",
    }

    maintenance, _, _ = filter_vehicle_maintenance_factual_history(maintenance)
    candidates = []
    unknown_date = False
    for record in maintenance:
        completed = str(record.completion_date or "").strip()
        if record.status != "完了" and not completed:
            continue

        recorded = day(completed or record.entry_date)
        if recorded is None:
            unknown_date = True
        elif as_of and recorded <= as_of:
            candidates.append((recorded, record.id or 0, record))

    if not candidates:
        return result

    last_date, _, record = max(
        candidates, key=lambda item: item[:2]
    )
    last = meter(record.mileage)
    result.update(
        last_date=last_date,
        last_mileage=last,
        days_since=(as_of - last_date).days,
        note="",
    )

    same_day = {
        meter(item.mileage)
        for date, _, item in candidates
        if date == last_date and meter(item.mileage) is not None
    }

    if unknown_date:
        result["note"] = (
            "日付不明の完了記録があり、"
            "直近の整備か確認が必要です。"
        )
    elif len(same_day) > 1:
        result["note"] = "同日の整備記録で走行距離が異なります。"
    elif current is None or last is None:
        result["note"] = "走行距離の記録が不足しています。"
    elif measured is None or measured < last_date or measured > as_of:
        result["note"] = "整備後のメーター記録を確認できません。"
    elif current < last:
        result["note"] = (
            "メーター値が整備時より小さいため確認が必要です。"
        )
    else:
        result["distance_since"] = current - last

    if not str(record.completion_date or "").strip() and not result["note"]:
        result["note"] = (
            "整備日は、完了日未入力のため入庫日を使用しています。"
        )

    return result


# PREVENTIVE_ASSEMBLY_EVIDENCE_V1
def build_vehicle_part_document_evidence(part, parent, source):
    """Trace a registered part to its unchanged, reviewed invoice line."""
    import unicodedata

    def norm(value):
        return re.sub(r"[\s・･]+", "", unicodedata.normalize("NFKC", str(value or ""))).casefold()

    result = {
        "status": "untraced",
        "part_source_id": f"part:{part.id}",
        "maintenance_source_id": f"maintenance:{parent.id}",
    }
    if (
        part.company_code != parent.company_code
        or part.vehicle_record_id != parent.vehicle_record_id
        or part.maintenance_record_id != parent.id
    ):
        return {**result, "reason": "parent_scope_mismatch"}
    if source is None:
        return {**result, "reason": "source_line_link_not_available"}
    if (
        source.company_code != parent.company_code
        or source.maintenance_record_id != parent.id
        or source.replacement_id != part.id
    ):
        return {**result, "reason": "source_line_scope_mismatch"}
    try:
        lines = json.loads(parent.line_items_json or "[]")
    except (ValueError, TypeError):
        return {**result, "reason": "source_lines_invalid"}
    if not isinstance(lines, list) or not all(isinstance(line, dict) for line in lines):
        return {**result, "reason": "source_lines_invalid"}
    index = source.source_line_index
    if type(index) is not int or not 0 <= index < len(lines):
        return {**result, "reason": "source_line_index_invalid"}
    line = lines[index]
    version = hashlib.sha256(json.dumps(
        line, sort_keys=True, ensure_ascii=False, default=str,
    ).encode("utf-8")).hexdigest()
    if source.source_line_version != version:
        return {**result, "reason": "source_line_changed"}
    if (
        line.get("replacement_action") != "replace"
        or norm(line.get("replacement_part_name")) != norm(part.part_name)
        or str(line.get("part_number") or "").strip() != str(part.part_number or "").strip()
    ):
        return {**result, "reason": "replacement_line_not_matched"}
    try:
        quantity = Decimal(str(line.get("quantity")))
        saved_quantity = Decimal(str(part.quantity))
        if not quantity.is_finite() or quantity <= 0 or quantity != saved_quantity:
            raise ValueError()
    except (ValueError, TypeError, InvalidOperation):
        return {**result, "reason": "replacement_quantity_not_matched"}
    invoice_source = safe_json_dict(parent.invoice_details_json).get("source")
    if not isinstance(invoice_source, dict):
        return {**result, "reason": "invoice_source_not_available"}
    sha256 = invoice_source.get("sha256")
    pages = invoice_source.get("pages")
    page = line.get("source_page")
    if (
        not isinstance(sha256, str) or re.fullmatch(r"[0-9a-fA-F]{64}", sha256) is None
        or not isinstance(pages, list) or not pages
        or any(type(value) is not int or value < 1 for value in pages)
        or type(page) is not int or page not in pages
        or not isinstance(invoice_source.get("draft_id"), str) or not invoice_source["draft_id"]
        or type(invoice_source.get("record_index")) is not int or invoice_source["record_index"] < 0
    ):
        return {**result, "reason": "invoice_source_metadata_invalid"}
    return {
        **result,
        "status": "verified_saved_source_line",
        "verification_scope": "Saved reviewed line, linked part and stored original reference; original bytes are not reread here.",
        "source_line_index": index,
        "source_line_version": version,
        "source_page": page,
        "document_source": {key: invoice_source.get(key) for key in (
            "draft_id", "record_index", "sha256", "pages", "filename",
        )},
        "reviewed_line": line,
        "component_inclusion_confirmed": False,
    }


def get_related_air_dryer_assembly_history(part_name, preventive_facts):
    """A named whole-assembly record is related history, never a component baseline."""
    import unicodedata

    def norm(value):
        return re.sub(r"[\s・･]+", "", unicodedata.normalize("NFKC", str(value or ""))).casefold().replace("フィルター", "フィルタ")

    target = norm(part_name)
    allowed_targets = {
        norm(root + suffix)
        for root in ("エアドライヤ", "エアドライヤー")
        for suffix in ("", "の乾燥剤", "のフィルタ", "のゴム部品")
    }
    if target not in allowed_targets or not isinstance(preventive_facts, dict):
        return []
    result = []
    for fact in preventive_facts.get("part_replacements", []):
        if not isinstance(fact, dict) or norm(fact.get("part_name")) not in {
            norm("エアドライヤASSY"), norm("エアドライヤーASSY"),
        }:
            continue
        source_ids = fact.get("source_ids")
        if not isinstance(source_ids, list) or not source_ids or any(
            not isinstance(value, str) or re.fullmatch(r"part:[0-9]+", value) is None for value in source_ids
        ):
            continue
        result.append({
            "assembly_part_name": fact["part_name"],
            "replacement_date": fact.get("latest_dated_replacement"),
            "replacement_mileage": fact.get("replacement_mileage"),
            "replacement_date_usable": fact.get("replacement_date_usable") is True,
            "source_ids": source_ids,
            "document_evidence": fact.get("latest_replacement_document_evidence", []),
            "relationship": "registered_whole_assembly_related_to_named_component",
            "component_inclusion_confirmed": False,
            "usable_as_component_baseline": False,
            "usable_as_inspection_baseline": False,
            "interpretation": (
                "本体ASSYの交換登録あり。構成部品の交換範囲・新品か再生品かは未確定。"
                "構成部品の交換日・点検日を本体交換日へ置き換えない。"
                "関連履歴がないとは案内しない。交換未実施・期限超過とも断定しない。"
            ),
        })
    return result




# PREVENTIVE_INSPECTION_FACTS_V1
def periodic_inspection_synthetic_evidence(row):
    from types import SimpleNamespace
    details = safe_json_dict(row.details_json)
    evidence = vehicle_maintenance_synthetic_evidence(SimpleNamespace(
        id=row.id, company_code=row.company_code, vehicle_record_id=row.vehicle_record_id,
        notes=details.get("notes"), invoice_details_json="{}",
    ))
    if evidence:
        evidence["source_id"] = f"periodic:{row.id}"
        evidence["evidence_field"] = "details_json.notes"
    return evidence


def assess_saved_inspection_item(item, legend):
    """Use this document's legend; never use a universal circle/cross convention."""
    import unicodedata
    def text(value):
        return unicodedata.normalize("NFKC", str(value or "")).strip()
    raw = text(item.get("raw_result"))
    if not raw:
        return {"status": "blank", "inspection_performed_confirmed": False}
    pairs = {}
    for entry in re.split(r"[、,;；\n\r]+", text(legend)):
        parts = re.split(r"[:：]", entry)
        if len(parts) != 2:
            continue
        left, right = (part.strip() for part in parts)
        for symbol, meaning in ((left, right), (right, left)):
            if len(symbol) == 1 and meaning:
                pairs.setdefault(symbol, set()).add(meaning)
    meanings = pairs.get(raw, set())
    if len(meanings) != 1:
        return {"status": "symbol_unresolved", "inspection_performed_confirmed": False}
    meaning = next(iter(meanings))
    labels = {
        "点検良好": "inspection_recorded", "点検済": "inspection_recorded",
        "点検済み": "inspection_recorded", "点検": "inspection_recorded",
        "異常なし": "inspection_recorded", "良好": "inspection_recorded",
        "該当なし": "not_applicable", "省略": "omitted",
        "交換": "recorded_work", "修理": "recorded_work", "調整": "recorded_work",
        "締付": "recorded_work", "清掃": "recorded_work", "給油(水)": "recorded_work",
        "特定整備": "recorded_work", "不良": "recorded_attention", "異常あり": "recorded_attention",
    }
    status = labels.get(meaning, "meaning_unresolved")
    # Combined cells and placement notes do not establish each sub-item's result.
    if status == "inspection_recorded" and (
        "/" in text(item.get("item_name"))
        or any(word in text(item.get("notes")) for word in ("空欄", "左欄", "右欄", "判読", "不明", "不確実"))
    ):
        status = "item_scope_unresolved"
    if status == "inspection_recorded" and any(
        word in text(item.get("result_text")) + text(item.get("notes"))
        for word in ("未実施", "未点検", "不良", "異常あり", "要修理", "判読不能")
    ):
        status = "conflicting_result_text"
    return {"status": status, "legend_meaning": meaning,
            "inspection_performed_confirmed": status == "inspection_recorded"}


def build_periodic_inspection_ai_details(row, draft):
    """Read confirmed item values plus original reference without changing the import."""
    from io import BytesIO
    from pypdf import PdfReader
    details = safe_json_dict(row.details_json)
    items = details.get("inspection_items")
    valid_items = isinstance(items, list) and len(items) <= 1000 and all(isinstance(item, dict) for item in items)
    legend = details.get("symbol_legend")
    legend = legend if isinstance(legend, str) else ""
    warnings = details.get("warnings")
    warnings = warnings if isinstance(warnings, list) else []
    evidence = {"status": "untraced", "source_id": f"periodic:{row.id}",
                "reason": "original_reference_not_available"}
    pages = details.get("source_pages")
    if (
        draft is not None and draft.id == row.source_draft_id
        and draft.company_code == row.company_code and draft.document_type == "inspection"
        and type(row.source_record_index) is int and row.source_record_index >= 0
    ):
        original = draft.source_file
        checksum = draft.source_sha256
        preview = safe_json_dict(draft.preview_json)
        original_records = preview.get("records")
        if not isinstance(original_records, list):
            original_records = preview.get("original_records")
        if (
            isinstance(original, bytes) and isinstance(checksum, str)
            and re.fullmatch(r"[0-9a-f]{64}", checksum)
            and hashlib.sha256(original).hexdigest() == checksum
            and isinstance(original_records, list) and row.source_record_index < len(original_records)
            and isinstance(pages, list) and pages
            and all(type(page) is int and page > 0 for page in pages)
        ):
            try:
                pdf = PdfReader(BytesIO(original), strict=False)
                count = len(pdf.pages)
                if pdf.is_encrypted or not 1 <= count <= 200 or max(pages) > count:
                    raise ValueError("invalid pages")
                evidence = {
                    "status": "verified_saved_original",
                    "source_id": f"periodic:{row.id}", "draft_id": draft.id,
                    "record_index": row.source_record_index, "sha256": checksum,
                    "filename": draft.source_filename, "source_pages": pages,
                    "original_page_count": count,
                    "verification_scope": "Saved original bytes/checksum, company, source record and physical pages; confirmed item values retained.",
                }
            except Exception:
                evidence["reason"] = "original_pdf_not_verified"
        else:
            evidence["reason"] = "original_checksum_or_record_scope_not_verified"
    date_values = [details.get(key) for key in ("inspection_date", "record_date") if details.get(key)]
    date_consistent = bool(date_values) and all(value == row.inspection_date for value in date_values)
    try:
        meter = Decimal(str(row.mileage))
        saved_meter = Decimal(str(details.get("mileage")))
        meter_consistent = meter.is_finite() and meter >= 0 and meter == saved_meter
    except (TypeError, ValueError, InvalidOperation):
        meter_consistent = False
    source_items = []
    for index, item in enumerate(items if valid_items else []):
        page = item.get("source_page")
        assessment = assess_saved_inspection_item(item, legend)
        if type(page) is not int or not isinstance(pages, list) or page not in pages:
            assessment = {"status": "source_page_unresolved", "inspection_performed_confirmed": False}
        source_items.append({**item, "item_index": index, "execution_evidence": assessment})
    return {
        "inspection_items": source_items,
        "symbol_legend": legend,
        "inspection_warnings": warnings,
        "inspection_document_evidence": evidence,
        "inspection_date_consistent": date_consistent,
        "inspection_mileage_consistent": meter_consistent,
        "next_inspection_month": details.get("next_inspection_month"),
        "inspection_execution_note": "記号は当該原本の凡例で解釈。空欄は未記入。交換・修理記号から別途の点検完了や指摘解消を作らない。",
    }


def build_recorded_inspection_facts(summary, records):
    def day(value):
        try:
            return datetime.strptime(value, "%Y-%m-%d").date() if isinstance(value, str) and len(value) == 10 else None
        except ValueError:
            return None
    def number(value):
        try:
            result = Decimal(str(value))
            return result if not isinstance(value, bool) and result.is_finite() and result >= 0 else None
        except (ValueError, TypeError, InvalidOperation):
            return None
    as_of = day(summary.get("end_date"))
    measured = day(summary.get("current_mileage_date"))
    current = number(summary.get("current_mileage"))
    facts = []
    for record in records:
        if not str(record.get("source_id") or "").startswith("periodic:"):
            continue
        document = record.get("inspection_document_evidence") or {}
        if document.get("status") != "verified_saved_original":
            continue
        performed = day(record.get("date"))
        meter = number(record.get("mileage"))
        for item in record.get("inspection_items", []):
            assessment = item.get("execution_evidence") or {}
            if assessment.get("inspection_performed_confirmed") is not True:
                continue
            distance = None
            if (
                record.get("inspection_mileage_consistent") is True and meter is not None
                and current is not None and measured and performed and as_of
                and performed <= measured <= as_of and current >= meter
                and (summary.get("mileage_reference") or {}).get("distance_usable") is True
            ):
                distance = current - meter
            facts.append({
                "item_name": item.get("item_name"), "category": item.get("category"),
                "inspection_item_index": item.get("item_index"),
                "inspection_date": record.get("date"),
                "inspection_date_usable": bool(record.get("inspection_date_consistent") is True and performed and as_of and performed <= as_of),
                "inspection_mileage": meter,
                "inspection_mileage_usable": distance is not None,
                "distance_since_km": distance,
                "source_ids": [record["source_id"]], "source_page": item.get("source_page"),
                "raw_result": item.get("raw_result"), "legend_meaning": assessment.get("legend_meaning"),
                "document_evidence": document,
                "scope_note": "原本・当該項目から確認できる点検登録。交換・指摘解消・車両全体の安全性とは別。未登録実施の有無は不明。",
            })
    return facts


def inspection_procedure_matches(rule, part_name, fact):
    """Match the inspection procedure, not merely a shared device name."""
    import unicodedata
    def norm(value):
        value = unicodedata.normalize("NFKC", str(value or ""))
        return re.sub(r"[\s・･☆★◎]+", "", value).casefold().replace("エアドライヤー", "エアドライヤ")
    target = norm(part_name)
    item = norm(fact.get("item_name"))
    quote = norm(rule.get("source_quote"))
    if not target or not item or not quote or "/" in item:
        return False
    if target == "エアドライヤ":
        return all(word in quote and word in item for word in ("エアドライヤ", "水", "量", "状態")) and any(
            word in item and word in quote for word in ("排出", "排水")
        )
    return target in item and len(item) >= len(target) + 4 and item in quote




def calculate_adopted_inspection_rule_timing(
    rule, part_name, preventive_facts, summary,
):
    """採用済み点検基準を、原本と項目の実施を確認できた点検実績へ照合する。"""
    import calendar
    import unicodedata
    from datetime import timedelta
    from decimal import Decimal, InvalidOperation

    criteria_results = []
    source_ids = []
    related_assembly_history = []

    def result(status, reason):
        if status == "held":
            criteria_results.clear()
        return {
            "status": status,
            "reason": reason,
            "scope": "registered_inspection_and_reading_dates",
            "calculation_permitted": any(
                item.get("calculation_permitted") is True
                for item in criteria_results
            ),
            "criteria": criteria_results,
            "related_assembly_replacements": related_assembly_history,
            "source_ids": list(dict.fromkeys(source_ids)),
        }

    def day(value):
        if not isinstance(value, str) or len(value) != 10:
            return None
        try:
            parsed = datetime.strptime(value, "%Y-%m-%d").date()
            return parsed if parsed.isoformat() == value else None
        except ValueError:
            return None

    def number(value):
        if type(value) not in {int, float, Decimal}:
            return None
        try:
            parsed = Decimal(str(value))
            return parsed if parsed.is_finite() and parsed >= 0 else None
        except (InvalidOperation, ValueError):
            return None

    def normalize_name(value):
        text = unicodedata.normalize(
            "NFKC", str(value or ""),
        ).casefold()
        return re.sub(r"[\s・･]+", "", text).replace(
            "フィルター", "フィルタ",
        )

    if (
        not isinstance(rule, dict)
        or not isinstance(preventive_facts, dict)
        or not isinstance(summary, dict)
    ):
        return result("held", "invalid_input")

    adoption = rule.get("analysis_adoption") or {}
    if adoption.get("status") != "adopted_for_analysis":
        return result("held", "rule_not_adopted")
    if rule.get("action") != "inspect":
        return result("held", "rule_not_inspection")
    if rule.get("cycle") not in {"repeat", "all"}:
        return result("held", "initial_baseline_not_available")

    criteria = rule.get("criteria")
    relation = rule.get("relation")
    if (
        not isinstance(criteria, list)
        or not 1 <= len(criteria) <= 4
        or (
            relation != "single" if len(criteria) == 1
            else relation not in {"any", "all"}
        )
    ):
        return result("held", "invalid_criteria_relation")

    as_of = day(summary.get("end_date"))
    if (
        as_of is None
        or as_of > datetime.now(ZoneInfo("Asia/Tokyo")).date()
        or preventive_facts.get("as_of") != as_of.isoformat()
    ):
        return result("held", "invalid_reference_date")

    name = normalize_name(part_name)
    facts = preventive_facts.get("inspection_items")
    if not name or not isinstance(facts, list):
        return result("held", "inspection_baseline_not_available")
    matches = [
        fact for fact in facts
        if isinstance(fact, dict)
        and inspection_procedure_matches(rule, part_name, fact)
    ]
    if not matches:
        return result("held", "inspection_procedure_not_matched" if facts else "inspection_baseline_not_available")
    if any(fact.get("inspection_date_usable") is not True or day(fact.get("inspection_date")) is None for fact in matches):
        return result("held", "inspection_date_not_confirmed")
    latest = max(day(fact["inspection_date"]) for fact in matches)
    matches = [fact for fact in matches if day(fact["inspection_date"]) == latest]
    if len(matches) != 1:
        return result("held", "inspection_baseline_not_uniquely_matched")

    fact = matches[0]
    inspected_on = day(fact.get("inspection_date"))
    if (
        fact.get("inspection_date_usable") is not True
        or inspected_on is None
        or inspected_on > as_of
    ):
        return result("held", "inspection_date_not_confirmed")

    ids = fact.get("source_ids")
    if (
        not isinstance(ids, list)
        or not ids
        or any(
            not isinstance(value, str) or not value.startswith("periodic:")
            for value in ids
        )
    ):
        return result("held", "inspection_evidence_missing")
    source_ids.extend(ids)
    for name in ("knowledge_source_id", "vehicle_source_id"):
        value = adoption.get(name)
        if not isinstance(value, str) or not value:
            return result("held", "adoption_evidence_missing")
        source_ids.append(value)

    seen = set()
    for criterion in criteria:
        if not isinstance(criterion, dict):
            return result("held", "invalid_criterion")
        metric = criterion.get("metric")
        threshold = number(criterion.get("value"))
        if (
            not isinstance(metric, str)
            or metric not in {
                "distance_km", "period_days",
                "period_months", "engine_hours",
            }
            or metric in seen
            or threshold is None
            or threshold <= 0
        ):
            return result("held", "invalid_criterion")
        seen.add(metric)
        entry = {
            "metric": metric,
            "threshold": criterion["value"],
            "baseline_kind": "inspection",
            "inspection_item_index": fact.get("inspection_item_index"),
            "baseline_date": inspected_on.isoformat(),
            "status": "unknown",
            "calculation_permitted": False,
        }

        if metric == "distance_km":
            measured_on = day(summary.get("current_mileage_date"))
            reference = summary.get("mileage_reference") or {}
            current = number(summary.get("current_mileage"))
            inspection_meter = number(fact.get("inspection_mileage"))
            recorded_distance = number(fact.get("distance_since_km"))
            if (
                fact.get("inspection_mileage_usable") is True
                and reference.get("distance_usable") is True
                and current is not None
                and inspection_meter is not None
                and current >= inspection_meter
                and measured_on is not None
                and inspected_on <= measured_on <= as_of
                and recorded_distance == current - inspection_meter
            ):
                elapsed = current - inspection_meter
                entry.update({
                    "status": (
                        "reached" if elapsed >= threshold
                        else "not_reached_at_reference"
                    ),
                    "calculation_permitted": True,
                    "reference_date": measured_on.isoformat(),
                    "inspection_mileage": inspection_meter,
                    "recorded_mileage": current,
                    "elapsed_km": elapsed,
                    "remaining_km": max(Decimal(0), threshold - elapsed),
                    "excess_km": max(Decimal(0), elapsed - threshold),
                })
            else:
                entry["reason"] = "comparable_mileage_not_available"

        elif metric in {"period_days", "period_months"}:
            if threshold != threshold.to_integral_value():
                entry["reason"] = "fractional_calendar_period"
            else:
                try:
                    amount = int(threshold)
                    if metric == "period_days":
                        due = inspected_on + timedelta(days=amount)
                    else:
                        total = inspected_on.month - 1 + amount
                        year = inspected_on.year + total // 12
                        month = total % 12 + 1
                        if not 1 <= year <= 9999:
                            raise ValueError("DATE_OUT_OF_RANGE")
                        due = inspected_on.replace(
                            year=year,
                            month=month,
                            day=min(
                                inspected_on.day,
                                calendar.monthrange(year, month)[1],
                            ),
                        )
                    entry.update({
                        "status": (
                            "reached" if as_of >= due
                            else "not_reached_at_reference"
                        ),
                        "calculation_permitted": True,
                        "reference_date": as_of.isoformat(),
                        "due_date": due.isoformat(),
                        "elapsed_days": (as_of - inspected_on).days,
                        "remaining_days": max(0, (due - as_of).days),
                        "overdue_days": max(0, (as_of - due).days),
                    })
                except (ValueError, OverflowError):
                    entry["reason"] = "calendar_date_out_of_range"
        else:
            entry["reason"] = "engine_hours_not_available"

        criteria_results.append(entry)

    statuses = [item["status"] for item in criteria_results]
    if relation in {"single", "any"} and "reached" in statuses:
        return result("threshold_reached", "recorded_threshold_reached")
    if relation == "all" and all(value == "reached" for value in statuses):
        return result("threshold_reached", "all_recorded_thresholds_reached")
    if "unknown" in statuses:
        return result("unknown", "some_criteria_not_calculable")
    return result(
        "not_reached_at_reference_dates",
        "threshold_not_reached_at_recorded_reference_dates",
    )




def calculate_adopted_maintenance_rule_timing(
    rule, part_name, preventive_facts, summary,
):
    """採用済み交換基準を実績と照合する。故障予測・整備要否は判定しない。"""
    import calendar
    import unicodedata
    from datetime import timedelta
    from decimal import Decimal, InvalidOperation

    criteria_results = []
    source_ids = []
    related_assembly_history = []

    def result(status, reason):
        if status == "held":
            criteria_results.clear()
        return {
            "status": status,
            "reason": reason,
            "scope": "registered_replacement_and_reading_dates",
            "calculation_permitted": any(
                item.get("calculation_permitted") is True
                for item in criteria_results
            ),
            "criteria": criteria_results,
            "related_assembly_replacements": related_assembly_history,
            "source_ids": list(dict.fromkeys(source_ids)),
        }

    def day(value):
        if not isinstance(value, str) or len(value) != 10:
            return None
        try:
            parsed = datetime.strptime(value, "%Y-%m-%d").date()
            return parsed if parsed.isoformat() == value else None
        except ValueError:
            return None

    def number(value):
        if type(value) not in {int, float, Decimal}:
            return None
        try:
            parsed = Decimal(str(value))
            return parsed if parsed.is_finite() and parsed >= 0 else None
        except (InvalidOperation, ValueError):
            return None

    def normalize_name(value):
        text = unicodedata.normalize(
            "NFKC", str(value or ""),
        ).casefold()
        return re.sub(r"[\s・･]+", "", text).replace(
            "フィルター", "フィルタ",
        )

    if (
        not isinstance(rule, dict)
        or not isinstance(preventive_facts, dict)
        or not isinstance(summary, dict)
    ):
        return result("held", "invalid_input")

    adoption = rule.get("analysis_adoption") or {}
    if adoption.get("status") != "adopted_for_analysis":
        return result("held", "rule_not_adopted")
    def related_history():
        values = get_related_air_dryer_assembly_history(part_name, preventive_facts)
        for value in values:
            source_ids.extend(value["source_ids"])
        if values:
            for key in ("knowledge_source_id", "vehicle_source_id"):
                value = adoption.get(key)
                if isinstance(value, str) and value:
                    source_ids.append(value)
        return values

    if rule.get("action") == "inspect":
        timing = calculate_adopted_inspection_rule_timing(rule, part_name, preventive_facts, summary)
        if timing.get("status") == "held":
            timing["related_assembly_replacements"] = related_history()
            timing["source_ids"] = list(dict.fromkeys(timing.get("source_ids", []) + source_ids))
        return timing
    if rule.get("action") != "replace":
        return result("held", "unsupported_action")
    if rule.get("cycle") not in {"repeat", "all"}:
        return result("held", "initial_baseline_not_available")

    criteria = rule.get("criteria")
    relation = rule.get("relation")
    if (
        not isinstance(criteria, list)
        or not 1 <= len(criteria) <= 4
        or (
            relation != "single" if len(criteria) == 1
            else relation not in {"any", "all"}
        )
    ):
        return result("held", "invalid_criteria_relation")

    as_of = day(summary.get("end_date"))
    if (
        as_of is None
        or as_of > datetime.now(ZoneInfo("Asia/Tokyo")).date()
        or preventive_facts.get("as_of") != as_of.isoformat()
    ):
        return result("held", "invalid_reference_date")

    name = normalize_name(part_name)
    facts = preventive_facts.get("part_replacements")
    if not name or not isinstance(facts, list):
        return result("held", "part_history_not_matched")
    matches = [
        fact for fact in facts
        if isinstance(fact, dict)
        and normalize_name(fact.get("part_name")) == name
    ]
    if not matches:
        related_assembly_history = related_history()
        return result("held", "related_assembly_component_scope_unconfirmed" if related_assembly_history else "part_history_not_matched")
    if len(matches) != 1:
        return result("held", "part_history_not_uniquely_matched")

    fact = matches[0]
    replaced_on = day(fact.get("latest_dated_replacement"))
    if (
        fact.get("replacement_date_usable") is not True
        or replaced_on is None
        or replaced_on > as_of
    ):
        return result("held", "replacement_date_not_confirmed")

    ids = fact.get("source_ids")
    if (
        not isinstance(ids, list)
        or not ids
        or any(
            not isinstance(value, str) or not value.startswith("part:")
            for value in ids
        )
    ):
        return result("held", "replacement_evidence_missing")
    source_ids.extend(ids)
    for name in ("knowledge_source_id", "vehicle_source_id"):
        value = adoption.get(name)
        if not isinstance(value, str) or not value:
            return result("held", "adoption_evidence_missing")
        source_ids.append(value)

    seen = set()
    for criterion in criteria:
        if not isinstance(criterion, dict):
            return result("held", "invalid_criterion")
        metric = criterion.get("metric")
        threshold = number(criterion.get("value"))
        if (
            not isinstance(metric, str)
            or metric not in {
                "distance_km", "period_days",
                "period_months", "engine_hours",
            }
            or metric in seen
            or threshold is None
            or threshold <= 0
        ):
            return result("held", "invalid_criterion")
        seen.add(metric)
        entry = {
            "metric": metric,
            "threshold": criterion["value"],
            "baseline_date": replaced_on.isoformat(),
            "status": "unknown",
            "calculation_permitted": False,
        }

        if metric == "distance_km":
            measured_on = day(summary.get("current_mileage_date"))
            reference = summary.get("mileage_reference") or {}
            current = number(summary.get("current_mileage"))
            replaced_meter = number(fact.get("replacement_mileage"))
            recorded_distance = number(fact.get("distance_since_km"))
            if (
                fact.get("replacement_mileage_usable") is True
                and reference.get("distance_usable") is True
                and current is not None
                and replaced_meter is not None
                and current >= replaced_meter
                and measured_on is not None
                and replaced_on <= measured_on <= as_of
                and recorded_distance == current - replaced_meter
            ):
                elapsed = current - replaced_meter
                entry.update({
                    "status": (
                        "reached" if elapsed >= threshold
                        else "not_reached_at_reference"
                    ),
                    "calculation_permitted": True,
                    "reference_date": measured_on.isoformat(),
                    "replacement_mileage": replaced_meter,
                    "recorded_mileage": current,
                    "elapsed_km": elapsed,
                    "remaining_km": max(Decimal(0), threshold - elapsed),
                    "excess_km": max(Decimal(0), elapsed - threshold),
                })
            else:
                entry["reason"] = "comparable_mileage_not_available"

        elif metric in {"period_days", "period_months"}:
            if threshold != threshold.to_integral_value():
                entry["reason"] = "fractional_calendar_period"
            else:
                try:
                    amount = int(threshold)
                    if metric == "period_days":
                        due = replaced_on + timedelta(days=amount)
                    else:
                        total = replaced_on.month - 1 + amount
                        year = replaced_on.year + total // 12
                        month = total % 12 + 1
                        if not 1 <= year <= 9999:
                            raise ValueError("DATE_OUT_OF_RANGE")
                        due = replaced_on.replace(
                            year=year,
                            month=month,
                            day=min(
                                replaced_on.day,
                                calendar.monthrange(year, month)[1],
                            ),
                        )
                    entry.update({
                        "status": (
                            "reached" if as_of >= due
                            else "not_reached_at_reference"
                        ),
                        "calculation_permitted": True,
                        "reference_date": as_of.isoformat(),
                        "due_date": due.isoformat(),
                        "elapsed_days": (as_of - replaced_on).days,
                        "remaining_days": max(0, (due - as_of).days),
                        "overdue_days": max(0, (as_of - due).days),
                    })
                except (ValueError, OverflowError):
                    entry["reason"] = "calendar_date_out_of_range"
        else:
            entry["reason"] = "engine_hours_not_available"

        criteria_results.append(entry)

    statuses = [item["status"] for item in criteria_results]
    if relation in {"single", "any"} and "reached" in statuses:
        return result("threshold_reached", "recorded_threshold_reached")
    if relation == "all" and all(value == "reached" for value in statuses):
        return result("threshold_reached", "all_recorded_thresholds_reached")
    if "unknown" in statuses:
        return result("unknown", "some_criteria_not_calculable")
    return result(
        "not_reached_at_reference_dates",
        "threshold_not_reached_at_recorded_reference_dates",
    )


def build_vehicle_karte_preventive_facts(vehicle, summary, records):
    """交換後の期間・距離を計算する。交換期限や故障時期は推定しない。"""
    import unicodedata
    def day(value):
        try:
            return datetime.strptime(
                str(value or "")[:10], "%Y-%m-%d"
            ).date()
        except ValueError:
            return None

    def meter(value):
        try:
            number = Decimal(str(value))
            return (
                number
                if number.is_finite() and number >= 0
                else None
            )
        except (InvalidOperation, ValueError, TypeError):
            return None

    as_of = day(summary.get("end_date"))
    current = meter(summary.get("current_mileage"))
    measured_on = day(summary.get("current_mileage_date"))
    groups = {}

    for record in records:
        if not record["source_id"].startswith("part:"):
            continue

        completed_on = day(record.get("completion_date"))
        if record.get("status") != "完了" and completed_on is None:
            continue
        if completed_on and as_of and completed_on > as_of:
            continue

        name = str(record.get("content") or "").strip()
        number = str(record.get("part_number") or "").strip()
        if name:
            normalized_name = re.sub(
                r"[\s・･]+", "",
                unicodedata.normalize("NFKC", name).casefold(),
            ).replace("フィルター", "フィルタ")
            groups.setdefault((normalized_name, number), []).append(record)

    facts = []

    for (name, number), rows in sorted(groups.items()):
        dated = [
            row for row in rows
            if day(row.get("date"))
        ]
        dated = [
            row for row in dated
            if not as_of or day(row["date"]) <= as_of
        ]
        if not dated:
            continue

        latest_day = max(day(row["date"]) for row in dated)
        latest = [
            row for row in dated
            if day(row["date"]) == latest_day
        ]
        distances = {
            meter(row.get("mileage"))
            for row in latest
        }
        replaced_meter = (
            next(iter(distances))
            if len(distances) == 1
            else None
        )
        notes = []

        if len(dated) != len(rows):
            notes.append(
                "日付不明などの交換記録があり、最新の交換かは要確認。"
            )
        if len(distances) > 1:
            notes.append(
                "同日の交換時走行距離が一致していません。"
            )

        distance = None
        if current is not None and replaced_meter is not None:
            if measured_on is None or measured_on < latest_day:
                notes.append(
                    "交換後の現在走行距離を確認できません。"
                )
            elif current < replaced_meter:
                notes.append(
                    "現在走行距離が交換時より小さいため距離を計算していません。"
                )
            else:
                distance = current - replaced_meter
        else:
            notes.append("走行距離の記録が不足しています。")

        previous_days = [
            day(row["date"]) for row in dated
            if day(row["date"]) < latest_day
        ]
        previous_day = max(previous_days) if previous_days else None
        previous = [
            row for row in dated
            if previous_day and day(row["date"]) == previous_day
        ]
        previous_meters = {
            meter(row.get("mileage")) for row in previous
        }
        previous_meter = (
            next(iter(previous_meters))
            if len(previous_meters) == 1 else None
        )
        interval_km = None
        if previous_meter is not None and replaced_meter is not None:
            if replaced_meter >= previous_meter:
                interval_km = replaced_meter - previous_meter
            else:
                notes.append(
                    "交換時走行距離が前回より小さいため交換間隔の距離を計算していません。"
                )

        facts.append({
            "part_name": str(latest[0].get("content") or name).strip(),
            "recorded_names": sorted({
                str(row.get("content") or "").strip() for row in rows
            }),
            "part_number": number,
            "latest_dated_replacement": latest_day.isoformat(),
            "replacement_date_usable": bool(
                as_of and len(dated) == len(rows)
            ),
            "replacement_mileage": replaced_meter,
            "replacement_mileage_usable": bool(
                as_of
                and len(dated) == len(rows)
                and replaced_meter is not None
                and (
                    previous_meter is None
                    or replaced_meter >= previous_meter
                )
            ),
            "days_since": (
                (as_of - latest_day).days if as_of else None
            ),
            "distance_since_km": distance,
            "previous_dated_replacement": (
                previous_day.isoformat() if previous_day else None
            ),
            "last_recorded_interval_days": (
                (latest_day - previous_day).days
                if previous_day else None
            ),
            "last_recorded_interval_km": interval_km,
            "interval_scope_note": (
                "登録された前回と直近の交換記録間の実績。"
                "途中の未登録作業の有無は不明。"
                "推奨交換間隔・交換期限・不具合の再発を意味しない。"
            ),
            "source_ids": list(dict.fromkeys(
                row["source_id"] for row in latest + previous
            )),
            "latest_replacement_document_evidence": [
                row["replacement_document_evidence"] for row in latest
                if isinstance(row.get("replacement_document_evidence"), dict)
            ],
            "notes": notes,
        })

    registered = str(
        vehicle.first_registration_date or ""
    ).strip()
    matched = re.match(
        r"^(\d{4})[-/年](\d{1,2})(?:月|[-/]|$)",
        registered,
    )
    age_months = None

    if matched and as_of:
        year, month = map(int, matched.groups())
        if 1 <= year <= 9999 and 1 <= month <= 12:
            months = (
                (as_of.year - year) * 12
                + as_of.month - month
            )
            if months >= 0:
                age_months = months

    return {
        "as_of": summary.get("end_date"),
        "vehicle_age_months": age_months,
        "current_mileage_date": summary.get(
            "current_mileage_date"
        ),
        "inspection_items": build_recorded_inspection_facts(summary, records),
        "part_replacements": facts,
        "note": (
            "名称・品番が一致する登録記録を集計。"
            "交換記録がないことは未交換を意味しない。"
            "距離・期間は交換期限や故障予測ではない。"
        ),
    }


def build_vehicle_karte_analysis_payload(
    vehicle, summary, comparison, maintenance, parts, defects,
):
    maintenance, parts = list(maintenance), list(parts)
    original_source_ids = {f"maintenance:{row.id}" for row in maintenance} | {f"part:{row.id}" for row in parts}
    maintenance, parts, synthetic_exclusions = filter_vehicle_maintenance_factual_history(maintenance, parts)
    # Preserve audit evidence from the summary if a caller already filtered its rows.
    source_exclusions = {
        (item["company_code"], item["vehicle_record_id"], item["source_id"]): item
        for item in list(summary.get("source_exclusions", [])) + synthetic_exclusions
    }
    excluded_source_ids = original_source_ids - ({f"maintenance:{row.id}" for row in maintenance} | {f"part:{row.id}" for row in parts})
    excluded_source_ids.update(item["source_id"] for item in source_exclusions.values())
    allowed_maintenance_ids = {row.id for row in maintenance}
    records = []
    sources = {}
    inspection_links = VehicleMaintenanceInspectionLink.query.filter_by(
        company_code=vehicle.company_code, vehicle_record_id=vehicle.id,
    ).order_by(
        VehicleMaintenanceInspectionLink.maintenance_record_id,
        VehicleMaintenanceInspectionLink.inspection_result_id,
        VehicleMaintenanceInspectionLink.defect_no,
    ).all()
    links_by_maintenance = {}
    links_by_defect = {}
    for link in inspection_links:
        if link.maintenance_record_id not in allowed_maintenance_ids:
            continue
        links_by_maintenance.setdefault(link.maintenance_record_id, []).append({
            "source_id": f"inspection:{link.inspection_result_id}",
            "defect_no": link.defect_no,
        })
        links_by_defect.setdefault((link.inspection_result_id, link.defect_no), []).append(
            f"maintenance:{link.maintenance_record_id}"
        )

    def short(value, limit=400):
        return str(value or "").strip()[:limit]

    def add(kind, row, date_value, values, link):
        date_text = short(date_value, 10)

        if date_text:
            try:
                date_value = datetime.strptime(
                    date_text, "%Y-%m-%d"
                ).date()
            except ValueError:
                date_text = ""
            else:
                if date_value.isoformat() > summary["end_date"]:
                    return

        source_id = f"{kind}:{row.id}"
        records.append({
            "source_id": source_id,
            "date": date_text or None,
            **values,
        })
        sources[source_id] = {
            "label": (
                f"{date_text or '日付未登録'} "
                f"{values['type']}："
                f"{short(values.get('content'), 80)}"
            ),
            "url": link,
        }
        if kind in {"part", "periodic"}:
            sources[source_id]["snapshot"] = records[-1]

    for row in maintenance:
        # ATTACHED_INVOICE_AI_INPUT_V1
        invoice_details = safe_json_dict(row.invoice_details_json)
        invoice_attachment = {}
        invoice_text = {
            name: value.strip() if isinstance(value, str) else ""
            for name, value in (
                ("content", invoice_details.get("attached_invoice_content")),
                ("notes", invoice_details.get("attached_invoice_notes")),
            )
        }
        if (
            isinstance(invoice_details.get("source"), dict)
            and any(invoice_text.values())
        ):
            invoice_attachment["attached_invoice"] = {
                **invoice_text,
                "source": {
                    key: invoice_details["source"].get(key)
                    for key in ("sha256", "pages", "record_index")
                },
                "evidence_scope": (
                    "Confirmed invoice text attached to this maintenance record. "
                    "It does not independently confirm repair completion "
                    "or inspection defect resolution."
                ),
            }
        add(
            "maintenance",
            row,
            row.entry_date or row.completion_date,
            {
                **invoice_attachment,
                "inspection_links": links_by_maintenance.get(row.id, []),
                "type": "整備・修理",
                "category": short(row.category),
                "content": str(row.content or "").strip(),
                "symptom": str(row.symptom or "").strip(),
                "cause": str(row.cause or "").strip(),
                "temporary_action": str(
                    row.temporary_action or ""
                ).strip(),
                "repair_content": str(
                    row.repair_content or ""
                ).strip(),
                "notes": str(row.notes or "").strip(),
                "line_items": safe_json_dict_list(
                    row.line_items_json
                ),
                "status": short(row.status),
                "completion_date": row.completion_date,
                "mileage": row.mileage,
                "total_cost": row.total_cost,
            },
            url_for(
                "vehicle_karte_maintenance",
                vehicle_record_id=vehicle.id,
                record_id=row.id,
            ),
        )

    maintenance_map = {
        row.id: row for row in maintenance
    }

    part_source_rows = (VehiclePartReplacementSource.query.filter_by(
        company_code=vehicle.company_code,
    ).filter(VehiclePartReplacementSource.maintenance_record_id.in_(list(maintenance_map))).all()
        if maintenance_map else [])
    part_source_map = {row.replacement_id: row for row in part_source_rows}

    for row in parts:
        parent = maintenance_map.get(
            row.maintenance_record_id
        )
        if parent is None:
            continue

        add(
            "part",
            row,
            row.replacement_date,
            {
                "replacement_document_evidence": build_vehicle_part_document_evidence(row, parent, part_source_map.get(row.id)),
                "type": "部品交換",
                "content": short(row.part_name),
                "part_number": short(row.part_number),
                "mileage": row.mileage,
                "quantity": row.quantity,
                "notes": short(row.notes),
                "status": short(parent.status),
                "completion_date": parent.completion_date,
            },
            url_for(
                "vehicle_karte_maintenance",
                vehicle_record_id=vehicle.id,
                record_id=parent.id,
            ),
        )

    for row in defects:
        add(
            "defect",
            row,
            row.occurred_date,
            {
                "type": "故障・不具合",
                "category": short(row.category),
                "content": short(row.content),
                "priority": short(row.priority),
                "cause": short(row.cause),
                "repair_content": short(row.repair_content),
                "status": short(row.status),
                "repair_date": row.repair_date,
            },
            url_for(
                "vehicle_patrol_detail",
                index=row.id,
            ),
        )

    inspections = VehicleChecklistResult.query.filter_by(
        company_code=vehicle.company_code,
        vehicle_record_id=vehicle.id,
    ).filter(
        VehicleChecklistResult.status.in_({
            "承認待ち", "承認済み", "点検完了",
        })
    ).all()

    def inspection_date(row):
        text = (
            f"{row.year}-"
            f"{str(row.month).zfill(2)}-"
            f"{str(row.day).zfill(2)}"
        )
        try:
            return datetime.strptime(
                text, "%Y-%m-%d"
            ).date().isoformat()
        except ValueError:
            return ""

    inspections.sort(
        key=lambda row: (inspection_date(row), row.id),
        reverse=True,
    )

    latest_checklists = set()

    for row in inspections:
        date_text = inspection_date(row)
        if date_text and date_text > summary["end_date"]:
            continue

        answers = safe_json_dict_list(row.answers_json)
        snapshot = safe_json_dict(
            row.checklist_snapshot_json
        )
        judgment = safe_json_dict(
            row.operation_judgment_json
        )

        findings = [
            {
                "item_no": answer.get("item_no"),
                "content": short(answer.get("content")),
                "value": short(answer.get("value"), 50),
                "comment": short(answer.get("comment")),
            }
            for answer in answers
            if str(answer.get("value") or "").strip() == "×"
            or str(answer.get("comment") or "").strip()
        ]

        attention = (
            bool(findings)
            or judgment.get("status") in {
                "運行不可", "判定保留",
            }
        )

        if (
            not attention
            and row.checklist_id in latest_checklists
        ):
            continue

        latest_checklists.add(row.checklist_id)

        treatments = []
        stored_defects = judgment.get("defects") or []

        for defect in (
            stored_defects
            if isinstance(stored_defects, list)
            else []
        ):
            if not isinstance(defect, dict):
                continue

            repair = defect.get("repair") or {}
            if not isinstance(repair, dict):
                repair = {}

            treatments.append({
                "defect_no": defect.get("defect_no"),
                "maintenance_source_ids": links_by_defect.get((row.id, defect.get("defect_no")), []),
                "recheck_result": short((defect.get("recheck") or {}).get("result")),
                "recheck_date": short((defect.get("recheck") or {}).get("performed_at"), 30),
                "recheck_note": str((defect.get("recheck") or {}).get("note") or "").strip(),
                "item_no": defect.get("item_no"),
                "status": short(defect.get("status")),
                "repair_note": short(repair.get("note")),
                "repair_date": short(
                    repair.get("performed_at"), 30
                ),
            })

        add(
            "inspection",
            row,
            date_text,
            {
                "type": "日常点検・車両チェックリスト",
                "content": short(
                    snapshot.get("name") or "点検結果"
                ),
                "status": short(row.status),
                "has_attention": attention,
                "answer_count": len(answers),
                "failure_count": sum(
                    str(answer.get("value") or "").strip() == "×"
                    for answer in answers
                ),
                "finding_count": len(findings),
                "findings": findings,
                "treatments": treatments,
                "registered_operation_judgment": short(
                    judgment.get("status")
                ),
                "judgment_reason": short(
                    judgment.get("reason")
                ),
            },
            url_for(
                "vehicle_checklist_results",
                index=row.checklist_id,
                vehicle_record_id=vehicle.id,
                year=row.year,
                month=row.month,
                active_day=row.day,
            ),
        )

    periodic = (
        VehiclePeriodicInspectionRecord.query.filter_by(
            company_code=vehicle.company_code,
            vehicle_record_id=vehicle.id,
        ).all()
    )

    for row in periodic:
        excluded_inspection = periodic_inspection_synthetic_evidence(row)
        if excluded_inspection:
            source_exclusions[(row.company_code, row.vehicle_record_id, excluded_inspection["source_id"])] = excluded_inspection
            continue
        original_draft = VehicleDocumentImportDraft.query.filter_by(
            id=row.source_draft_id, company_code=vehicle.company_code, document_type="inspection",
        ).first()
        inspection_details = build_periodic_inspection_ai_details(row, original_draft)
        add(
            "periodic",
            row,
            row.inspection_date,
            {
                **inspection_details,
                "type": "定期点検",
                "category": short(row.inspection_type),
                "content": short(row.content, 2000),
                "notes": short(
                    safe_json_dict(row.details_json).get("notes"),
                    2000,
                ),
                "mileage": row.mileage,
                "completion_date": row.completion_date,
                "next_inspection_date": (
                    row.next_inspection_date
                ),
            },
            url_for(
                "vehicle_karte_inspections",
                vehicle_record_id=vehicle.id,
            ),
        )

    records.sort(
        key=lambda item: (
            item["date"] or "",
            item["source_id"],
        ),
        reverse=True,
    )
    fingerprints = get_vehicle_karte_analysis_fingerprints(
        vehicle,
        summary,
        records,
    )
    fingerprints["routine_hash"] = hashlib.sha256(
        json.dumps(
            {
                "vehicle": fingerprints["routine_hash"],
                "comparison": comparison,
            },
            sort_keys=True,
            ensure_ascii=False,
            default=str,
        ).encode("utf-8")
    ).hexdigest()
    preventive_facts = build_vehicle_karte_preventive_facts(
        vehicle, summary, records,
    )
    fact_source_ids = {
        source_id
        for fact in preventive_facts["part_replacements"]
        for source_id in fact["source_ids"]
    }
    fact_source_ids.update(
        ident for fact in preventive_facts.get("inspection_items", []) for ident in fact["source_ids"]
    )
    available_count = len(records)
    latest_parts = {}
    for item in records:
        if not item["source_id"].startswith("part:") or not item.get("date"):
            continue
        if item.get("status") != "完了" and not item.get("completion_date"):
            continue
        key = (item.get("content"), item.get("part_number"))
        latest_parts.setdefault(key, item["date"])

    def important_for_analysis(item):
        source_id = item["source_id"]
        if source_id.startswith("maintenance:"):
            return True
        if source_id.startswith("defect:"):
            return item.get("status") in {"未対応", "対応中"}
        if source_id.startswith("inspection:"):
            return bool(item.get("has_attention"))
        if source_id.startswith("periodic:"):
            return bool(item.get("content") or item.get("notes") or item.get("inspection_items"))
        if source_id.startswith("part:"):
            key = (item.get("content"), item.get("part_number"))
            return (
                bool(item.get("date"))
                and item["date"] == latest_parts.get(key)
                and (
                    item.get("status") == "完了"
                    or bool(item.get("completion_date"))
                )
            )
        return False

    protected_records = []
    other_records = []

    for item in records:
        if important_for_analysis(item):
            protected_records.append(item)
        else:
            other_records.append(item)

    protected_count = len(protected_records)
    records = (
        protected_records
        + other_records[:max(0, 80 - protected_count)]
    )

    selected_ids = {
        item["source_id"] for item in records
    }
    evidence_ids = selected_ids | fact_source_ids
    sources = {
        key: value
        for key, value in sources.items()
        if key in evidence_ids
    }

    payload = {
        "vehicle": {
            "model_code": vehicle.model_code,
            "engine_code": getattr(vehicle, "engine_code", None),
            "manufacturer": vehicle.manufacturer,
            "first_registration_date": (
                vehicle.first_registration_date
            ),
            "body_type": vehicle.body_type or None,
            "registered_type": vehicle.type or None,
            "gross_vehicle_weight_kg": vehicle.gross_vehicle_weight,
            "max_payload_kg": vehicle.max_payload,
            "attribute_scope_note": (
                "登録済みの車両台帳情報。空欄は不明。"
                "初度登録日は製造年月ではない。"
                "車体形状・登録区分・重量だけで商品系列、"
                "エンジン、変速機、締結方式、装備、"
                "実際の使用条件を確定しない。"
            ),
        },
        "source_exclusions": list(source_exclusions.values()),
        "summary": summary,
        "comparison": comparison,
        "preventive_facts": preventive_facts,
        "records": records,
        "_fingerprints": fingerprints,
        "coverage": {
            "available_count": available_count,
            "sent_count": len(records),
            "protected_count": protected_count,
            "omitted_count": available_count - len(records),
            "description": (
                "対象は期間終了日以前の履歴。"
                "重要履歴は80件の枠で切り捨てず保持。"
                "通常履歴は合計80件までの残り枠へ追加。"
                "部品別の交換後距離・期間は履歴選択前に計算。"
                "計算に使った交換記録の参照先も保持。"
                "未対応不具合・点検指摘・定期点検内容・"
                "部品別の直近交換記録を優先。"
                "同じ優先区分では新しい順。"
                "日付不明は末尾。"
                "日常点検の指摘・対応は件数で切り捨てず保持。"
                "定期点検の内容・備考は各2000文字、"
                "整備・修理の内容・症状・原因・応急処置・"
                "修理内容・備考と登録明細は文字数で省略しない。"
                "整備・修理以外のその他の自由記述は最大400文字。"
            ),
        },
        "status_note": (
            "状態・修理内容は現在の登録内容。"
            "指定期間終了時点の状態を復元したものではありません。"
        ),
    }

    knowledge, knowledge_sources, knowledge_count = get_vehicle_maintenance_knowledge(
        vehicle, records=records,
    )
    import copy

    rule_timing_fingerprint = []
    for knowledge_item in knowledge:
        evidence = knowledge_item.get("maintenance_rule_evidence") or {}
        for rule in evidence.get("rules", []):
            adoption = rule.get("analysis_adoption") or {}
            if adoption.get("status") != "adopted_for_analysis":
                continue

            timing = calculate_adopted_maintenance_rule_timing(
                rule,
                knowledge_item.get("part_name"),
                preventive_facts,
                summary,
            )
            rule["timing_facts"] = timing
            adoption["calculation_permitted"] = (
                timing["calculation_permitted"]
            )
            adoption["calculation_status"] = (
                "evaluated"
                if timing["calculation_permitted"]
                else "held"
            )
            rule_timing_fingerprint.append({
                "rule_key": adoption.get("rule_key"),
                "timing_facts": timing,
            })

        source_id = knowledge_item["source_id"]
        if source_id in knowledge_sources:
            knowledge_sources[source_id]["snapshot"] = knowledge_item

    knowledge_for_fingerprint = copy.deepcopy(knowledge)
    for knowledge_item in knowledge_for_fingerprint:
        evidence = knowledge_item.get("maintenance_rule_evidence") or {}
        for rule in evidence.get("rules", []):
            rule.pop("timing_facts", None)
            adoption = rule.get("analysis_adoption")
            if isinstance(adoption, dict):
                adoption.pop("calculation_permitted", None)
                adoption.pop("calculation_status", None)

    fingerprints["routine_hash"] = hashlib.sha256(
        json.dumps(
            {
                "history": fingerprints["routine_hash"],
                "maintenance_rule_timing": rule_timing_fingerprint,
            },
            sort_keys=True,
            ensure_ascii=False,
            default=str,
        ).encode("utf-8")
    ).hexdigest()

    payload["maintenance_knowledge"] = knowledge
    payload["knowledge_coverage"] = {
        "matching_count": knowledge_count,
        "sent_count": len(knowledge),
        "description": "利用中・有効期間内でメーカー・型式が一致する知識。指摘・部品・整備記録との文字列関連性、メーカー・型式の限定、登録順で最大20件。資料の発行順ではない。適用条件の成立は別途確認。",
    }
    sources.update(knowledge_sources)
    if knowledge:
        source_id = f"vehicle:{vehicle.id}"
        payload["vehicle_source"] = {
            "source_id": source_id,
            **payload["vehicle"],
            "current_mileage": summary["current_mileage"],
            "current_mileage_date": summary.get("current_mileage_date"),
            "mileage_reference": summary.get("mileage_reference"),
        }
        sources[source_id] = {
            "label": "車両台帳・登録済み走行距離",
            "url": url_for("vehicle_karte", vehicle_record_id=vehicle.id),
        }
    def feedback_uses_excluded_history(row):
        snapshot = safe_json_dict(row.snapshot_json)
        proposal = snapshot.get("proposal") or {}
        linked = snapshot.get("maintenance_record") or {}
        references = proposal.get("source_ids") or []
        return any(value in excluded_source_ids for value in references if isinstance(value, str)) or (
            isinstance(linked, dict) and f"maintenance:{linked.get('id')}" in excluded_source_ids
        )

    feedback_context = []
    for row in latest_vehicle_analysis_feedback(vehicle.company_code, vehicle.id)[:20]:
        if feedback_uses_excluded_history(row):
            continue
        previous = safe_json_dict(row.snapshot_json).get("proposal") or {}
        feedback_context.append({
            "proposal_id": row.proposal_key,
            "target": previous.get("target") or previous.get("title"),
            "action": previous.get("action"),
            "source_ids": previous.get("source_ids", []),
            "status": row.status, "comment": row.comment[:1000],
            "maintenance_record": safe_json_dict(row.snapshot_json).get("maintenance_record"),
            "by": row.created_by, "at": row.created_at,
        })
    evaluation_labels = {
        "appropriate": "適切",
        "needs_revision": "要修正",
        "uncertain": "判断保留",
    }
    for row in latest_vehicle_analysis_evaluations(vehicle.company_code, vehicle.id)[:10]:
        if feedback_uses_excluded_history(row):
            continue
        previous = safe_json_dict(row.snapshot_json).get("proposal") or {}
        feedback_context.append({
            "type": "人による提案内容の評価。実整備結果・確定診断とは別。",
            "proposal_id": row.proposal_key,
            "proposal_revision": row.proposal_revision,
            "target": previous.get("target") or previous.get("title"),
            "action": previous.get("action"),
            "source_ids": previous.get("source_ids", []),
            "evaluation": evaluation_labels.get(row.verdict, row.verdict),
            "comment": row.comment[:1000],
            "by": row.created_by,
            "at": row.created_at,
        })
    payload["feedback_context"] = feedback_context
    fingerprints["important_hash"] = hashlib.sha256(
        json.dumps(
            {
                "history": fingerprints["important_hash"],
                "knowledge": knowledge_for_fingerprint,
                "feedback": feedback_context,
            },
            sort_keys=True, ensure_ascii=False, default=str,
        ).encode("utf-8")
    ).hexdigest()
    fingerprints["has_important_history"] = (
        fingerprints["has_important_history"] or bool(knowledge) or bool(feedback_context)
    )
    return payload, sources


def get_vehicle_karte_peer_comparison(vehicle, summary, registration_scope="same_year", include_inactive=False):
    model = (vehicle.model_code or "").strip().upper()
    registration = str(
        vehicle.first_registration_date or ""
    ).strip()
    year_match = re.match(
        r"^((?:19|20)\d{2})(?:[-/年]|$)",
        registration,
    )

    result = {
        "vehicle_count": None,
        "metrics": [],
        "part_statistics": [],
        "note": "",
    }

    if registration_scope not in {"same_year", "all_years"}:
        registration_scope = "same_year"
    include_inactive = include_inactive is True
    result["registration_scope"] = registration_scope
    result["include_inactive"] = include_inactive
    result["comparison_scope"] = {
        "status": "available",
        "model_code": model or None,
        "registration_scope": registration_scope,
        "reference_registration_year": (
            int(year_match.group(1)) if year_match else None
        ),
        "registration_year_basis": "初度登録年。製造年月ではありません。",
        "include_inactive": include_inactive,
        "start_date": summary.get("start_date"),
        "end_date": summary.get("end_date"),
        "same_company_only": True,
        "target_vehicle_excluded": True,
        "cohort_vehicle_ids": [],
        "active_vehicle_count": None,
        "inactive_vehicle_count": None,
        "status_unknown_vehicle_count": None,
        "data_scope_note": (
            "登録済み記録に基づく比較。比較台数と各指標の"
            "sample_countは異なります。未登録を未交換・故障なしと扱いません。"
        ),
    }
    if not model:
        result["comparison_scope"]["status"] = "missing_model"
        result["note"] = "型式が未登録のため比較できません。"
        return result
    if registration_scope == "same_year" and not year_match:
        result["comparison_scope"]["status"] = "missing_registration_year"
        result["note"] = (
            "同じ初度登録年で比較する条件ですが、対象車両の初度登録年が"
            "不明なため比較できません。比較対象0台という意味ではありません。"
            "画面では「初度登録年を限定しない」で別条件の比較ができます。"
            "画面の条件変更だけでは保存済み自動AIの条件は変わりません。"
        )
        return result

    year = year_match.group(1) if year_match else None
    peers = [
        row
        for row in Vehicle.query.filter_by(
            company_code=vehicle.company_code,
        ).all()
        if row.id != vehicle.id
        and (include_inactive or row.deleted is False)
        and (row.model_code or "").strip().upper() == model
        and (
            registration_scope == "all_years"
            or re.match(
                r"^" + year + r"(?:[-/年]|$)",
                str(row.first_registration_date or "").strip(),
            )
        )
    ]

    year_note = (
        f"同じ初度登録年（{year}年）"
        if registration_scope == "same_year" else "初度登録年を限定しない"
    )
    active_note = "無効車両を含む" if include_inactive else "有効車両のみ"
    result["note"] = (
        f"同じ会社・同型式・{year_note}・{active_note}。"
        "対象車両は平均から除外。"
    )
    result["vehicle_count"] = len(peers)
    result["comparison_scope"].update({
        "status": "available" if peers else "no_peers",
        "cohort_vehicle_ids": sorted(row.id for row in peers),
        "active_vehicle_count": sum(row.deleted is False for row in peers),
        "inactive_vehicle_count": sum(row.deleted is True for row in peers),
        "status_unknown_vehicle_count": sum(
            row.deleted is not False and row.deleted is not True
            for row in peers
        ),
    })

    if not peers:
        result["note"] += " 比較対象車両がありません。"
        return result

    grouped = {
        row.id: {
            "maintenance": [],
            "operations": [],
            "parts": [],
            "defects": [],
        }
        for row in peers
    }
    ids = list(grouped)

    for record_class, key in (
        (VehicleMaintenanceRecord, "maintenance"),
        (VehicleOperationRecord, "operations"),
        (VehiclePartReplacement, "parts"),
        (VehiclePatrol, "defects"),
    ):
        records = (
            record_class.query.filter_by(
                company_code=vehicle.company_code,
            )
            .filter(
                record_class.vehicle_record_id.in_(ids)
            ).all()
        )
        for record in records:
            grouped[record.vehicle_record_id][key].append(
                record
            )

    for values in grouped.values():
        values["maintenance"], values["parts"], values["source_exclusions"] = filter_vehicle_maintenance_factual_history(values["maintenance"], values["parts"])
    result["source_exclusions"] = [
        item for values in grouped.values() for item in values["source_exclusions"]
    ]

    import unicodedata

    part_events = {}
    part_names = {}
    for peer_id, values in grouped.items():
        parents = {
            row.id: row for row in values["maintenance"]
        }
        for part in values["parts"]:
            parent = parents.get(part.maintenance_record_id)
            if parent is None or parent.vehicle_record_id != peer_id:
                continue
            try:
                replaced_on = datetime.strptime(
                    str(part.replacement_date or "")[:10],
                    "%Y-%m-%d",
                ).date().isoformat()
            except ValueError:
                continue
            if not summary["start_date"] <= replaced_on <= summary["end_date"]:
                continue

            name = str(part.part_name or "").strip()
            if not name:
                continue
            normalized_name = re.sub(
                r"[\s・･]+", "",
                unicodedata.normalize("NFKC", name).casefold(),
            ).replace("フィルター", "フィルタ")
            number = str(part.part_number or "").strip()
            key = (normalized_name, number)
            part_names.setdefault(key, set()).add(name)
            part_events.setdefault(key, set()).add(
                (peer_id, parent.id)
            )

    result["part_statistics"] = [
        {
            "part_name": sorted(part_names[key])[0],
            "recorded_names": sorted(part_names[key]),
            "part_number": key[1],
            "registered_event_count": len(events),
            "vehicles_with_registered_events": len({
                peer_id for peer_id, _ in events
            }),
        }
        for key, events in sorted(
            part_events.items(),
            key=lambda item: (-len(item[1]), item[0]),
        )
    ]
    result["part_statistics_note"] = (
        "比較条件・指定期間内の部品交換登録を名称・品番別に集計。"
        "同一車両・同一整備記録・同一部品は1件。"
        "対象車両自身は含まない。未登録車両を未交換と扱わない。"
        "登録内容の真偽・作業完了・故障原因はこの集計では判定しない。"
        "件数の多さだけで故障多発や交換時期を判断しない。"
    )

    from statistics import median

    interval_samples = {}
    for peer in peers:
        values = grouped[peer.id]
        parents = {
            row.id: row for row in values["maintenance"]
        }
        peer_parts = []
        for part in values["parts"]:
            parent = parents.get(part.maintenance_record_id)
            if parent is None or parent.vehicle_record_id != peer.id:
                continue
            peer_parts.append({
                "source_id": f"part:{part.id}",
                "date": part.replacement_date,
                "content": part.part_name,
                "part_number": part.part_number,
                "mileage": part.mileage,
                "status": parent.status,
                "completion_date": parent.completion_date,
            })

        peer_facts = build_vehicle_karte_preventive_facts(
            peer,
            {
                "end_date": summary["end_date"],
                "current_mileage": None,
                "current_mileage_date": None,
            },
            peer_parts,
        )
        for fact in peer_facts["part_replacements"]:
            latest = fact["latest_dated_replacement"]
            if not summary["start_date"] <= latest <= summary["end_date"]:
                continue
            days = fact.get("last_recorded_interval_days")
            if days is None:
                continue
            name = re.sub(
                r"[\s・･]+", "",
                unicodedata.normalize(
                    "NFKC", fact["part_name"],
                ).casefold(),
            ).replace("フィルター", "フィルタ")
            key = (name, fact["part_number"])
            interval_samples.setdefault(key, []).append({
                "vehicle_id": peer.id,
                "days": days,
                "km": fact.get("last_recorded_interval_km"),
            })

    for item in result["part_statistics"]:
        name = re.sub(
            r"[\s・･]+", "",
            unicodedata.normalize(
                "NFKC", item["part_name"],
            ).casefold(),
        ).replace("フィルター", "フィルタ")
        samples = interval_samples.get(
            (name, item["part_number"]), [],
        )
        days = [sample["days"] for sample in samples]
        distances = [
            sample["km"] for sample in samples
            if sample["km"] is not None
        ]
        item.update({
            "latest_interval_sample_count": len(days),
            "latest_interval_distance_sample_count": len(distances),
            "latest_interval_days_median": median(days) if days else None,
            "latest_interval_km_median": (
                median(distances) if distances else None
            ),
        })

    result["part_interval_note"] = (
        "各比較対象車両の、期間内で直近の登録交換とその前回との間隔。"
        "同一部品・品番につき1台最大1組。前回は期間開始前も参照する。"
        "交換完了の登録がある記録を使用。全交換間隔の平均ではない。"
        "期間と距離の母数は別で、距離不明・逆転は距離集計から除外。"
        "途中の未登録作業やテスト記録等の真偽は未確認。"
        "メーカー基準・推奨交換間隔・故障発生間隔を意味しない。"
    )

    summaries = [
        build_vehicle_karte_analysis_summary(
            values["maintenance"],
            values["operations"],
            values["parts"],
            values["defects"],
            summary["start_date"],
            summary["end_date"],
        )
        for values in grouped.values()
    ]

    for field, label, unit in (
        ("total_cost", "期間内の整備費", "円"),
        ("failure_count", "登録故障件数", "件"),
        ("part_replacement_count", "部品交換登録件数", "件"),
        ("cost_per_km", "1kmあたり整備費", "円/km"),
    ):
        def comparable(item):
            if (
                field == "total_cost"
                and item["missing_cost_count"]
            ):
                return None
            return item[field]

        values = [comparable(item) for item in summaries]
        known = [
            Decimal(str(value))
            for value in values if value is not None
        ]
        average = (
            sum(known, Decimal("0")) / len(known)
            if known else None
        )
        current = comparable(summary)

        result["metrics"].append({
            "label": label,
            "unit": unit,
            "current": current,
            "average": average,
            "sample_count": len(known),
            "vehicles_with_registered_events": (
                sum(value > 0 for value in known)
                if field in {
                    "failure_count", "part_replacement_count",
                }
                else None
            ),
            "sample_scope_note": (
                "登録件数の平均には登録0件の比較対象車両も含む。"
                "登録0件は実際の故障・交換がなかった証明ではない。"
                if field in {
                    "failure_count", "part_replacement_count",
                }
                else
                "平均の母数はsample_count。比較対象の全台数とは"
                "限らず、記録のある費用・距離に基づく比較。"
            ),
            "difference_percentage": (
                (Decimal(str(current)) - average)
                / average * Decimal("100")
                if current is not None
                and average is not None
                and average > 0
                else None
            ),
        })

    return result


@app.route(
    "/vehicle/karte/<int:vehicle_record_id>/analysis",
    methods=["GET"],
)
def vehicle_karte_analysis(vehicle_record_id):
    from flask import abort

    if not session.get("username"):
        return redirect(url_for("login"))

    vehicle = Vehicle.query.filter_by(
        id=vehicle_record_id,
        company_code=session.get("company_code"),
    ).first_or_404()

    today = datetime.now(
        ZoneInfo("Asia/Tokyo")
    ).date()

    default_start = today.replace(
        year=today.year - 2,
        day=min(
            today.day,
            calendar.monthrange(
                today.year - 2, today.month
            )[1],
        ),
    )

    start_text = request.args.get(
        "start_date", default_start.isoformat()
    )
    end_text = request.args.get(
        "end_date", today.isoformat()
    )

    try:
        start = datetime.strptime(
            start_text, "%Y-%m-%d"
        ).date()
        end = datetime.strptime(
            end_text, "%Y-%m-%d"
        ).date()

        if (
            start.isoformat() != start_text
            or end.isoformat() != end_text
            or start > end
            or (end - start).days > 366 * 5
        ):
            raise ValueError()
    except ValueError:
        abort(
            400,
            description=(
                "分析期間は開始日から終了日の順で、"
                "5年以内を指定してください。"
            ),
        )

    maintenance = (
        VehicleMaintenanceRecord.query.filter_by(
            company_code=vehicle.company_code,
            vehicle_record_id=vehicle.id,
        ).all()
    )

    operations = (
        VehicleOperationRecord.query.filter_by(
            company_code=vehicle.company_code,
            vehicle_record_id=vehicle.id,
        )
        .filter(
            VehicleOperationRecord.operation_date
            <= end.isoformat()
        ).all()
    )

    parts = (
        VehiclePartReplacement.query
        .join(
            VehicleMaintenanceRecord,
            VehiclePartReplacement.maintenance_record_id
            == VehicleMaintenanceRecord.id,
        )
        .filter(
            VehiclePartReplacement.company_code
            == vehicle.company_code,
            VehiclePartReplacement.vehicle_record_id
            == vehicle.id,
            VehicleMaintenanceRecord.company_code
            == vehicle.company_code,
            VehicleMaintenanceRecord.vehicle_record_id
            == vehicle.id,
        ).all()
    )

    defects = VehiclePatrol.query.filter_by(
        company_code=vehicle.company_code,
        vehicle_record_id=vehicle.id,
    ).all()

    summary = build_vehicle_karte_analysis_summary(
        maintenance,
        operations,
        parts,
        defects,
        start.isoformat(),
        end.isoformat(),
        periodic_records=(
            VehiclePeriodicInspectionRecord.query.filter_by(
                company_code=vehicle.company_code,
                vehicle_record_id=vehicle.id,
            ).all()
        ),
    )

    number = vehicle_number({
        "plate_area": vehicle.plate_area or "",
        "plate_class": vehicle.plate_class or "",
        "plate_kana": vehicle.plate_kana or "",
        "plate_number": vehicle.plate_number or "",
    })

    if request.method == "POST":
        comparison = get_vehicle_karte_peer_comparison(
            vehicle, summary
        )
        payload, sources = build_vehicle_karte_analysis_payload(
            vehicle,
            summary,
            comparison,
            maintenance,
            parts,
            defects,
        )

        if not payload["records"]:
            result = {
                "overview": (
                    "分析の根拠となる整備・部品交換・"
                    "故障の履歴がありません。"
                ),
                "recommendations": [],
            }
        else:
            try:
                result = analyze_vehicle_karte(payload)
            except (ValueError, RuntimeError) as error:
                code = str(error)
                app.logger.warning(
                    "車両AI分析に失敗しました: %s",
                    code,
                )

                if code == "API_KEY_NOT_SET":
                    message = (
                        "AI接続用のOPENAI_API_KEYが"
                        "設定されていません。"
                        "サーバー設定を確認してください。"
                    )
                    status = 503
                elif code == "ANALYSIS_NETWORK_OR_TIMEOUT":
                    message = (
                        "AIとの通信が完了せず、"
                        "分析結果を取得できませんでした。"
                    )
                    status = 504
                elif code == "ANALYSIS_HTTP_429":
                    message = (
                        "AIサービスの利用上限に達したか、"
                        "リクエストが集中しています。"
                    )
                    status = 429
                else:
                    message = (
                        "AI分析の結果を取得・検証"
                        "できませんでした。"
                        "時間をおいて再実行してください。"
                    )
                    status = 502

                return jsonify(
                    ok=False,
                    message=message,
                ), status

        return jsonify(
            ok=True,
            analysis=result,
            sources=sources,
            coverage=payload["coverage"],
            generated_at=datetime.now(
                ZoneInfo("Asia/Tokyo")
            ).strftime("%Y/%m/%d %H:%M"),
        )

    return render_template(
        "vehicle_karte_analysis.html",
        vehicle=vehicle,
        vehicle_number=number,
        open_defects=get_vehicle_open_inspection_defects(
            vehicle.company_code,
            vehicle.id,
        ),
        inspection_defect_progress=get_vehicle_open_inspection_defects(
            vehicle.company_code,
            vehicle.id,
            include_resolved=True,
        ),
        analysis_summary=summary,
        analysis_progress=build_vehicle_karte_service_progress(
            maintenance, summary
        ),
        analysis_comparison=get_vehicle_karte_peer_comparison(
            vehicle,
            summary,
            registration_scope=request.args.get("peer_registration", "same_year"),
            include_inactive=request.args.get("peer_inactive") == "1",
        ),
        analysis_today=today.isoformat(),
        format_analysis_number=(
            format_vehicle_maintenance_number
        ),
    )


@app.route("/vehicle/karte/<int:vehicle_record_id>/costs")
def vehicle_karte_costs(vehicle_record_id):
    from flask import abort

    if not session.get("username"):
        return redirect(url_for("login"))

    vehicle = Vehicle.query.filter_by(
        id=vehicle_record_id,
        company_code=session.get("company_code"),
    ).first_or_404()

    current_year = datetime.now(
        ZoneInfo("Asia/Tokyo")
    ).year
    selected_year = request.args.get(
        "year", current_year, type=int
    )
    if not 1900 <= selected_year <= current_year + 1:
        abort(400)

    records = VehicleMaintenanceRecord.query.filter_by(
        company_code=vehicle.company_code,
        vehicle_record_id=vehicle.id,
    ).all()

    details = get_vehicle_maintenance_cost_details(
        records, selected_year
    )
    details["available_years"] = sorted(
        set(details["available_years"]) | {current_year},
        reverse=True,
    )

    number = vehicle_number({
        "plate_area": vehicle.plate_area or "",
        "plate_class": vehicle.plate_class or "",
        "plate_kana": vehicle.plate_kana or "",
        "plate_number": vehicle.plate_number or "",
    })

    return render_template(
        "vehicle_karte_costs.html",
        vehicle=vehicle,
        vehicle_number=number,
        open_defects=get_vehicle_open_inspection_defects(
            vehicle.company_code,
            vehicle.id,
        ),
        cost_details=details,
        format_cost_number=format_vehicle_maintenance_number,
        cost_current_year=current_year,
    )


def get_vehicle_maintenance_cost_details(maintenance_records, selected_year):
    selected_year = int(selected_year)
    if not 2 <= selected_year <= 9999:
        raise ValueError("集計年が不正です。")

    records, _, synthetic_exclusions = filter_vehicle_maintenance_factual_history(maintenance_records)
    dated_records = []
    undated_records = []

    for record in records:
        date_text = (
            (record.entry_date or "").strip()
            or (record.completion_date or "").strip()
        )
        try:
            record_date = datetime.strptime(
                date_text, "%Y-%m-%d"
            ).date()
        except ValueError:
            undated_records.append(record)
            continue

        dated_records.append((record_date, record))

    def summarize(items):
        return get_vehicle_maintenance_cost_summary(items)

    def year_records(year):
        return [
            record for record_date, record in dated_records
            if record_date.year == year
        ]

    selected_records = year_records(selected_year)
    previous_records = year_records(selected_year - 1)
    selected_summary = summarize(selected_records)
    previous_summary = summarize(previous_records)

    selected_total = selected_summary["total_cost"]
    previous_total = previous_summary["total_cost"]

    change_amount = None
    change_percentage = None
    if selected_total is not None and previous_total is not None:
        change_amount = selected_total - previous_total
        if previous_total > 0:
            change_percentage = (
                change_amount / previous_total * Decimal("100")
            )

    monthly_costs = []
    for month in range(1, 13):
        items = [
            record for record_date, record in dated_records
            if record_date.year == selected_year
            and record_date.month == month
        ]
        monthly_costs.append({
            "month": month,
            "amount": summarize(items)["total_cost"],
            "record_count": len(items),
            "missing_amount_count": sum(
                record.total_cost is None for record in items
            ),
        })

    yearly_costs = []
    for year in range(max(1, selected_year - 2), selected_year + 1):
        items = year_records(year)
        yearly_costs.append({
            "year": year,
            "amount": summarize(items)["total_cost"],
            "record_count": len(items),
            "missing_amount_count": sum(
                record.total_cost is None for record in items
            ),
        })

    selected_dated = [
        (record_date, record)
        for record_date, record in dated_records
        if record_date.year == selected_year
    ]

    high_cost_records = [
        record
        for record_date, record in sorted(
            selected_dated,
            key=lambda item: (
                item[1].total_cost
                if item[1].total_cost is not None
                else Decimal("0"),
                item[0],
                item[1].id,
            ),
            reverse=True,
        )
        if record.total_cost is not None
    ][:5]

    recent_records = [
        record
        for record_date, record in sorted(
            selected_dated,
            key=lambda item: (item[0], item[1].id),
            reverse=True,
        )
    ][:5]

    today = datetime.now(ZoneInfo("Asia/Tokyo")).date()
    average_end = today.replace(day=1)
    average_start = average_end.replace(year=average_end.year - 1)
    rolling_records = [
        record for record_date, record in dated_records
        if average_start <= record_date < average_end
    ]
    rolling_total = summarize(rolling_records)["total_cost"]
    rolling_average = (
        rolling_total / Decimal("12")
        if rolling_total is not None else None
    )

    return {
        "source_exclusions": synthetic_exclusions,
        "rolling_average": rolling_average,
        "average_start": average_start.isoformat(),
        "average_end_exclusive": average_end.isoformat(),
        "average_last_month": datetime.fromordinal(
            average_end.toordinal() - 1
        ).strftime("%Y/%m"),
        "rolling_missing_amount_count": sum(
            record.total_cost is None for record in rolling_records
        ),
        "selected_year": selected_year,
        "all_time_summary": summarize(records),
        "selected_summary": selected_summary,
        "previous_total": previous_total,
        "change_amount": change_amount,
        "change_percentage": change_percentage,
        "monthly_costs": monthly_costs,
        "yearly_costs": yearly_costs,
        "high_cost_records": high_cost_records,
        "recent_records": recent_records,
        "selected_record_count": len(selected_records),
        "missing_amount_count": sum(
            record.total_cost is None for record in selected_records
        ),
        "undated_record_count": len(undated_records),
        "available_years": sorted({
            record_date.year for record_date, record in dated_records
        } | {selected_year}, reverse=True),
    }


def get_vehicle_maintenance_cost_summary(maintenance_records):
    maintenance_records, _, synthetic_exclusions = filter_vehicle_maintenance_factual_history(maintenance_records)
    maintenance_summary = {"total_cost": None, "annual_costs": [], "source_exclusions": synthetic_exclusions}
    costs = [
        record.total_cost
        for record in maintenance_records
        if record.total_cost is not None
    ]
    if costs:
        maintenance_summary["total_cost"] = sum(
            costs, Decimal("0")
        )

    current_year = datetime.now(ZoneInfo("Asia/Tokyo")).year
    annual_totals = {}
    annual_counts = {}

    for record in maintenance_records:
        if record.total_cost is None:
            continue

        date_text = (
            (record.entry_date or "").strip()
            or (record.completion_date or "").strip()
        )
        try:
            record_date = datetime.strptime(
                date_text, "%Y-%m-%d"
            ).date()
        except ValueError:
            continue

        year = record_date.year
        if current_year - 4 <= year <= current_year:
            annual_totals[year] = (
                annual_totals.get(year, Decimal("0"))
                + record.total_cost
            )
            annual_counts[year] = annual_counts.get(year, 0) + 1

    maintenance_summary["annual_costs"] = [
        {
            "year": year,
            "amount": (
                str(annual_totals[year])
                if year in annual_totals else None
            ),
            "count": annual_counts.get(year, 0),
        }
        for year in range(current_year - 4, current_year + 1)
    ]

    category_totals = {}
    for record in maintenance_records:
        if record.total_cost is None:
            continue
        category = (record.category or "").strip() or "未分類"
        category_totals[category] = (
            category_totals.get(category, Decimal("0"))
            + record.total_cost
        )

    category_total = sum(category_totals.values(), Decimal("0"))
    show_cost_ring = (
        category_total > 0
        and all(amount >= 0 for amount in category_totals.values())
    )
    category_colors = (
        "#397dea", "#72adef", "#49bda9",
        "#e8b64b", "#9982ce", "#94a3b8",
    )
    maintenance_summary["show_cost_ring"] = show_cost_ring
    maintenance_summary["category_costs"] = [
        {
            "label": category,
            "amount": amount,
            "percentage": (
                amount / category_total * Decimal("100")
                if show_cost_ring else None
            ),
            "color": category_colors[index % len(category_colors)],
        }
        for index, (category, amount) in enumerate(sorted(
            category_totals.items(),
            key=lambda item: (-item[1], item[0]),
        ))
    ]

    return maintenance_summary


def get_vehicle_periodic_inspection_summary(company_code, vehicle_record_id):
    """Last performed inspection and explicitly recorded next date, per type."""
    def parsed(value):
        try:
            return datetime.strptime(str(value or ""), "%Y-%m-%d").date()
        except ValueError:
            return None

    today = datetime.now(ZoneInfo("Asia/Tokyo")).date()
    latest = {}
    for record in VehiclePeriodicInspectionRecord.query.filter_by(
        company_code=company_code, vehicle_record_id=vehicle_record_id
    ).all():
        performed = parsed(record.inspection_date)
        if record.inspection_type not in {"3month", "12month"} or performed is None or performed > today:
            continue
        previous = latest.get(record.inspection_type)
        if previous is None or (performed, record.id) > previous[:2]:
            latest[record.inspection_type] = (performed, record.id, record)
    result = {}
    for kind, (performed, _, record) in latest.items():
        due = parsed(record.next_inspection_date)
        result[kind] = {
            "record_id": record.id, "last_date": performed.isoformat(),
            "mileage": record.mileage,
            "next_date": due.isoformat() if due and due >= performed else None,
        }
    return result


@app.context_processor
def inject_vehicle_karte_choices():
    if request.endpoint not in {
        "vehicle_karte_list",
        "vehicle_karte",
        "vehicle_karte_history",
        "vehicle_karte_inspections",
        "vehicle_periodic_followup",
        "vehicle_karte_documents",
        "vehicle_karte_maintenance",
        "vehicle_karte_maintenance_form",
        "vehicle_karte_parts",
        "vehicle_karte_costs",
        "vehicle_karte_analysis",
    }:
        return {}

    company_code = session.get("company_code")
    if not company_code:
        return {"karte_vehicle_choices": []}

    vehicles = Vehicle.query.filter_by(
        company_code=company_code
    ).order_by(Vehicle.id.asc()).all()

    driver_names_by_vehicle = {
        str(record.id): []
        for record in vehicles
    }

    drivers = Driver.query.filter_by(
        company_code=company_code
    ).order_by(Driver.id.asc()).all()

    for driver in drivers:
        driver_name = (driver.name or "").strip()
        if not driver_name:
            continue

        for vehicle_id in safe_json_str_list(
            driver.vehicles_json
        ):
            names = driver_names_by_vehicle.get(
                vehicle_id
            )
            if names is not None and driver_name not in names:
                names.append(driver_name)

    choices = []
    for record in vehicles:
        number = vehicle_number({
            "plate_area": record.plate_area or "",
            "plate_class": record.plate_class or "",
            "plate_kana": record.plate_kana or "",
            "plate_number": record.plate_number or "",
        })

        choices.append({
            "id": record.id,
            "number": number,
            "chassis_number": record.chassis_number or "",
            "driver_names": "、".join(
                driver_names_by_vehicle.get(
                    str(record.id),
                    []
                )
            ),
        })

    operation_summary = {
        "current_mileage": None,
        "mileage_date": None,
    }

    vehicle_record_id = (
        request.view_args or {}
    ).get("vehicle_record_id")

    if any(
        record.id == vehicle_record_id
        for record in vehicles
    ):
        operation_summary = get_vehicle_operation_summary(
            company_code,
            vehicle_record_id
        )

    maintenance_summary = {
        "last_mileage": None,
        "last_date": None,
        "distance_since": None,
        "total_cost": None,
        "annual_costs": [],
    }

    if any(
        record.id == vehicle_record_id
        for record in vehicles
    ):
        maintenance_records = VehicleMaintenanceRecord.query.filter_by(
            company_code=company_code,
            vehicle_record_id=vehicle_record_id,
        ).all()

        maintenance_summary.update(
            get_vehicle_maintenance_cost_summary(maintenance_records)
        )

        maintenance_records, _, _ = filter_vehicle_maintenance_factual_history(maintenance_records)
        completed_records = [
            record
            for record in maintenance_records
            if (
                (record.completion_date or "").strip()
                or record.status == "完了"
            )
            and (
                (record.completion_date or "").strip()
                or (record.entry_date or "").strip()
            )
        ]
        if completed_records:
            latest_record = max(
                completed_records,
                key=lambda record: (
                    (record.completion_date or "").strip()
                    or (record.entry_date or "").strip(),
                    record.id,
                ),
            )
            maintenance_summary["last_mileage"] = latest_record.mileage
            maintenance_summary["last_date"] = (
                latest_record.completion_date
                or latest_record.entry_date
            )

            current_mileage = operation_summary.get("current_mileage")
            try:
                measured_on = datetime.strptime(
                    str(operation_summary.get("mileage_date") or "")[:10].replace("/", "-"),
                    "%Y-%m-%d",
                ).date()
                maintained_on = datetime.strptime(
                    str(maintenance_summary.get("last_date") or "")[:10].replace("/", "-"),
                    "%Y-%m-%d",
                ).date()
            except ValueError:
                measured_on = maintained_on = None

            if (
                operation_summary.get(
                    "mileage_reference", {}
                ).get("distance_usable") is True
                and current_mileage is not None
                and latest_record.mileage is not None
                and measured_on is not None
                and maintained_on is not None
                and measured_on >= maintained_on
            ):
                difference = (
                    Decimal(str(current_mileage))
                    - Decimal(str(latest_record.mileage))
                )
                if difference >= 0:
                    maintenance_summary["distance_since"] = difference

    return {
        "karte_vehicle_choices": choices,
        "karte_usage_vehicles": get_vehicle_karte_usage_vehicles(),
        "karte_operation_summary": operation_summary,
        "karte_maintenance_summary": maintenance_summary,
        "karte_execution_summary": (
            inspection_plans.latest(company_code, vehicle_record_id)
            if any(record.id == vehicle_record_id for record in vehicles) else {}
        ),
        "karte_issue_counts": {
            "daily": len(get_vehicle_open_inspection_defects(company_code, vehicle_record_id)),
            "periodic": periodic_followups.summary(company_code, vehicle_record_id)["open_count"],
        } if any(record.id == vehicle_record_id for record in vehicles) else {},
        "karte_plan_summary": (
            inspection_plans.summary(company_code, vehicle_record_id)
            if any(record.id == vehicle_record_id for record in vehicles) else {}
        ),
        "karte_periodic_summary": (
            get_vehicle_periodic_inspection_summary(company_code, vehicle_record_id)
            if any(record.id == vehicle_record_id for record in vehicles) else {}
        ),
        "karte_recent_maintenance": (
            sorted(
                maintenance_records,
                key=lambda record: (
                    (record.entry_date or "").strip()
                    or (record.completion_date or "").strip(),
                    record.id,
                ),
                reverse=True,
            )[:5]
            if request.endpoint == "vehicle_karte"
            and any(
                record.id == vehicle_record_id
                for record in vehicles
            )
            else []
        ),
    }


@app.route("/vehicle/karte")
def vehicle_karte_list():
    selected_value = request.args.get(
        "vehicle_record_id",
        ""
    ).strip()

    if selected_value:
        selected_id = request.args.get(
            "vehicle_record_id",
            type=int
        )

        if (
            selected_id is None
            or selected_id <= 0
            or selected_id > 9223372036854775807
        ):
            flash(
                "表示する車両を選択し直してください。",
                "error:karte_vehicle_search"
            )
            return render_template(
                "vehicle_karte.html",
                vehicle=None
            ), 400

        selected_vehicle = Vehicle.query.filter_by(
            id=selected_id,
            company_code=session.get("company_code")
        ).first()

        if selected_vehicle is None:
            flash(
                "選択した車両を表示できません。車両を選択し直してください。",
                "error:karte_vehicle_search"
            )
            return render_template(
                "vehicle_karte.html",
                vehicle=None
            ), 404

        return redirect(url_for(
            "vehicle_karte",
            vehicle_record_id=selected_vehicle.id
        ))

    usage_vehicles = get_vehicle_karte_usage_vehicles()

    if usage_vehicles:
        current_user = User.query.filter_by(
            company_code=session.get("company_code"),
            username=session.get("username")
        ).first()

        user_settings = safe_json_dict(
            current_user.dashboard_settings_json
        ) if current_user is not None else {}

        last_vehicle_id = str(user_settings.get(
            "vehicle_karte_last_vehicle_id",
            ""
        ))

        default_vehicle = next(
            (
                record
                for record in usage_vehicles
                if str(record.id) == last_vehicle_id
            ),
            usage_vehicles[0]
        )

        return redirect(url_for(
            "vehicle_karte",
            vehicle_record_id=default_vehicle.id
        ))

    return render_template(
        "vehicle_karte.html",
        vehicle=None
    )


@app.route("/master/vehicles/invoice-reviews/<document_id>/duplicate", methods=["POST"])
@limiter.limit("10 per minute", methods=["POST"])
def vehicle_maintenance_document_duplicate(document_id):
    if not require_master_admin():
        return "この操作は管理者のみ利用できます。", 403

    if request.form.get("already_recorded") != "1":
        return return_form_errors([(
            "費用・交換内容がすべて登録済みであることを確認してください。",
            "already_recorded"
        )])

    company_code = session.get("company_code")
    username = session.get("username")
    if not company_code or not username:
        return "会社・利用者を確認できません。", 403

    try:
        company = Company.query.filter_by(
            company_code=company_code
        ).with_for_update().first()
        if company is None:
            raise UploadValidationError("会社情報を確認できません。")

        document = VehicleMaintenanceDocument.query.filter_by(
            id=document_id, company_code=company_code
        ).with_for_update().populate_existing().first_or_404()

        vehicle = Vehicle.query.filter_by(
            id=document.vehicle_record_id,
            company_code=company_code
        ).first_or_404()

        model = (
            VehicleMaintenanceRecord
            if document.maintenance_record_id is not None
            else VehiclePeriodicInspectionRecord
        )
        target_id = (
            document.maintenance_record_id
            or document.inspection_record_id
        )
        model.query.filter_by(
            id=target_id,
            company_code=company_code,
            vehicle_record_id=vehicle.id
        ).first_or_404()

        draft = VehicleDocumentImportDraft.query.filter_by(
            id=document.source_draft_id,
            company_code=company_code,
            document_type="maintenance",
            status="completed"
        ).first_or_404()

        if hashlib.sha256(draft.source_file).hexdigest() != draft.source_sha256:
            raise UploadValidationError("保存済みの原本を確認できません。")

        if document.financial_status not in {"pending", "duplicate"}:
            raise UploadValidationError(
                "費用の確定状態が変わっています。一覧から再確認してください。"
            )

        if document.financial_status == "pending" or document.parts_status == "pending":
            decision = json.loads(document.decision_json or "{}")
            if not isinstance(decision, dict) or not isinstance(
                decision.get("review_history", []), list
            ):
                raise UploadValidationError("確認履歴を読み取れません。")

            now = datetime.now(ZoneInfo("UTC"))
            history = list(decision.get("review_history", []))
            history.append({
                "action": "already_recorded",
                "financial_status_before": document.financial_status,
                "parts_status_before": document.parts_status,
                "username": username,
                "reviewed_at": now.isoformat(),
            })

            document.financial_status = "duplicate"
            if document.parts_status == "pending":
                document.parts_status = "not_applicable"

            document.decision_json = json.dumps({
                **decision,
                "review_history": history,
                "review_action": "already_recorded",
            }, ensure_ascii=False)
            document.reviewed_by_username = username
            document.reviewed_at = now

        if request.headers.get("X-DKSS-Validation-Only") == "1":
            db.session.rollback()
            return jsonify({"ok": True})

        db.session.commit()

    except (UploadValidationError, ValueError) as error:
        db.session.rollback()
        return return_form_errors([(str(error), "")])
    except SQLAlchemyError:
        db.session.rollback()
        app.logger.exception("請求書の確認結果を保存できませんでした。")
        return return_form_errors([
            ("確認結果を保存できませんでした。再度お試しください。", "")
        ], status_code=500)

    flash(
        "登録済みの内容として確認しました。原本を残し、費用・交換回数は追加していません。",
        "success"
    )
    return redirect(url_for("vehicle_maintenance_document_reviews"))


@app.route("/master/vehicles/invoice-reviews/<document_id>/initial-cost", methods=["POST"])
@limiter.limit("10 per minute", methods=["POST"])
def vehicle_maintenance_document_initial_cost(document_id):
    return review_vehicle_maintenance_document_cost(document_id, "initial_cost")


@app.route("/master/vehicles/invoice-reviews/<document_id>/correction", methods=["POST"])
@limiter.limit("10 per minute", methods=["POST"])
def vehicle_maintenance_document_correction(document_id):
    return review_vehicle_maintenance_document_cost(document_id, "correction")


def calculate_vehicle_invoice_correction(target, replacement_id, incoming_amounts):
    fields = ("labor_cost", "parts_cost", "other_cost", "tax_amount", "total_cost")

    def parse_costs(values):
        if not isinstance(values, dict) or any(field not in values for field in fields):
            raise ValueError("請求額の確認履歴が不足しています。")
        costs = {}
        for field in fields:
            raw = values[field]
            value = None if raw is None else Decimal(str(raw))
            if value is not None and (
                not value.is_finite() or abs(value) > Decimal("999999999999.99")
                or value != value.quantize(Decimal("0.01"))
            ):
                raise ValueError("請求額の確認履歴が不正です。")
            costs[field] = value
        return costs

    ledger = []
    for old in VehicleMaintenanceDocument.query.filter(
        VehicleMaintenanceDocument.company_code == target.company_code,
        VehicleMaintenanceDocument.vehicle_record_id == target.vehicle_record_id,
        VehicleMaintenanceDocument.maintenance_record_id == target.id,
        VehicleMaintenanceDocument.financial_status.in_(("confirmed", "superseded"))
    ).with_for_update().populate_existing().all():
        decision = json.loads(old.decision_json or "{}")
        if not isinstance(decision, dict) or decision.get("costs_applied") is not True:
            raise ValueError("費用の反映履歴を確認できません。")
        costs = parse_costs(decision.get("confirmed_costs"))
        history = decision.get("review_history")
        if not isinstance(history, list) or not all(isinstance(item, dict) for item in history):
            raise ValueError("費用の確認履歴が不正です。")
        actions = [item for item in history if item.get("action") in {
            "initial_cost", "additional_cost", "correction"
        }]
        if len(actions) != 1 or costs["total_cost"] is None:
            raise ValueError("費用の確認履歴が不足しています。")
        when = datetime.fromisoformat(actions[0]["reviewed_at"])
        if when.tzinfo is None:
            raise ValueError("費用の確認日時が不正です。")
        ledger.append((when, old, decision, costs, actions[0]["action"]))
    if not ledger:
        raise ValueError("差し替え可能な確定済み請求書がありません。")
    ledger.sort(key=lambda item: (item[0], item[1].id))
    first = ledger[0]
    if first[4] == "initial_cost":
        baseline = {field: Decimal("0") for field in fields}
    elif first[4] == "additional_cost":
        baseline = parse_costs(first[2].get("costs_before"))
        if baseline["total_cost"] is None:
            raise ValueError("請求書の反映前の費用を確認できません。")
    else:
        raise ValueError("最初の費用の反映履歴を確認できません。")
    active = [item for item in ledger if item[1].financial_status == "confirmed"]
    selected = next((item for item in active if item[1].id == replacement_id), None)
    if selected is None:
        raise ValueError("訂正前の請求書は確認状態が変わっています。選び直してください。")
    if any(item[4] == "initial_cost" for item in ledger[1:]):
        raise ValueError("初回費用の履歴が重複しています。")

    def aggregate(invoices):
        result = {}
        for field in fields:
            values = [baseline[field]] + [costs[field] for costs in invoices]
            result[field] = None if any(value is None for value in values) else sum(values, Decimal("0"))
            if result[field] is not None and abs(result[field]) > Decimal("999999999999.99"):
                raise ValueError("訂正後の費用が登録可能な金額を超えます。")
        return result

    current = aggregate([item[3] for item in active])
    if any(current[field] != getattr(target, field) for field in fields):
        raise ValueError("登録済み費用と請求書の履歴が一致しません。費用を再確認してください。")
    old = selected[1]
    draft = VehicleDocumentImportDraft.query.filter_by(
        id=old.source_draft_id, company_code=target.company_code,
        document_type="maintenance", status="completed"
    ).first()
    if draft is None or hashlib.sha256(draft.source_file).hexdigest() != draft.source_sha256:
        raise ValueError("訂正前の原本を確認できません。")
    payload = json.loads(old.payload_json)
    records = safe_json_dict(draft.preview_json).get("records")
    index = old.source_record_index
    if (not isinstance(payload, dict) or not isinstance(records, list)
            or type(index) is not int or not 0 <= index < len(records)
            or records[index] != payload):
        raise ValueError("訂正前の明細を確認できません。")
    source_costs = parse_costs({
        field: None if payload.get(field) in (None, "") else payload[field]
        for field in fields
    })
    if source_costs != selected[3]:
        raise ValueError("訂正前の請求額と反映履歴が一致しません。")
    return aggregate([
        item[3] for item in active if item[1].id != replacement_id
    ] + [incoming_amounts]), old


def review_vehicle_maintenance_document_cost(document_id, cost_mode):
    if not require_master_admin():
        return "この操作は管理者のみ利用できます。", 403
    if cost_mode not in {"initial_cost", "additional_cost", "correction"}:
        return "確認方法が不正です。", 400
    confirm_field = "confirm_" + cost_mode
    if request.form.get(confirm_field) != "1":
        return return_form_errors([("請求額の反映方法を確認してください。", confirm_field)])
    company_code = session.get("company_code")
    username = session.get("username")
    if not company_code or not username:
        return "会社・利用者を確認できません。", 403
    try:
        if Company.query.filter_by(company_code=company_code).with_for_update().first() is None:
            raise ValueError("会社情報を確認できません。")
        document = VehicleMaintenanceDocument.query.filter_by(
            id=document_id, company_code=company_code
        ).with_for_update().populate_existing().first_or_404()
        Vehicle.query.filter_by(
            id=document.vehicle_record_id, company_code=company_code
        ).first_or_404()
        if document.financial_status != "pending" or document.maintenance_record_id is None:
            raise ValueError("費用の確定状態・登録先を一覧から再確認してください。")
        target = VehicleMaintenanceRecord.query.filter_by(
            id=document.maintenance_record_id, company_code=company_code,
            vehicle_record_id=document.vehicle_record_id
        ).with_for_update().populate_existing().first_or_404()
        fields = ("labor_cost", "parts_cost", "other_cost", "tax_amount", "total_cost")
        if cost_mode == "initial_cost":
            if any(getattr(target, field) is not None for field in fields) or VehicleMaintenanceDocument.query.filter_by(
                company_code=company_code, maintenance_record_id=target.id,
                financial_status="confirmed"
            ).first() is not None:
                raise ValueError("登録済みの費用があります。追加請求・訂正として確認してください。")
        else:
            if target.total_cost is None:
                raise ValueError("追加先の合計金額がありません。初回費用として確認してください。")
            expected_total = Decimal(request.form.get("expected_total", ""))
            if not expected_total.is_finite() or expected_total != target.total_cost:
                raise ValueError("登録済みの金額が変わりました。一覧を開き直してください。")
        draft = VehicleDocumentImportDraft.query.filter_by(
            id=document.source_draft_id, company_code=company_code,
            document_type="maintenance", status="completed"
        ).first_or_404()
        if hashlib.sha256(draft.source_file).hexdigest() != draft.source_sha256:
            raise ValueError("保存済みの原本を確認できません。")
        payload = json.loads(document.payload_json)
        records = safe_json_dict(draft.preview_json).get("records")
        index = document.source_record_index
        if (not isinstance(payload, dict) or not isinstance(records, list)
                or type(index) is not int or not 0 <= index < len(records)
                or records[index] != payload
                or payload.get("vehicle_record_id") not in (None, document.vehicle_record_id)):
            raise ValueError("保存済み明細の一致を確認できません。")
        incoming = build_vehicle_document_record(draft, index, {
            **payload, "vehicle_record_id": document.vehicle_record_id
        })
        amounts = {field: getattr(incoming, field) for field in fields}
        if amounts["total_cost"] is None or any(
            value is not None and value < 0 for value in amounts.values()
        ):
            raise ValueError("合計金額がない資料・マイナス金額は、初回費用として確定できません。")
        components = [amounts[field] for field in fields[:-1]]
        if all(value is not None for value in components) and sum(components) != amounts["total_cost"]:
            raise ValueError("内訳と合計金額が一致しません。原本を確認してください。")
        decision = json.loads(document.decision_json or "{}")
        if not isinstance(decision, dict) or not isinstance(
            decision.get("review_history", []), list
        ):
            raise ValueError("確認履歴を読み取れません。")
        now = datetime.now(ZoneInfo("UTC"))
        before_costs = {field: getattr(target, field) for field in fields}
        confirmed_costs = {
            field: str(value) if value is not None else None
            for field, value in amounts.items()
        }
        replaced_document = None
        if cost_mode == "correction":
            amounts, replaced_document = calculate_vehicle_invoice_correction(
                target, request.form.get("replaces_document_id", ""), amounts
            )
        elif cost_mode == "additional_cost":
            amounts = {
                field: before_costs[field] + amounts[field]
                if before_costs[field] is not None and amounts[field] is not None
                else None
                for field in fields
            }
            if any(value is not None and abs(value) > Decimal("999999999999.99")
                   for value in amounts.values()):
                raise ValueError("加算後の費用が登録可能な金額を超えます。")
        changes = []
        for field, value in amounts.items():
            setattr(target, field, value)
            if before_costs[field] != value:
                changes.append({
                    "field": field,
                    "before": str(before_costs[field]) if before_costs[field] is not None else None,
                    "after": str(value) if value is not None else None,
                })
        target.updated_by_username = username
        target.updated_at = datetime.now(
            ZoneInfo("Asia/Tokyo")
        ).isoformat(timespec="seconds")
        add_vehicle_maintenance_record_event(
            target, action="updated", changes=changes
        )
        document.financial_status = "confirmed"
        if replaced_document is not None:
            document.related_document_id = replaced_document.id
            old_decision = json.loads(replaced_document.decision_json)
            replaced_document.financial_status = "superseded"
            replaced_document.decision_json = json.dumps({
                **old_decision,
                "replaced_by_document_id": document.id,
                "review_history": old_decision["review_history"] + [{
                    "action": "superseded", "replacement_document_id": document.id,
                    "username": username, "reviewed_at": now.isoformat(),
                }],
            }, ensure_ascii=False)
            replaced_document.reviewed_by_username = username
            replaced_document.reviewed_at = now
        document.decision_json = json.dumps({
            **decision,
            "costs_applied": True,
            "review_action": cost_mode,
            "cost_record_id": target.id,
            "confirmed_costs": confirmed_costs,
            "costs_before": {
                field: str(value) if value is not None else None
                for field, value in before_costs.items()
            },
            "costs_after": {
                field: str(value) if value is not None else None
                for field, value in amounts.items()
            },
            "review_history": decision.get("review_history", []) + [{
                "action": cost_mode,
                "username": username,
                "reviewed_at": now.isoformat()
            }],
        }, ensure_ascii=False)
        document.reviewed_by_username = username
        document.reviewed_at = now
        if request.headers.get("X-DKSS-Validation-Only") == "1":
            db.session.rollback()
            return jsonify({"ok": True})
        db.session.commit()
    except (ValueError, KeyError, TypeError, InvalidOperation) as error:
        db.session.rollback()
        return return_form_errors([(
            "請求書の金額・明細・確認状態を確認してください。 " + str(error), ""
        )])
    except SQLAlchemyError:
        db.session.rollback()
        app.logger.exception("初回の請求費用を保存できませんでした。")
        return return_form_errors([(
            "費用を保存できませんでした。再度お試しください。", ""
        )], status_code=500)
    flash(
        "請求額を反映しました。交換部品の確認状態はそのまま保持しています。",
        "success"
    )
    return redirect(url_for("vehicle_maintenance_document_reviews"))


@app.route("/master/vehicles/invoice-reviews/<document_id>/additional-cost", methods=["POST"])
@limiter.limit("10 per minute", methods=["POST"])
def vehicle_maintenance_document_additional_cost(document_id):
    return review_vehicle_maintenance_document_cost(document_id, "additional_cost")


def vehicle_invoice_parts_version(parts):
    return hashlib.sha256(json.dumps([
        [part.id, part.part_name, part.part_number, str(part.quantity),
         part.replacement_date, str(part.mileage), str(part.cost)]
        for part in sorted(parts, key=lambda item: item.id)
    ], ensure_ascii=False).encode("utf-8")).hexdigest()


@app.route("/master/vehicles/invoice-reviews/<document_id>/parts", methods=["POST"])
@limiter.limit("10 per minute", methods=["POST"])
def vehicle_maintenance_document_parts(document_id):
    if not require_master_admin():
        return "この操作は管理者のみ利用できます。", 403
    if request.form.get("confirm_parts") != "1":
        return return_form_errors([("原本と交換履歴を確認してください。", "confirm_parts")])
    company_code = session.get("company_code")
    username = session.get("username")
    if not company_code or not username:
        return "会社・利用者を確認できません。", 403
    try:
        if Company.query.filter_by(company_code=company_code).with_for_update().first() is None:
            raise ValueError("会社情報を確認できません。")
        document = VehicleMaintenanceDocument.query.filter_by(
            id=document_id, company_code=company_code
        ).with_for_update().populate_existing().first_or_404()
        if (document.parts_status != "pending" or document.maintenance_record_id is None
                or document.financial_status not in {"pending", "confirmed", "superseded"}):
            raise ValueError("部品の確認状態・登録先を一覧から再確認してください。")
        Vehicle.query.filter_by(id=document.vehicle_record_id, company_code=company_code).first_or_404()
        target = VehicleMaintenanceRecord.query.filter_by(
            id=document.maintenance_record_id, company_code=company_code,
            vehicle_record_id=document.vehicle_record_id
        ).with_for_update().populate_existing().first_or_404()
        draft = VehicleDocumentImportDraft.query.filter_by(
            id=document.source_draft_id, company_code=company_code,
            document_type="maintenance", status="completed"
        ).first_or_404()
        if hashlib.sha256(draft.source_file).hexdigest() != draft.source_sha256:
            raise ValueError("保存済みの原本を確認できません。")
        payload = json.loads(document.payload_json)
        records = safe_json_dict(draft.preview_json).get("records")
        index = document.source_record_index
        if (not isinstance(payload, dict) or not isinstance(records, list)
                or type(index) is not int or not 0 <= index < len(records)
                or records[index] != payload
                or payload.get("vehicle_record_id") not in (None, document.vehicle_record_id)):
            raise ValueError("保存済み明細の一致を確認できません。")
        lines = payload.get("line_items") or []
        if not isinstance(lines, list) or len(lines) > 1000 or not all(isinstance(line, dict) for line in lines):
            raise ValueError("請求書の明細を確認できません。")
        parts = VehiclePartReplacement.query.filter_by(
            company_code=company_code, vehicle_record_id=target.vehicle_record_id,
            maintenance_record_id=target.id
        ).with_for_update().populate_existing().all()
        if request.form.get("parts_version") != vehicle_invoice_parts_version(parts):
            raise ValueError("交換履歴が変わりました。一覧を開き直してください。")
        decision = json.loads(document.decision_json or "{}")
        if not isinstance(decision, dict) or not isinstance(decision.get("review_history", []), list):
            raise ValueError("確認履歴を読み取れません。")

        def number(raw, required=False):
            if raw is None or str(raw).strip() == "":
                if required:
                    raise ValueError("新規の交換には数量が必要です。")
                return None
            if isinstance(raw, bool) or len(str(raw)) > 100:
                raise ValueError("部品の数値を確認してください。")
            value = parse_maintenance_invoice_number(raw)
            if (not value.is_finite() or value < 0 or abs(value) > Decimal("999999999999.99")
                    or value != value.quantize(Decimal("0.01"))):
                raise ValueError("部品の数値を確認してください。")
            return value

        now = datetime.now(ZoneInfo("UTC"))
        confirmed = []
        created_count = 0
        import unicodedata
        normalize = lambda value: "".join(unicodedata.normalize("NFKC", value or "").split()).casefold()
        for line_index, line in enumerate(lines):
            action = request.form.get("part_choice_" + str(line_index), "")
            if action == "none":
                confirmed.append({"source_line_index": line_index, "action": "not_replace"})
                continue
            if action.startswith("existing:"):
                existing_id = int(action.split(":", 1)[1])
                part = next((item for item in parts if item.id == existing_id), None)
                if part is None:
                    raise ValueError("同じ整備の交換履歴を選択してください。")
            elif action == "new":
                name = request.form.get("part_name_" + str(line_index), "").strip()
                part_number = request.form.get("part_number_" + str(line_index), "").strip()
                if not name or len(name) > 200 or len(part_number) > 100:
                    raise ValueError("新規の交換には部品名が必要です。名称・品番の文字数も確認してください。")
                quantity = number(request.form.get("part_quantity_" + str(line_index)), required=True)
                if quantity <= 0:
                    raise ValueError("交換数量は0より大きい数値で入力してください。")
                replacement_date = request.form.get("replacement_date", "")
                if datetime.strptime(replacement_date, "%Y-%m-%d").date().isoformat() != replacement_date:
                    raise ValueError("交換日を確認してください。")
                if any(item.replacement_date == replacement_date and (
                    normalize(item.part_number) == normalize(part_number)
                    if item.part_number and part_number
                    else normalize(item.part_name) == normalize(name)
                ) for item in parts):
                    raise ValueError("同じ日・同じ部品の交換履歴があります。登録済みの交換を選んでください。別の交換の場合はカルテで内容を確認してください。")
                part = VehiclePartReplacement(
                    company_code=company_code, vehicle_record_id=target.vehicle_record_id,
                    maintenance_record_id=target.id, part_name=name,
                    part_number=part_number or None, quantity=quantity,
                    replacement_date=replacement_date,
                    mileage=number(request.form.get("replacement_mileage")),
                    cost=number(line.get("parts_amount")),
                    notes="請求書の確認から登録（明細" + str(line_index + 1) + "）",
                    created_by_username=username,
                    created_at=datetime.now(ZoneInfo("Asia/Tokyo")).isoformat(timespec="seconds"),
                )
                db.session.add(part)
                db.session.flush()
                parts.append(part)
                created_count += 1
            else:
                raise ValueError("すべての明細で、登録済み・新規交換・交換対象外のいずれかを選んでください。")
            confirmed.append({
                "source_line_index": line_index, "action": action,
                "replacement_id": part.id, "part_name": part.part_name,
                "part_number": part.part_number, "quantity": str(part.quantity),
                "replacement_date": part.replacement_date,
            })
        document.parts_status = "confirmed" if any("replacement_id" in item for item in confirmed) else "not_applicable"
        document.decision_json = json.dumps({
            **decision, "parts_applied": created_count > 0,
            "confirmed_parts": confirmed,
            "review_history": decision.get("review_history", []) + [{
                "action": "parts_review", "username": username,
                "reviewed_at": now.isoformat(), "created_count": created_count,
            }],
        }, ensure_ascii=False)
        document.reviewed_by_username = username
        document.reviewed_at = now
        if request.headers.get("X-DKSS-Validation-Only") == "1":
            db.session.rollback()
            return jsonify({"ok": True})
        db.session.commit()
    except (ValueError, KeyError, TypeError, InvalidOperation) as error:
        db.session.rollback()
        return return_form_errors([("交換部品を確認してください。 " + str(error), "")])
    except SQLAlchemyError:
        db.session.rollback()
        app.logger.exception("請求書の交換部品を保存できませんでした。")
        return return_form_errors([("交換部品を保存できませんでした。再度お試しください。", "")], status_code=500)
    flash("交換部品を確認しました。新規登録は" + str(created_count) + "件です。費用は変更していません。", "success")
    return redirect(url_for("vehicle_maintenance_document_reviews"))


@app.route("/master/vehicles/invoice-reviews")
def vehicle_maintenance_document_reviews():
    if not require_master_admin():
        return "この操作は管理者のみ利用できます。", 403

    company_code = session.get("company_code")
    query = db.session.query(
        VehicleMaintenanceDocument, Vehicle, VehicleDocumentImportDraft
    ).join(
        Vehicle,
        db.and_(
            Vehicle.id == VehicleMaintenanceDocument.vehicle_record_id,
            Vehicle.company_code == company_code
        )
    ).join(
        VehicleDocumentImportDraft,
        db.and_(
            VehicleDocumentImportDraft.id == VehicleMaintenanceDocument.source_draft_id,
            VehicleDocumentImportDraft.company_code == company_code
        )
    ).filter(
        VehicleMaintenanceDocument.company_code == company_code,
        or_(
            VehicleMaintenanceDocument.financial_status == "pending",
            db.and_(
                VehicleMaintenanceDocument.financial_status.in_(("confirmed", "superseded")),
                VehicleMaintenanceDocument.parts_status == "pending"
            )
        )
    )

    total = query.count()
    total_pages = max(1, (total + 9) // 10)
    page = max(1, min(
        request.args.get("page", 1, type=int), total_pages
    ))
    rows = []

    for document, vehicle, draft in query.order_by(
        VehicleMaintenanceDocument.created_at.desc(),
        VehicleMaintenanceDocument.id.asc()
    ).offset((page - 1) * 10).limit(10).all():
        is_maintenance = document.maintenance_record_id is not None
        model = (
            VehicleMaintenanceRecord if is_maintenance
            else VehiclePeriodicInspectionRecord
        )
        target_id = (
            document.maintenance_record_id if is_maintenance
            else document.inspection_record_id
        )
        target = model.query.filter_by(
            id=target_id,
            company_code=company_code,
            vehicle_record_id=vehicle.id
        ).first()
        if target is None:
            continue

        replacement_parts = VehiclePartReplacement.query.filter_by(
            company_code=company_code, vehicle_record_id=vehicle.id,
            maintenance_record_id=target.id
        ).order_by(VehiclePartReplacement.id).all() if is_maintenance else []
        rows.append({
            "parts_review_available": is_maintenance and document.parts_status == "pending",
            "replacement_parts": replacement_parts,
            "parts_version": vehicle_invoice_parts_version(replacement_parts),
            "id": document.id,
            "vehicle_id": vehicle.id,
            "vehicle_number": vehicle_number({
                "plate_area": vehicle.plate_area or "",
                "plate_class": vehicle.plate_class or "",
                "plate_kana": vehicle.plate_kana or "",
                "plate_number": vehicle.plate_number or "",
            }),
            "office": vehicle.office or "未設定",
            "draft_id": draft.id,
            "filename": draft.source_filename,
            "record_index": document.source_record_index,
            "payload": safe_json_dict(document.payload_json),
            "target_kind": "整備記録" if is_maintenance else "点検記録",
            "target_date": (
                target.entry_date if is_maintenance
                else target.inspection_date
            ),
            "target_content": target.content or "",
            "existing_total": target.total_cost if is_maintenance else None,
            "financial_label": "訂正前（費用は集計対象外）" if document.financial_status == "superseded"
                else "確認待ち" if document.financial_status == "pending" else "確認済み",
            "correction_candidates": [{
                "id": previous.id,
                "invoice_number": safe_json_dict(previous.payload_json).get("invoice_number") or "番号なし",
                "total_cost": safe_json_dict(previous.payload_json).get("total_cost"),
                "draft_id": previous.source_draft_id,
            } for previous in VehicleMaintenanceDocument.query.filter_by(
                company_code=company_code, vehicle_record_id=vehicle.id,
                maintenance_record_id=target.id, financial_status="confirmed"
            ).order_by(VehicleMaintenanceDocument.created_at, VehicleMaintenanceDocument.id).all()
              if safe_json_dict(previous.decision_json).get("costs_applied") is True]
                if is_maintenance and document.financial_status == "pending" and target.total_cost is not None else [],
            "can_additional_cost": is_maintenance and document.financial_status == "pending"
                and target.total_cost is not None
                and safe_json_dict(document.payload_json).get("total_cost") not in (None, ""),
            "can_initial_cost": is_maintenance and document.financial_status == "pending"
                and all(getattr(target, field) is None for field in (
                    "labor_cost", "parts_cost", "other_cost", "tax_amount", "total_cost"
                )) and safe_json_dict(document.payload_json).get("total_cost") not in (None, ""),
            "financial_pending": document.financial_status == "pending",
            "parts_pending": document.parts_status == "pending",
        })

    return render_template(
        "vehicle_master.html",
        invoice_review_rows=rows,
        invoice_review_count=total,
        invoice_review_page=page,
        invoice_review_total_pages=total_pages,
        pending_vehicle_count=vehicle_import_pending_query(company_code).count(),
    )


def get_vehicle_pending_identity_match(identity, vehicles, plate_candidates):
    plate = normalize_vehicle_operation_plate(
        identity.get("source_vehicle_number")
    )
    candidate_ids = plate_candidates.get(plate, []) if plate else []
    source_chassis = normalize_vehicle_operation_plate(
        identity.get("chassis_number")
    )
    pending_identity_conflict = False
    pending_match_reason = "取込元のナンバーと一致する登録済み車両です。"

    if source_chassis and source_chassis not in {
        "不明", "記載なし", "未設定", "なし", "unknown", "none", "n/a"
    }:
        chassis_ids = {
            vehicle.id for vehicle in vehicles
            if normalize_vehicle_operation_plate(
                vehicle.chassis_number
            ) == source_chassis
        }
        if chassis_ids:
            if candidate_ids and not chassis_ids.intersection(candidate_ids):
                candidate_ids = []
                pending_identity_conflict = True
            else:
                candidate_ids = sorted(
                    chassis_ids.intersection(candidate_ids)
                    if candidate_ids else chassis_ids
                )
                pending_match_reason = "取込元の車台番号と一致する登録済み車両です。"
        elif candidate_ids:
            compatible_ids = {
                vehicle.id for vehicle in vehicles
                if not normalize_vehicle_operation_plate(
                    vehicle.chassis_number
                )
            }
            filtered_ids = [
                item for item in candidate_ids
                if item in compatible_ids
            ]
            pending_identity_conflict = (
                len(filtered_ids) != len(candidate_ids)
            )
            candidate_ids = [] if pending_identity_conflict else filtered_ids

    return candidate_ids, pending_identity_conflict, pending_match_reason


def get_vehicle_pending_workspace(company_code, selected_id=None):
    """Read-only queue, scoped to the current company; search spans every pending group."""
    keyword = request.args.get("q", "").strip()[:100]
    normalized = normalize_vehicle_operation_plate(keyword)
    groups = vehicle_import_pending_query(company_code).order_by(
        VehicleImportPending.created_at.asc(), VehicleImportPending.id.asc()
    ).all()
    summaries = {}
    for pending_id, kind, count in db.session.query(
        VehicleImportPendingRecord.pending_id,
        VehicleImportPendingRecord.source_kind,
        db.func.count(VehicleImportPendingRecord.id)
    ).join(
        VehicleImportPending,
        VehicleImportPending.id == VehicleImportPendingRecord.pending_id
    ).filter(
        VehicleImportPending.company_code == company_code,
        VehicleImportPending.status == "pending",
        VehicleImportPendingRecord.company_code == company_code,
        VehicleImportPendingRecord.status == "pending"
    ).group_by(
        VehicleImportPendingRecord.pending_id, VehicleImportPendingRecord.source_kind
    ).all():
        summaries.setdefault(pending_id, []).append((kind, count))
    labels = {
        "operation": "運行実績", "driving_report": "運行日報",
        "inspection": "点検記録", "maintenance": "請求書・整備資料"
    }
    rows = []
    for group in groups:
        identity = safe_json_dict(group.identity_json)
        plate = str(identity.get("source_vehicle_number") or "").strip()
        code = str(identity.get("source_vehicle_code") or "").strip()
        chassis = str(identity.get("chassis_number") or "").strip()
        if normalized and not any(
            normalized in normalize_vehicle_operation_plate(value)
            for value in (plate, code, chassis)
        ):
            continue
        kinds = summaries.get(group.id, [])
        rows.append({
            "id": group.id, "identity": identity,
            "title": plate or ("車両コード " + code if code else "車両情報未確認"),
            "record_count": sum(count for _, count in kinds),
            "summary": " ／ ".join(
                labels.get(kind, "その他") + " " + str(count) + "件"
                for kind, count in sorted(kinds)
            ),
        })
    selected_index = next((i for i, row in enumerate(rows) if row["id"] == selected_id), None)
    pages = max(1, (len(rows) + 19) // 20)
    page = max(1, min(request.args.get("page", 1, type=int), pages))
    if selected_index is not None:
        page = selected_index // 20 + 1
    visible = rows[(page - 1) * 20:page * 20]
    vehicles, plate_candidates = get_vehicle_operation_plate_candidates(company_code)
    for row in visible:
        ids, conflict, _ = get_vehicle_pending_identity_match(
            row["identity"], vehicles, plate_candidates
        )
        if len(ids) == 1 and not conflict:
            row.update(label="候補あり", tone="match")
        elif conflict or ids:
            row.update(label="要確認", tone="check")
        elif get_vehicle_import_pending_plate(row["identity"]):
            row.update(label="新規候補", tone="new")
        else:
            row.update(label="情報不足", tone="missing")
    return {
        "keyword": keyword, "rows": visible, "total": len(groups),
        "filtered_count": len(rows), "page": page, "pages": pages,
        "position": selected_index + 1 if selected_index is not None else 0,
        "previous_id": rows[selected_index - 1]["id"] if selected_index is not None and selected_index > 0 else None,
        "next_id": rows[selected_index + 1]["id"] if selected_index is not None and selected_index + 1 < len(rows) else None,
        "first_id": visible[0]["id"] if visible else None,
    }


@app.route("/master/vehicles")
def vehicle_master():
    if request.args.get("view", "") != "pending":
        return render_vehicle_list("vehicle_master.html")

    if not require_master_admin():
        return "この操作は管理者のみ利用できます。", 403

    workspace = get_vehicle_pending_workspace(session.get("company_code"))

    if workspace["first_id"]:
        return redirect(url_for(
            "vehicle_import_pending_review",
            pending_id=workspace["first_id"],
            q=workspace["keyword"]
        ))

    return render_template(
        "vehicle_master.html",
        pending_workspace=workspace,
        pending_vehicle_count=workspace["total"],
    )


@app.route(
    "/master/vehicles/pending/<pending_id>", methods=["GET", "POST"]
)
@limiter.limit("10 per minute", methods=["POST"])
def vehicle_import_pending_review(pending_id):
    if not require_master_admin():
        return "この操作は管理者のみ利用できます。", 403

    company_code = session.get("company_code")
    pending = VehicleImportPending.query.filter_by(
        id=pending_id, company_code=company_code
    ).first_or_404()
    if pending.status != "pending":
        flash("この登録待ちは対応済みか、処理中です。", "info")
        return redirect(url_for("vehicle_master", view="pending"))

    if request.method == "POST":
        action = request.form.get("pending_action", "link")
        if action not in {"link", "create"}:
            return return_form_errors([("操作を選び直してください。", "")])

        vehicle_id = request.form.get("vehicle_record_id", type=int)
        if action == "link" and (
            vehicle_id is None or not 0 < vehicle_id <= 9223372036854775807
        ):
            return return_form_errors([
                ("登録先の車両を選択してください。", "vehicle_record_id")
            ])
        try:
            if action == "create":
                vehicle = create_vehicle_from_pending_operations(
                    pending, company_code
                )
                vehicle_id = vehicle.id
            questions = get_vehicle_pending_invoice_questions(
                pending.id, vehicle_id, company_code
            )
            invoice_choices = {
                question["pending_record_id"]: request.form.get(
                    "invoice_choice_" + question["pending_record_id"], ""
                )
                for question in questions
            }
            if questions and not all(invoice_choices.values()):
                db.session.rollback()
                if request.headers.get("X-DKSS-Validation-Only") == "1":
                    return jsonify({"ok": True})
                return render_template(
                    "vehicle_master.html",
                    pending_detail={"id": pending.id},
                    pending_invoice_questions=questions,
                    pending_invoice_vehicle_id=vehicle_id,
                    pending_workspace=get_vehicle_pending_workspace(company_code, pending.id),
                    pending_vehicle_count=vehicle_import_pending_query(
                        company_code
                    ).count(),
                )
            result = apply_vehicle_import_pending_records(
                pending.id, vehicle_id, company_code, session.get("username"),
                invoice_choices=invoice_choices
            )
            if request.headers.get("X-DKSS-Validation-Only") == "1":
                db.session.rollback()
                return jsonify({"ok": True})
            db.session.commit()
        except (UploadValidationError, ValueError, InvalidOperation) as error:
            db.session.rollback()
            return return_form_errors([(str(error), "")])
        except IntegrityError:
            db.session.rollback()
            return return_form_errors([
                ("別の操作で更新されました。一覧から再確認してください。", "")
            ])
        except SQLAlchemyError:
            db.session.rollback()
            app.logger.exception("登録待ち実績の紐付けに失敗しました。")
            return return_form_errors([
                ("保存できませんでした。時間をおいて再度お試しください。", "")
            ], status_code=500)

        flash(
            ("車両を登録しました。" if action == "create" else "")
            + f"取込済みデータ{result['linked_count']}件を紐付けました。原本もカルテから確認できます。"
            + (
                f"うち請求書{result['review_pending_count']}件は、費用・部品を確認待ちで保存しました。"
                if result.get("review_pending_count") else ""
            ),
            "success"
        )
        if request.form.get("queue_continue") == "1":
            workspace = get_vehicle_pending_workspace(company_code)
            next_id = request.form.get("queue_next", "")
            if next_id and not vehicle_import_pending_query(company_code).filter(
                VehicleImportPending.id == next_id
            ).first():
                next_id = None
            next_id = next_id or workspace["first_id"]
            if next_id:
                return redirect(url_for(
                    "vehicle_import_pending_review", pending_id=next_id,
                    q=workspace["keyword"]
                ))
            return redirect(url_for(
                "vehicle_master", view="pending", q=workspace["keyword"]
            ))
        return redirect(url_for(
            "vehicle_karte", vehicle_record_id=vehicle_id
        ))

    vehicles, plate_candidates = get_vehicle_operation_plate_candidates(
        company_code
    )
    identity = safe_json_dict(pending.identity_json)
    plate = normalize_vehicle_operation_plate(
        identity.get("source_vehicle_number")
    )
    candidate_ids = plate_candidates.get(plate, []) if plate else []
    source_chassis = normalize_vehicle_operation_plate(
        identity.get("chassis_number")
    )
    pending_identity_conflict = False
    pending_match_reason = "取込元のナンバーと一致する登録済み車両です。"

    if source_chassis and source_chassis not in {
        "不明", "記載なし", "未設定", "なし", "unknown", "none", "n/a"
    }:
        chassis_ids = {
            vehicle.id for vehicle in vehicles
            if normalize_vehicle_operation_plate(
                vehicle.chassis_number
            ) == source_chassis
        }
        if chassis_ids:
            if candidate_ids and not chassis_ids.intersection(candidate_ids):
                candidate_ids = []
                pending_identity_conflict = True
            else:
                candidate_ids = sorted(
                    chassis_ids.intersection(candidate_ids)
                    if candidate_ids else chassis_ids
                )
                pending_match_reason = "取込元の車台番号と一致する登録済み車両です。"
        elif candidate_ids:
            compatible_ids = {
                vehicle.id for vehicle in vehicles
                if not normalize_vehicle_operation_plate(
                    vehicle.chassis_number
                )
            }
            filtered_ids = [
                item for item in candidate_ids
                if item in compatible_ids
            ]
            pending_identity_conflict = (
                len(filtered_ids) != len(candidate_ids)
            )
            candidate_ids = [] if pending_identity_conflict else filtered_ids

    choices = [{
        "id": vehicle.id,
        "number": vehicle_number({
            "plate_area": vehicle.plate_area or "",
            "plate_class": vehicle.plate_class or "",
            "plate_kana": vehicle.plate_kana or "",
            "plate_number": vehicle.plate_number or "",
        }),
        "chassis_number": vehicle.chassis_number,
        "office": vehicle.office,
        "deleted": vehicle.deleted,
    } for vehicle in vehicles]

    suggested = next((item for item in choices if (
        len(candidate_ids) == 1 and item["id"] == candidate_ids[0]
    )), None)

    summary = db.session.query(
        db.func.count(VehicleImportPendingRecord.id),
        db.func.min(VehicleImportPendingRecord.record_date),
        db.func.max(VehicleImportPendingRecord.record_date)
    ).filter_by(
        pending_id=pending.id, company_code=company_code, status="pending"
    ).one()

    source_drafts = db.session.query(
        VehicleOperationImportDraft.id,
        VehicleOperationImportDraft.source_filename,
        VehicleOperationImportDraft.created_at
    ).join(
        VehicleImportPendingRecord,
        VehicleImportPendingRecord.operation_draft_id == VehicleOperationImportDraft.id
    ).filter(
        VehicleOperationImportDraft.company_code == company_code,
        VehicleImportPendingRecord.company_code == company_code,
        VehicleImportPendingRecord.pending_id == pending.id,
        VehicleImportPendingRecord.source_kind == "operation",
        VehicleImportPendingRecord.status == "pending"
    ).distinct().order_by(
        VehicleOperationImportDraft.created_at.desc(),
        VehicleOperationImportDraft.id.asc()
    ).all()

    pending_sources = []
    for source in source_drafts:
        created_at = source.created_at
        if created_at.tzinfo is None:
            created_at = created_at.replace(tzinfo=ZoneInfo("UTC"))
        pending_sources.append({
            "id": source.id,
            "kind": "operation",
            "filename": source.source_filename,
            "created_at": created_at.astimezone(
                ZoneInfo("Asia/Tokyo")
            ).strftime("%Y/%m/%d %H:%M"),
        })

    document_sources = db.session.query(
        VehicleDocumentImportDraft.id,
        VehicleDocumentImportDraft.source_filename,
        VehicleDocumentImportDraft.created_at
    ).join(
        VehicleImportPendingRecord,
        VehicleImportPendingRecord.document_draft_id == VehicleDocumentImportDraft.id
    ).filter(
        VehicleDocumentImportDraft.company_code == company_code,
        VehicleImportPendingRecord.company_code == company_code,
        VehicleImportPendingRecord.pending_id == pending.id,
        VehicleImportPendingRecord.source_kind == VehicleDocumentImportDraft.document_type,
        VehicleImportPendingRecord.status == "pending"
    ).distinct().all()

    for source in document_sources:
        created_at = source.created_at
        if created_at.tzinfo is None:
            created_at = created_at.replace(tzinfo=ZoneInfo("UTC"))
        pending_sources.append({
            "id": source.id,
            "kind": "document",
            "filename": source.source_filename,
            "created_at": created_at.astimezone(
                ZoneInfo("Asia/Tokyo")
            ).strftime("%Y/%m/%d %H:%M"),
        })
    pending_sources.sort(
        key=lambda source: source["created_at"],
        reverse=True
    )

    labels = {
        "operation": "運行実績",
        "driving_report": "運行日報",
        "inspection": "点検記録",
        "maintenance": "請求書・整備資料",
    }
    pending_record_counts = [{
        "label": labels.get(kind, "その他"),
        "count": count,
    } for kind, count in db.session.query(
        VehicleImportPendingRecord.source_kind,
        db.func.count(VehicleImportPendingRecord.id)
    ).filter_by(
        pending_id=pending.id,
        company_code=company_code,
        status="pending"
    ).group_by(
        VehicleImportPendingRecord.source_kind
    ).order_by(
        VehicleImportPendingRecord.source_kind
    ).all()]

    return render_template(
        "vehicle_master.html",
        pending_record_counts=pending_record_counts,
        pending_sources=pending_sources,
        pending_workspace=get_vehicle_pending_workspace(company_code, pending.id),
        pending_documents=[{
            "draft_id": draft.id,
            "filename": draft.source_filename,
            "record_index": record.source_record_index,
            "kind": record.source_kind,
            "record_date": record.record_date,
            "payload": safe_json_dict(record.payload_json),
        } for record, draft in db.session.query(
            VehicleImportPendingRecord, VehicleDocumentImportDraft
        ).join(
            VehicleDocumentImportDraft,
            VehicleDocumentImportDraft.id == VehicleImportPendingRecord.document_draft_id
        ).filter(
            VehicleImportPendingRecord.company_code == company_code,
            VehicleImportPendingRecord.pending_id == pending.id,
            VehicleImportPendingRecord.status == "pending",
            VehicleDocumentImportDraft.company_code == company_code,
        ).order_by(
            VehicleImportPendingRecord.record_date.desc(),
            VehicleImportPendingRecord.id.asc()
        ).limit(10).all()],
        pending_detail={
            "id": pending.id,
            "identity": identity,
            "record_count": summary[0],
            "date_from": summary[1],
            "date_to": summary[2],
        },
        pending_suggested=suggested,
        pending_identity_conflict=pending_identity_conflict,
        pending_match_reason=pending_match_reason,
        pending_new_plate=(
            get_vehicle_import_pending_plate(identity)
            if not candidate_ids and not pending_identity_conflict else None
        ),
        pending_choices=choices,
        pending_choose=request.args.get("choose") == "1",
        pending_vehicle_count=vehicle_import_pending_query(
            company_code
        ).count(),
    )


@app.route("/master/vehicles/pending/<pending_id>/sources/<draft_id>")
def vehicle_import_pending_operation_source(pending_id, draft_id):
    if not require_master_admin():
        return "この操作は管理者のみ利用できます。", 403

    company_code = session.get("company_code")
    VehicleImportPending.query.filter_by(
        id=pending_id, company_code=company_code
    ).first_or_404()

    belongs_to_pending = db.session.query(
        VehicleImportPendingRecord.id
    ).filter(
        VehicleImportPendingRecord.pending_id == pending_id,
        VehicleImportPendingRecord.company_code == company_code,
        VehicleImportPendingRecord.source_kind == "operation",
        VehicleImportPendingRecord.operation_draft_id == draft_id
    ).exists()

    draft = VehicleOperationImportDraft.query.filter(
        VehicleOperationImportDraft.id == draft_id,
        VehicleOperationImportDraft.company_code == company_code,
        belongs_to_pending
    ).first_or_404()

    response = send_file(
        BytesIO(draft.source_file),
        mimetype="text/csv",
        download_name=draft.source_filename,
        as_attachment=True,
        conditional=False,
        etag=False,
        max_age=0
    )
    response.headers["X-Content-Type-Options"] = "nosniff"
    response.headers["Cache-Control"] = "private, no-store"
    return response


def get_vehicle_import_pending_plate(identity):
    plate = normalize_vehicle_operation_plate(
        identity.get("source_vehicle_number")
    ).upper()
    match = re.fullmatch(
        r"([一-龥々ヶぁ-んァ-ヶ]{1,20})([0-9][0-9A-Z]{1,2})([ぁ-ゖ])([0-9]{1,4})",
        plate
    )
    if match is None or int(match.group(4)) == 0:
        return None
    return dict(zip(
        ("plate_area", "plate_class", "plate_kana", "plate_number"),
        match.groups()
    ))


def create_vehicle_from_pending_operations(pending, company_code):
    if pending.company_code != company_code or pending.status != "pending":
        raise UploadValidationError("登録待ちの車両を再確認してください。")

    parts = get_vehicle_import_pending_plate(
        safe_json_dict(pending.identity_json)
    )
    if parts is None:
        raise UploadValidationError(
            "新規登録に必要なナンバーを確認できません。資料を追加して確認してください。"
        )

    company = Company.query.filter_by(
        company_code=company_code
    ).with_for_update().first()
    if company is None:
        raise UploadValidationError("会社情報を確認できません。")

    active_count = Vehicle.query.filter_by(
        company_code=company_code, deleted=False
    ).count()
    if active_count >= (company.vehicle_limit or 0):
        raise UploadValidationError("登録可能台数の上限に達しています。")

    vehicles, plate_candidates = get_vehicle_operation_plate_candidates(
        company_code
    )
    source_chassis = str(
        safe_json_dict(pending.identity_json).get("chassis_number") or ""
    ).strip()
    normalized_chassis = normalize_vehicle_operation_plate(source_chassis)

    if not normalized_chassis or normalized_chassis in {
        "不明", "記載なし", "未設定", "なし", "unknown", "none", "n/a"
    }:
        source_chassis = ""
        normalized_chassis = ""

    if len(source_chassis) > 100:
        raise UploadValidationError("原本の車台番号を確認してください。")

    if normalized_chassis and any(
        normalize_vehicle_operation_plate(
            vehicle.chassis_number
        ) == normalized_chassis
        for vehicle in vehicles
    ):
        raise UploadValidationError(
            "同じ車台番号の車両が登録済みです。登録済み車両から選択してください。"
        )

    plate = normalize_vehicle_operation_plate(vehicle_number(parts))
    if plate_candidates.get(plate):
        raise UploadValidationError(
            "同じナンバーの車両が登録済みです。登録済み車両から選択してください。"
        )

    vehicle = Vehicle(
        company_code=company_code,
        chassis_number=source_chassis or None,
        deleted=False,
        **parts
    )
    db.session.add(vehicle)
    db.session.flush()
    return vehicle


@app.route("/master/vehicles/pending/<pending_id>/document-sources/<draft_id>")
def vehicle_import_pending_document_source(pending_id, draft_id):
    if not require_master_admin():
        raise NotFound()

    company_code = session.get("company_code")
    VehicleImportPending.query.filter_by(
        id=pending_id, company_code=company_code
    ).first_or_404()

    draft = VehicleDocumentImportDraft.query.join(
        VehicleImportPendingRecord,
        VehicleImportPendingRecord.document_draft_id == VehicleDocumentImportDraft.id
    ).filter(
        VehicleDocumentImportDraft.id == draft_id,
        VehicleDocumentImportDraft.company_code == company_code,
        VehicleImportPendingRecord.company_code == company_code,
        VehicleImportPendingRecord.pending_id == pending_id,
        VehicleImportPendingRecord.source_kind == VehicleDocumentImportDraft.document_type
    ).first_or_404()

    mimetype = {
        ".pdf": "application/pdf",
        ".png": "image/png",
        ".jpg": "image/jpeg",
        ".jpeg": "image/jpeg",
    }.get(os.path.splitext(draft.source_filename)[1].lower())
    if mimetype is None:
        raise NotFound()

    response = send_file(
        BytesIO(draft.source_file),
        mimetype=mimetype,
        download_name=draft.source_filename,
        as_attachment=False,
        conditional=False,
        etag=False,
        max_age=0
    )
    response.headers["X-Content-Type-Options"] = "nosniff"
    response.headers["Cache-Control"] = "private, no-store"
    return response


def get_vehicle_pending_maintenance_candidates(company_code, vehicle_id, payload):
    """作業日が一致する候補を返す。確定・更新・費用の統合は行わない。"""
    if (
        not company_code or isinstance(vehicle_id, bool)
        or not isinstance(vehicle_id, int) or not isinstance(payload, dict)
    ):
        raise UploadValidationError("会社・車両・請求書の情報を確認してください。")
    vehicle = Vehicle.query.filter_by(
        id=vehicle_id, company_code=company_code
    ).first()
    if vehicle is None:
        raise UploadValidationError("登録先の車両を確認できません。")

    dates = set()
    for field in ("record_date", "completion_date"):
        value = payload.get(field)
        if not value:
            continue
        if not isinstance(value, str):
            raise UploadValidationError("整備資料の作業日を確認してください。")
        try:
            parsed = datetime.strptime(value, "%Y-%m-%d")
            if parsed.strftime("%Y-%m-%d") != value:
                raise ValueError
        except ValueError:
            raise UploadValidationError("整備資料の作業日を確認してください。")
        dates.add(value)
    if not dates:
        return []

    candidates = []
    models = (
        ("maintenance", VehicleMaintenanceRecord, "entry_date"),
        ("inspection", VehiclePeriodicInspectionRecord, "inspection_date"),
    )
    for kind, model, date_field in models:
        rows = model.query.filter(
            model.company_code == company_code,
            model.vehicle_record_id == vehicle_id,
            or_(getattr(model, date_field).in_(dates),
                model.completion_date.in_(dates)),
        ).order_by(model.id).all()
        for record in rows:
            matched_dates = sorted(dates.intersection({
                getattr(record, date_field), record.completion_date
            }))
            candidates.append({
                "kind": kind,
                "record_id": record.id,
                "record_date": getattr(record, date_field) or "",
                "completion_date": record.completion_date or "",
                "content": record.content or "",
                "maintenance_company": (
                    record.maintenance_company if kind == "maintenance"
                    else record.inspection_company
                ) or "",
                "matched_dates": matched_dates,
                "has_invoice": kind == "maintenance" and bool(
                    record.invoice_number or record.invoice_date
                    or safe_json_dict(record.invoice_details_json).get("source")
                    or any(getattr(record, field) is not None for field in (
                        "labor_cost", "parts_cost", "other_cost",
                        "tax_amount", "total_cost"
                    ))
                ),
            })
    return candidates


def get_vehicle_pending_invoice_questions(pending_id, vehicle_id, company_code):
    """未反映の請求書ごとに、原本と整備候補を確認画面へ渡す。"""
    pending = VehicleImportPending.query.filter_by(
        id=pending_id, company_code=company_code, status="pending"
    ).first()
    if pending is None:
        raise UploadValidationError("登録待ちの情報を再確認してください。")

    questions = []
    items = VehicleImportPendingRecord.query.filter_by(
        pending_id=pending.id, company_code=company_code,
        source_kind="maintenance", status="pending"
    ).order_by(VehicleImportPendingRecord.id).all()

    for item in items:
        draft = VehicleDocumentImportDraft.query.filter_by(
            id=item.document_draft_id, company_code=company_code,
            document_type="maintenance", status="completed"
        ).first()
        if draft is None or hashlib.sha256(
            draft.source_file
        ).hexdigest() != draft.source_sha256:
            raise UploadValidationError("保存済みの原本を確認できません。")

        payload = safe_json_dict(item.payload_json)
        records = safe_json_dict(draft.preview_json).get("records")
        index = item.source_record_index
        if (
            not isinstance(records, list)
            or isinstance(index, bool) or not isinstance(index, int)
            or not 0 <= index < len(records)
            or records[index] != payload
            or payload.get("vehicle_record_id") is not None
        ):
            raise UploadValidationError("保存済み明細の一致を確認できません。")

        candidates = get_vehicle_pending_maintenance_candidates(
            company_code, vehicle_id, payload
        )
        if candidates:
            questions.append({
                "pending_record_id": item.id,
                "draft_id": draft.id,
                "filename": draft.source_filename,
                "record_index": index,
                "record_date": payload.get("record_date") or "",
                "completion_date": payload.get("completion_date") or "",
                "invoice_date": payload.get("invoice_date") or "",
                "invoice_number": payload.get("invoice_number") or "",
                "content": payload.get("content") or "",
                "total_cost": payload.get("total_cost"),
                "candidates": candidates,
            })
    return questions


def save_vehicle_maintenance_document(
    pending_record_id, vehicle_id, target_kind, target_id, company_code, username
):
    """原本と確認待ち情報を保存する。既存費用・部品の更新や確定はしない。"""
    if (
        not company_code or not username
        or company_code != session.get("company_code")
        or username != session.get("username")
        or type(vehicle_id) is not int or type(target_id) is not int
        or target_kind not in {"maintenance", "inspection"}
    ):
        raise UploadValidationError("資料の登録先を再確認してください。")

    company = Company.query.filter_by(
        company_code=company_code
    ).with_for_update().first()
    if company is None:
        raise UploadValidationError("会社情報を確認できません。")

    item = VehicleImportPendingRecord.query.filter_by(
        id=pending_record_id, company_code=company_code,
        source_kind="maintenance"
    ).first()
    if item is None:
        raise UploadValidationError("保存済みの請求書明細を確認できません。")

    draft = VehicleDocumentImportDraft.query.filter_by(
        id=item.document_draft_id, company_code=company_code,
        document_type="maintenance", status="completed"
    ).first()
    if draft is None or hashlib.sha256(
        draft.source_file
    ).hexdigest() != draft.source_sha256:
        raise UploadValidationError("保存済みの原本を確認できません。")

    payload = safe_json_dict(item.payload_json)
    records = safe_json_dict(draft.preview_json).get("records")
    index = item.source_record_index
    if (
        not isinstance(records, list) or type(index) is not int
        or not 0 <= index < len(records) or records[index] != payload
        or payload.get("vehicle_record_id") is not None
    ):
        raise UploadValidationError("保存済み明細の一致を確認できません。")

    target_model = (
        VehicleMaintenanceRecord if target_kind == "maintenance"
        else VehiclePeriodicInspectionRecord
    )
    target = target_model.query.filter_by(
        id=target_id, company_code=company_code, vehicle_record_id=vehicle_id
    ).with_for_update().first()
    vehicle = Vehicle.query.filter_by(
        id=vehicle_id, company_code=company_code
    ).first()
    if target is None or vehicle is None:
        raise UploadValidationError(
            "同じ会社・車両の整備または点検を選択してください。"
        )

    canonical_payload = json.dumps(
        payload, ensure_ascii=False, sort_keys=True, separators=(",", ":")
    )
    existing = VehicleMaintenanceDocument.query.filter_by(
        company_code=company_code, source_draft_id=draft.id,
        source_record_index=index
    ).first()
    target_fields = {
        "maintenance_record_id": target_id if target_kind == "maintenance" else None,
        "inspection_record_id": target_id if target_kind == "inspection" else None,
    }
    if existing is not None:
        if (
            existing.vehicle_record_id != vehicle_id
            or existing.pending_record_id != item.id
            or any(
                getattr(existing, key) != value
                for key, value in target_fields.items()
            )
            or safe_json_dict(existing.payload_json) != payload
        ):
            raise UploadValidationError(
                "この明細は別の登録先へ保存済みです。再確認してください。"
            )
        return existing

    if item.status != "pending":
        raise UploadValidationError("この明細は対応済みです。再確認してください。")

    if not any(
        row["kind"] == target_kind and row["record_id"] == target_id
        for row in get_vehicle_pending_maintenance_candidates(
            company_code, vehicle_id, payload
        )
    ):
        raise UploadValidationError("整備候補が変わりました。再確認してください。")

    document = VehicleMaintenanceDocument(
        company_code=company_code, vehicle_record_id=vehicle_id,
        source_draft_id=draft.id, source_record_index=index,
        pending_record_id=item.id, payload_json=canonical_payload,
        decision_json=json.dumps({
            "service_match": "same",
            "matched_by_username": username,
            "costs_applied": False,
            "parts_applied": False,
        }, ensure_ascii=False),
        financial_status="pending",
        parts_status="pending",
        created_by_username=username,
        **target_fields
    )
    db.session.add(document)
    db.session.flush()
    return document


def merge_vehicle_pending_invoice_record(target_id, invoice):
    """請求未登録の整備へ追加する。確定は呼出元のトランザクションで行う。"""
    if (
        not isinstance(invoice, VehicleMaintenanceRecord)
        or not inspect(invoice).transient
        or invoice.company_code != session.get("company_code")
        or isinstance(target_id, bool) or not isinstance(target_id, int)
    ):
        raise UploadValidationError("請求書の登録先を再確認してください。")

    candidates = get_vehicle_pending_maintenance_candidates(
        invoice.company_code, invoice.vehicle_record_id,
        {"record_date": invoice.entry_date,
         "completion_date": invoice.completion_date}
    )
    candidate = next((row for row in candidates if (
        row["kind"] == "maintenance" and row["record_id"] == target_id
    )), None)
    if candidate is None:
        raise UploadValidationError("同じ車両・作業日の整備を選択してください。")

    record = VehicleMaintenanceRecord.query.filter_by(
        id=target_id, company_code=invoice.company_code,
        vehicle_record_id=invoice.vehicle_record_id
    ).with_for_update().populate_existing().first()
    if record is None:
        raise UploadValidationError("登録先の整備記録を確認できません。")

    costs = ("labor_cost", "parts_cost", "other_cost", "tax_amount", "total_cost")
    details = safe_json_dict(record.invoice_details_json)
    if (
        record.invoice_number or record.invoice_date or details.get("source")
        or any(getattr(record, field) is not None for field in costs)
        or json.loads(record.line_items_json or "[]")
        or details.get("fees")
        or VehiclePartReplacement.query.filter_by(
            company_code=record.company_code,
            maintenance_record_id=record.id
        ).first() is not None
    ):
        raise UploadValidationError(
            "この整備には請求情報・費用・部品が登録済みです。上書きせず、内容を確認してください。"
        )

    invoice_details = safe_json_dict(invoice.invoice_details_json)
    if not isinstance(invoice_details.get("source"), dict):
        raise UploadValidationError("請求書の原本情報を確認できません。")

    record.invoice_details_json = json.dumps({
        **details, **invoice_details,
        "before_invoice_attachment": details,
        "before_invoice_attachment_json": record.invoice_details_json,
        "attached_invoice_content": invoice.content,
        "attached_invoice_notes": invoice.notes,
    }, ensure_ascii=False)

    for field in (*costs, "invoice_number", "invoice_date", "line_items_json"):
        setattr(record, field, getattr(invoice, field))

    for field in ("entry_date", "completion_date", "mileage", "maintenance_company"):
        if getattr(record, field) is None or getattr(record, field) == "":
            setattr(record, field, getattr(invoice, field))

    record.updated_by_username = session.get("username")
    record.updated_at = datetime.now(ZoneInfo("Asia/Tokyo")).isoformat(
        timespec="seconds"
    )
    return record


def apply_vehicle_import_pending_documents(
    pending_id, vehicle_id, company_code, username, *, invoice_choices=None
):
    return apply_vehicle_import_pending_records(
        pending_id, vehicle_id, company_code, username,
        invoice_choices=invoice_choices,
        allowed_kinds={"inspection", "maintenance", "driving_report"},
    )


def apply_vehicle_import_pending_operations(
    pending_id, vehicle_id, company_code, username
):
    return apply_vehicle_import_pending_records(
        pending_id, vehicle_id, company_code, username,
        allowed_kinds={"operation"},
    )


def apply_vehicle_import_pending_records(
    pending_id, vehicle_id, company_code, username, *, invoice_choices=None,
    allowed_kinds=None,
):
    """Claim once and apply every source in the caller's single transaction."""
    if (
        not company_code or not username
        or isinstance(vehicle_id, bool) or not isinstance(vehicle_id, int)
    ):
        raise UploadValidationError("会社・利用者・登録先を確認してください。")

    vehicle = Vehicle.query.filter_by(
        id=vehicle_id, company_code=company_code
    ).first()
    if vehicle is None:
        raise UploadValidationError("登録先の車両を確認できません。")

    company = Company.query.filter_by(
        company_code=company_code
    ).with_for_update().first()
    if company is None:
        raise UploadValidationError("会社情報を確認できません。")

    claimed = VehicleImportPending.query.filter_by(
        id=pending_id, company_code=company_code, status="pending"
    ).update({"status": "processing"}, synchronize_session=False)
    if claimed != 1:
        raise UploadValidationError("この登録待ちは対応済みか、処理中です。")

    items = VehicleImportPendingRecord.query.filter_by(
        pending_id=pending_id, company_code=company_code, status="pending"
    ).order_by(VehicleImportPendingRecord.id).all()
    supported = {"operation", "inspection", "maintenance", "driving_report"}
    kinds = {item.source_kind for item in items}
    if not items or not kinds <= (
        supported if allowed_kinds is None else supported & allowed_kinds
    ):
        raise UploadValidationError("登録待ちの資料構成を再確認してください。")

    result = {"added_count": 0, "linked_count": 0, "review_pending_count": 0}
    operations = [item for item in items if item.source_kind == "operation"]
    documents = [item for item in items if item.source_kind != "operation"]
    if operations:
        applied = _apply_vehicle_pending_operation_records(
            operations, vehicle_id, company_code, username
        )
        for key, value in applied.items():
            result[key] += value
    if documents:
        applied = _apply_vehicle_pending_document_records(
            documents, vehicle_id, company_code, username,
            invoice_choices=invoice_choices,
        )
        for key, value in applied.items():
            result[key] += value

    db.session.flush()
    pending = VehicleImportPending.query.filter_by(
        id=pending_id, company_code=company_code
    ).first()
    applied_ids = {
        row.vehicle_record_id
        for row in VehicleImportPendingRecord.query.filter_by(
            pending_id=pending_id, company_code=company_code, status="applied"
        ).all()
        if row.vehicle_record_id is not None
    }
    pending.status = "resolved"
    pending.resolved_vehicle_id = (
        next(iter(applied_ids)) if len(applied_ids) == 1 else None
    )
    pending.resolved_at = datetime.now(ZoneInfo("UTC"))
    pending.resolution_json = json.dumps({
        "vehicle_ids": sorted(applied_ids),
        "resolved_by_username": username,
    })
    db.session.flush()
    return result


def _apply_vehicle_pending_document_records(
    items, vehicle_id, company_code, username, *, invoice_choices=None
):
    maintenance_candidates = {
        item.id: get_vehicle_pending_maintenance_candidates(
            company_code, vehicle_id, safe_json_dict(item.payload_json)
        )
        for item in items if item.source_kind == "maintenance"
    }
    added_count = 0
    now = datetime.now(ZoneInfo("UTC"))
    for item in items:
        draft = VehicleDocumentImportDraft.query.filter_by(
            id=item.document_draft_id,
            company_code=company_code,
            document_type=item.source_kind,
            status="completed"
        ).first()
        if draft is None or hashlib.sha256(
            draft.source_file
        ).hexdigest() != draft.source_sha256:
            raise UploadValidationError("保存済みの原本を確認できません。")

        payload = safe_json_dict(item.payload_json)
        preview_records = safe_json_dict(draft.preview_json).get("records")
        index = item.source_record_index
        if (
            not isinstance(preview_records, list)
            or not 0 <= index < len(preview_records)
            or preview_records[index] != payload
            or payload.get("vehicle_record_id") is not None
        ):
            raise UploadValidationError("保存済み明細の一致を確認できません。")

        if item.source_kind == "maintenance":
            source_keys = maintenance_import_source_keys({
                "sha256": draft.source_sha256,
                "pages": payload.get("source_pages"),
                "record_index": index,
            })
            if source_keys & registered_maintenance_import_keys(
                company_code, exclude_pending_record_id=item.id
            ):
                raise UploadValidationError(
                    "同じ原本の請求書が登録済み、または他の登録待ちと重複しています。"
                )

        if item.source_kind == "inspection" and (draft.source_sha256, index) in registered_inspection_import_keys(
            company_code, exclude_pending_record_id=item.id
        ):
            raise UploadValidationError("同じ原本の点検記録がすでに登録されています。")
        values = {**payload, "vehicle_record_id": vehicle_id}
        record = build_vehicle_document_record(draft, index, values)
        document = None
        if item.source_kind == "maintenance":
            candidates = maintenance_candidates.get(item.id, [])
            choice = (invoice_choices or {}).get(item.id, "")
            if candidates and not choice:
                raise UploadValidationError("請求書と整備の対応を回答してください。")
            if choice and choice != "new":
                selected = next((row for row in candidates if (
                    choice == f"{row['kind']}:{row['record_id']}"
                )), None)
                if selected is None:
                    raise UploadValidationError(
                        "整備候補が変わりました。再確認してください。"
                    )
                document = save_vehicle_maintenance_document(
                    item.id, vehicle_id, selected["kind"], selected["record_id"],
                    company_code, username
                )

        if document is None:
            added_count += int(inspect(record).transient)
            db.session.add(record)
            db.session.flush()
            if item.source_kind == "maintenance":
                add_vehicle_maintenance_record_event(record, action="imported")
                save_vehicle_maintenance_replacement_parts(record)

        applied_result = {
            "record_id": record.id if document is None else None,
            "document_type": draft.document_type,
        }
        if document is not None:
            applied_result.update({
                "maintenance_document_id": document.id,
                "target_kind": selected["kind"],
                "target_record_id": selected["record_id"],
                "financial_status": document.financial_status,
                "parts_status": document.parts_status,
            })

        result = safe_json_dict(draft.result_json)
        registered = result.get("records", [])
        if not isinstance(registered, list) or any(
            not isinstance(row, dict) or row.get("record_index") == index
            for row in registered
        ):
            raise UploadValidationError("この明細の反映状況を再確認してください。")

        registered.append({
            **applied_result,
            "record_index": index,
            "vehicle_record_id": vehicle_id,
        })
        waiting = result.get("pending_records", [])
        if not isinstance(waiting, list) or not all(
            isinstance(row, dict) for row in waiting
        ):
            raise UploadValidationError("登録待ち明細を再確認してください。")

        waiting = [
            row for row in waiting
            if row.get("pending_record_id") != item.id
        ]
        draft.result_json = json.dumps({
            **result,
            "records": registered,
            "pending_records": waiting,
            "pending_count": len(waiting),
        }, ensure_ascii=False)

        item.status = "applied"
        item.vehicle_record_id = vehicle_id
        item.applied_at = now
        item.result_json = json.dumps(applied_result, ensure_ascii=False)

    db.session.flush()
    review_pending_count = VehicleMaintenanceDocument.query.filter(
        VehicleMaintenanceDocument.company_code == company_code,
        VehicleMaintenanceDocument.pending_record_id.in_([item.id for item in items]),
        VehicleMaintenanceDocument.financial_status == "pending",
    ).count()
    return {
        "added_count": added_count,
        "linked_count": len(items),
        "review_pending_count": review_pending_count,
    }


def _apply_vehicle_pending_operation_records(
    records, vehicle_id, company_code, username
):
    source_rows_by_draft = {}
    added_count = 0
    linked_count = 0
    now = datetime.now(ZoneInfo("UTC"))
    imported_at = now.astimezone(ZoneInfo("Asia/Tokyo")).strftime(
        "%Y-%m-%d %H:%M:%S"
    )

    for item in records:
        draft = VehicleOperationImportDraft.query.filter_by(
            id=item.operation_draft_id, company_code=company_code
        ).first()
        if draft is None:
            raise UploadValidationError("取込原本を確認できません。")

        if draft.id not in source_rows_by_draft:
            source_rows_by_draft[draft.id] = {
                row["line_number"]: row["source_row"]
                for row in read_vehicle_operation_csv(draft.source_file)
            }
        source_row = source_rows_by_draft[draft.id].get(
            item.source_record_index
        )
        if source_row is None:
            raise UploadValidationError("原本の対象行を確認できません。")

        payload = safe_json_dict(item.payload_json)
        values = parse_vehicle_operation_csv_row(
            source_row, item.source_record_index
        )
        if json.loads(json.dumps(values, default=str)) != payload:
            raise UploadValidationError("保存データと原本の内容が一致しません。")

        source_code = str(values.get("source_vehicle_code") or "").strip()
        source_number = normalize_vehicle_operation_plate(
            values.get("source_vehicle_number")
        )
        if source_code and source_number:
            mapping = VehicleOperationVehicleMapping.query.filter_by(
                company_code=company_code,
                source_vehicle_code=source_code,
                source_vehicle_number=source_number
            ).with_for_update().first()

            if mapping is not None and mapping.vehicle_record_id != vehicle_id:
                raise UploadValidationError(
                    "この車両コード・ナンバーは別の車両に対応付けられています。登録先を再確認してください。"
                )

            if mapping is None:
                mapping = VehicleOperationVehicleMapping(
                    company_code=company_code,
                    source_vehicle_code=source_code,
                    source_vehicle_number=source_number,
                    vehicle_record_id=vehicle_id,
                    confirmed_by_username=username,
                    confirmed_at=now
                )
                db.session.add(mapping)
            else:
                mapping.confirmed_by_username = username
                mapping.confirmed_at = now

        operation = VehicleOperationRecord.query.filter_by(
            company_code=company_code,
            report_number=values["report_number"]
        ).first()
        if operation is not None:
            if operation.vehicle_record_id != vehicle_id or any(
                getattr(operation, key) != value
                for key, value in values.items()
            ):
                raise UploadValidationError(
                    "同じ日報番号の登録済み実績と内容・車両が異なります。"
                )
        else:
            operation = VehicleOperationRecord(
                company_code=company_code,
                vehicle_record_id=vehicle_id,
                source_filename=draft.source_filename,
                imported_by_username=username,
                imported_at=imported_at,
                **values
            )
            db.session.add(operation)
            db.session.flush()
            added_count += 1

        item.status = "applied"
        item.vehicle_record_id = vehicle_id
        item.applied_at = now
        item.result_json = json.dumps({
            "operation_record_id": operation.id
        })
        original_ids = get_vehicle_operation_imported_vehicle_ids(draft)
        original_ids.add(vehicle_id)
        draft.result_json = json.dumps({
            **safe_json_dict(draft.result_json),
            "imported_vehicle_ids": sorted(original_ids),
        })
        linked_count += 1

    return {"added_count": added_count, "linked_count": linked_count}


def vehicle_import_pending_query(company_code):
    pending_record_exists = db.session.query(
        VehicleImportPendingRecord.id
    ).filter(
        VehicleImportPendingRecord.pending_id == VehicleImportPending.id,
        VehicleImportPendingRecord.company_code == company_code,
        VehicleImportPendingRecord.status == "pending"
    ).exists()

    return VehicleImportPending.query.filter(
        VehicleImportPending.company_code == company_code,
        VehicleImportPending.status == "pending",
        pending_record_exists
    )


def render_vehicle_list(template_name):
    keyword = request.args.get("keyword", "").strip()
    office = request.args.get("office", "").strip()
    vehicle_type = request.args.get("vehicle_type", "").strip()
    status = request.args.get("status", "").strip()
    manufacturer = request.args.get("manufacturer", "").strip()
    model_code = request.args.get("model_code", "").strip()

    if (
        len(keyword) > 100
        or len(office) > 100
        or len(vehicle_type) > 100
        or len(status) > 50
        or len(manufacturer) > 100
        or len(model_code) > 100
    ):
        return "検索条件が長すぎます。", 400

    if status not in {"", "active", "inactive"}:
        return "状態が不正です。", 400

    company_code = session.get("company_code")

    if office:
        valid_office = Office.query.filter_by(
            company_code=company_code,
            name=office
        ).first()

        if not valid_office:
            return "営業所が不正です。", 400

    if vehicle_type:
        valid_vehicle_type = VehicleType.query.filter_by(
            company_code=company_code,
            name=vehicle_type
        ).first()

        if not valid_vehicle_type:
            return "車種が不正です。", 400

    if manufacturer:
        valid_manufacturer = Vehicle.query.filter_by(
            company_code=company_code,
            manufacturer=manufacturer
        ).first()

        if not valid_manufacturer:
            return "メーカーが不正です。", 400

    if model_code:
        valid_model_code = Vehicle.query.filter_by(
            company_code=company_code,
            model_code=model_code
        ).first()

        if not valid_model_code:
            return "型式が不正です。", 400
        
    query = Vehicle.query.filter_by(
        company_code=company_code
    )

    plate_number_search = request.args.get(
        "plate_number_search", ""
    ).strip()
    chassis_number_search = request.args.get(
        "chassis_number_search", ""
    ).strip()

    search_errors = []

    if len(plate_number_search) > 100:
        search_errors.append((
            "車番の検索条件は100文字以内で入力してください。",
            "vehicle_search_plate_number"
        ))

    if len(chassis_number_search) > 100:
        search_errors.append((
            "車台番号の検索条件は100文字以内で入力してください。",
            "vehicle_search_chassis_number"
        ))

    if search_errors:
        return return_form_errors(search_errors)

    if plate_number_search:
        normalized_plate_number = "".join(
            plate_number_search.split()
        ).replace("-", "").replace("－", "")

        if normalized_plate_number:
            plate_number_expression = (
                db.func.coalesce(Vehicle.plate_area, "")
                + db.func.coalesce(Vehicle.plate_class, "")
                + db.func.coalesce(Vehicle.plate_kana, "")
                + db.func.coalesce(Vehicle.plate_number, "")
            )

            for separator in (" ", "　", "-", "－"):
                plate_number_expression = db.func.replace(
                    plate_number_expression,
                    separator,
                    ""
                )

            query = query.filter(
                plate_number_expression.ilike(
                    f"%{normalized_plate_number}%"
                )
            )

    if chassis_number_search:
        query = query.filter(
            Vehicle.chassis_number.ilike(
                f"%{chassis_number_search}%"
            )
        )

    # キーワード検索
    if keyword:

        keyword_like = f"%{keyword}%"

        query = query.filter(
            db.or_(
                Vehicle.plate_area.ilike(keyword_like),
                Vehicle.plate_class.ilike(keyword_like),
                Vehicle.plate_kana.ilike(keyword_like),
                Vehicle.plate_number.ilike(keyword_like),
                Vehicle.chassis_number.ilike(keyword_like),
                Vehicle.model_code.ilike(keyword_like),
                Vehicle.manufacturer.ilike(keyword_like),
                Vehicle.body_type.ilike(keyword_like),
            )
        )


    # 有効・無効
    if status == "active":
        query = query.filter(
            Vehicle.deleted == False
        )

    elif status == "inactive":
        query = query.filter(
            Vehicle.deleted == True
        )


    # メーカー・車名
    if manufacturer:
        query = query.filter(
            Vehicle.manufacturer == manufacturer
        )


    # 型式
    if model_code:
        query = query.filter(
            Vehicle.model_code == model_code
        )


    # 営業所
    if office:
        query = query.filter(
            Vehicle.office == office
        )


    # 車種
    if vehicle_type:
        query = query.filter(
            Vehicle.type == vehicle_type
        )


    # メーカー候補
    manufacturers = [
        item[0]
        for item in db.session.query(Vehicle.manufacturer)
        .filter(
            Vehicle.company_code == session.get("company_code"),
            Vehicle.manufacturer.isnot(None),
            Vehicle.manufacturer != ""
        )
        .distinct()
        .order_by(Vehicle.manufacturer)
        .all()
    ]


    # 型式候補
    model_codes = [
        item[0]
        for item in db.session.query(Vehicle.model_code)
        .filter(
            Vehicle.company_code == session.get("company_code"),
            Vehicle.model_code.isnot(None),
            Vehicle.model_code != ""
        )
        .distinct()
        .order_by(Vehicle.model_code)
        .all()
    ]


    # ページ分割
    page = request.args.get("page", 1, type=int)
    per_page = 10

    total_count = query.count()

    total_pages = max(
        1,
        (total_count + per_page - 1) // per_page
    )

    if page < 1:
        page = 1

    if page > total_pages:
        page = total_pages


    vehicle_records = (
        query
        .order_by(Vehicle.id.asc())
        .offset((page - 1) * per_page)
        .limit(per_page)
        .all()
    )


    filtered_vehicles = []

    for vehicle in vehicle_records:

        item = {
            "index": vehicle.id,
            "id": vehicle.id,
            "company_code": vehicle.company_code,
            "vehicle_record_id": vehicle.id,
            "deleted": vehicle.deleted,

            "plate_area": vehicle.plate_area,
            "plate_class": vehicle.plate_class,
            "plate_kana": vehicle.plate_kana,
            "plate_number": vehicle.plate_number,

            "chassis_number": vehicle.chassis_number,
            "model_code": vehicle.model_code,
            "first_registration_date": vehicle.first_registration_date,
            "manufacturer": vehicle.manufacturer,
            "body_type": vehicle.body_type,

            "gross_vehicle_weight": vehicle.gross_vehicle_weight,
            "max_payload": vehicle.max_payload,

            "type": vehicle.type,
            "office": vehicle.office,
            "inspection_expiry": vehicle.inspection_expiry,
        }

        item["number"] = vehicle_number(item)

        if template_name == "vehicle_master.html":
            item["open_defect_count"] = len(
                get_vehicle_open_inspection_defects(
                    company_code,
                    vehicle.id
                )
            )

        filtered_vehicles.append(item)

    company = Company.query.filter_by(
        company_code=session.get("company_code")
    ).first()

    vehicle_limit = 0

    vehicle_count = Vehicle.query.filter_by(
        company_code=session.get("company_code"),
        deleted=False
    ).count()

    remaining_vehicles = 0

    if company:
        vehicle_limit = company.vehicle_limit
        remaining_vehicles = vehicle_limit - vehicle_count

    return render_template(
        template_name,
        vehicles=filtered_vehicles,
        offices=offices_for_current_company(),
        vehicle_types=vehicle_types_for_current_company(),
        keyword=keyword,
        office=office,
        vehicle_type=vehicle_type,
        status=status,
        manufacturer=manufacturer,
        model_code=model_code,

        manufacturers=manufacturers,
        model_codes=model_codes,

        vehicle_limit=vehicle_limit,
        vehicle_count=vehicle_count,
        remaining_vehicles=remaining_vehicles,
        pending_vehicle_count=vehicle_import_pending_query(
            company_code
        ).count(),

        page=page,
        total_pages=total_pages,
        total_count=total_count,
    )

@app.route("/master/vehicles/import/master", methods=["POST"])
@limiter.limit("10 per minute", methods=["POST"])
def register_vehicle_import_master():
    company_code = session.get("company_code")

    if not company_code or not require_master_admin():
        return return_form_errors([
            ("管理者権限が必要です。", "")
        ], status_code=403)

    master_kind = request.form.get("master_kind", "").strip()
    name = request.form.get("name", "").strip()

    master_models = {
        "office": (Office, "営業所"),
        "vehicle_type": (VehicleType, "車種"),
    }

    if master_kind not in master_models:
        return return_form_errors([
            ("登録するマスタの種類を確認してください。", "")
        ])

    model, label = master_models[master_kind]

    if not name:
        return return_form_errors([
            (f"{label}名を入力してください。", "name")
        ])

    if len(name) > 100:
        return return_form_errors([
            (f"{label}名は100文字以内で入力してください。", "name")
        ])

    existing = model.query.filter_by(
        company_code=company_code,
        name=name
    ).first()

    if existing:
        return return_form_errors([
            (
                f"{label}「{name}」はすでに登録されています。"
                "既存マスタへの割り当てを選択してください。",
                "name"
            )
        ], status_code=409)

    if request.headers.get("X-DKSS-Validation-Only") == "1":
        return jsonify({"ok": True})

    if request.form.get("confirmed") != "1":
        return return_form_errors([
            ("新規登録する内容を確認してください。", "")
        ])

    master = model(
        company_code=company_code,
        name=name
    )

    try:
        db.session.add(master)
        db.session.commit()
    except SQLAlchemyError:
        db.session.rollback()
        app.logger.exception("車両Excel取込のマスタ登録に失敗しました。")
        return return_form_errors([
            (
                f"{label}を登録できませんでした。"
                "入力内容を保持したまま、もう一度お試しください。",
                "name"
            )
        ], status_code=500)

    return jsonify({
        "ok": True,
        "master_kind": master_kind,
        "master": {
            "id": master.id,
            "name": master.name,
        },
    })


@app.route("/master/vehicles/import", methods=["GET", "POST"])
@limiter.limit("10 per minute", methods=["POST"])
def import_vehicles():

    company_code = session.get("company_code")

    if request.method == "GET" and request.args.get("complete") == "1":
        result = session.get("vehicle_import_complete")
        if isinstance(result, dict):
            return render_template("vehicle_import_complete.html", **result)

    if request.method == "POST":

        excel_file = request.files.get("excel_file")

        if not excel_file or not excel_file.filename:
            return return_form_errors([
                (
                    "Excelファイルを選択してください。",
                    "excel_file"
                )
            ])

        if not excel_file.filename.lower().endswith(".xlsx"):
            return return_form_errors([
                (
                    "xlsx形式のExcelファイルを選択してください。",
                    "excel_file"
                )
            ])

        if not is_valid_uploaded_file(
            excel_file,
            ".xlsx"
        ):
            return return_form_errors([
                (
                    "Excelファイルの内容が不正です。",
                    "excel_file"
                )
            ])

        try:
            workbook = load_workbook(
                excel_file,
                data_only=True
            )
        except Exception:
            return return_form_errors([
                (
                    "Excelファイルを読み込めませんでした。",
                    "excel_file"
                )
            ])

        sheet = workbook.active

        if sheet.max_row > 5000:
            return return_form_errors([
                (
                    "一度に読み込めるExcelは5000行までです。",
                    "excel_file"
                )
            ])

        if sheet.max_column > 200:
            return return_form_errors([
                (
                    "一度に読み込めるExcelは200列までです。",
                    "excel_file"
                )
            ])

        header_row = None

        for row in sheet.iter_rows():
            values = [cell.value for cell in row]

            if (
                "ID" in values
                and "車両番号" in values
                and "車体番号" in values
                and "車番" in values
            ):
                header_row = row[0].row
                break

        if header_row is None:
            return return_form_errors([
                (
                    "車両台帳の見出し行が見つかりませんでした。",
                    "excel_file"
                )
            ])

        headers = [
            cell.value
            for cell in sheet[header_row]
        ]

        header_map = {
            name: index
            for index, name in enumerate(headers)
            if name is not None
        }
        required_headers = [
            "車種コード",
            "車番・地域名",
            "車番・分類",
            "車番・ひらがな",
            "車番",
            "車両総重量",
            "車体番号",
            "車体型式",
            "初年度車検",
            "車検期間終了日",
            "車両メーカー",
            "車両形状",
            "最大積載量",
        ]

        missing_headers = [
            header
            for header in required_headers
            if header not in header_map
        ]

        if missing_headers:
            return return_form_errors([
                (
                    "Excelに必要な見出しがありません："
                    + "、".join(missing_headers),
                    "excel_file"
                )
            ])

        def normalize_excel_date(value):
            if value in (None, ""):
                return ""

            if hasattr(value, "strftime"):
                return value.strftime("%Y-%m-%d")

            return str(value).strip()
        vehicles_data = []

        for data_row in range(header_row + 1, sheet.max_row + 1):

            row_values = [
                cell.value
                for cell in sheet[data_row]
            ]

            # 空行は読み飛ばす
            if not any(value is not None for value in row_values):
                continue

            plate_number = row_values[header_map["車番"]]
            chassis_number = row_values[header_map["車体番号"]]



            vehicle_data = {
                "excel_row": data_row,

                "office": (
                    str(
                        row_values[header_map["営業所"]] or ""
                    ).strip()
                    if "営業所" in header_map
                    else ""
                ),

                "active_status": (
                    str(
                        row_values[header_map["有効／無効"]] or ""
                    ).strip()
                    if "有効／無効" in header_map
                    else ""
                ),

                "vehicle_type_code": str(
                    row_values[header_map["車種コード"]] or ""
                ).strip(),

                "plate_area": row_values[header_map["車番・地域名"]],
                "plate_class": row_values[header_map["車番・分類"]],
                "plate_kana": row_values[header_map["車番・ひらがな"]],
                "plate_number": plate_number,

                "gross_vehicle_weight": row_values[header_map["車両総重量"]],
                "chassis_number": chassis_number,
                "model_code": row_values[header_map["車体型式"]],

                "first_registration_date": normalize_excel_date(
                    row_values[header_map["初年度車検"]]
                ),
                "inspection_expiry": normalize_excel_date(
                    row_values[header_map["車検期間終了日"]]
                ),

                "vehicle_name_raw": row_values[header_map["車両メーカー"]],
                "body_type_raw": row_values[header_map["車両形状"]],

                "vehicle_name": row_values[header_map["車両メーカー"]],
                "body_type": row_values[header_map["車両形状"]],

                "max_payload": row_values[header_map["最大積載量"]],
            }

            vehicles_data.append(vehicle_data)

        valid_import_offices = {
            office.name
            for office in Office.query.filter_by(
                company_code=session.get("company_code")
            ).all()
        }

        for vehicle in vehicles_data:
            office = vehicle.get("office", "")
            active_status = vehicle.get("active_status", "")
            excel_row = vehicle.get("excel_row")

            if office and office not in valid_import_offices:
                return return_form_errors([
                    (
                        f"{excel_row}行目の営業所「{office}」は"
                        "営業所マスタに登録されていません。",
                        "excel_file"
                    )
                ])

            if active_status not in {"", "有効", "無効"}:
                return return_form_errors([
                    (
                        f"{excel_row}行目の有効／無効は"
                        "「有効」または「無効」で入力してください。",
                        "excel_file"
                    )
                ])

        def clean_preview_text(value):
            return str(
                "" if value is None else value
            ).strip()

        def preview_int(value):
            cleaned_value = clean_preview_text(
                value
            ).replace(",", "")

            if not cleaned_value:
                return None

            try:
                return int(float(cleaned_value))
            except (TypeError, ValueError):
                return None

        incoming_chassis_numbers = {
            clean_preview_text(
                vehicle.get("chassis_number")
            )
            for vehicle in vehicles_data
            if clean_preview_text(
                vehicle.get("chassis_number")
            )
        }


        existing_preview_records = []

        if incoming_chassis_numbers:
            existing_preview_records.extend(
                Vehicle.query.filter(
                    Vehicle.company_code
                    == session.get("company_code"),
                    db.func.trim(
                        Vehicle.chassis_number
                    ).in_(incoming_chassis_numbers)
                ).all()
            )

        existing_preview_by_chassis = {}

        for existing_vehicle in existing_preview_records:

            existing_chassis = clean_preview_text(
                existing_vehicle.chassis_number
            )

            if existing_chassis:
                existing_preview_by_chassis[
                    existing_chassis
                ] = existing_vehicle

        # この会社で過去に保存した
        # Excel車種コード → 車種名 の対応を取得
        vehicle_type_mappings = VehicleTypeImportMapping.query.filter_by(
            company_code=session.get("company_code")
        ).all()

        valid_vehicle_type_names = {
            vehicle_type.name
            for vehicle_type in VehicleType.query.filter_by(
                company_code=session.get("company_code")
            ).all()
        }

        vehicle_type_mapping_dict = {
            mapping.excel_value: mapping.vehicle_type_name
            for mapping in vehicle_type_mappings
            if mapping.vehicle_type_name in valid_vehicle_type_names
        }

        for vehicle in vehicles_data:
            excel_vehicle_type = str(
                vehicle.get("vehicle_type_code", "") or ""
            ).strip()

            mapped_vehicle_type = vehicle_type_mapping_dict.get(
                excel_vehicle_type,
                ""
            )

            if (
                not mapped_vehicle_type
                and excel_vehicle_type in valid_vehicle_type_names
            ):
                mapped_vehicle_type = excel_vehicle_type

            vehicle["mapped_vehicle_type"] = mapped_vehicle_type
            
        processed_import_keys = set()

        for vehicle in vehicles_data:

            chassis_number = clean_preview_text(
                vehicle.get("chassis_number")
            )

            if not chassis_number:
                return return_form_errors([
                    (
                        f"{vehicle.get('excel_row')}行目の車台番号を入力してください。",
                        "excel_file"
                    )
                ])

            import_key = (
                "chassis",
                chassis_number
            )

            existing_vehicle = (
                existing_preview_by_chassis.get(
                    chassis_number
                )
            )

            vehicle["recommended_update_id"] = None

            if not existing_vehicle:
                candidates = get_vehicle_registration_plate_conflicts(
                    company_code,
                    vehicle.get("plate_area"),
                    vehicle.get("plate_class"),
                    vehicle.get("plate_kana"),
                    vehicle.get("plate_number"),
                    chassis_number,
                )
                complete_chassis = normalize_vehicle_operation_plate(
                    chassis_number
                )
                correction_candidates = []

                for candidate in candidates:
                    shortened_chassis = normalize_vehicle_operation_plate(
                        candidate["chassis_number"]
                    )

                    if (
                        shortened_chassis
                        and len(shortened_chassis) < len(complete_chassis)
                        and complete_chassis.startswith(shortened_chassis)
                        and clean_preview_text(candidate["chassis_number"])
                        not in incoming_chassis_numbers
                    ):
                        correction_candidates.append(candidate)

                if len(correction_candidates) == 1:
                    vehicle["recommended_update_id"] = (
                        correction_candidates[0]["id"]
                    )
                    existing_vehicle = Vehicle.query.filter_by(
                        id=vehicle["recommended_update_id"],
                        company_code=company_code,
                    ).first()

            is_excel_duplicate = (
                import_key in processed_import_keys
            )

            if existing_vehicle:

                if not clean_preview_text(
                    vehicle.get("mapped_vehicle_type")
                ):
                    existing_vehicle_type = clean_preview_text(
                        existing_vehicle.type
                    )

                    if (
                        existing_vehicle_type
                        in valid_vehicle_type_names
                    ):
                        vehicle["mapped_vehicle_type"] = (
                            existing_vehicle_type
                        )

                if not vehicle.get("active_status"):
                    vehicle["active_status"] = (
                        "無効" if existing_vehicle.deleted else "有効"
                    )

                target_deleted = (
                    vehicle["active_status"] == "無効"
                )

                vehicle["reactivate"] = (
                    existing_vehicle.deleted and not target_deleted
                )

                vehicle["state_changed"] = (
                    bool(existing_vehicle.deleted) != target_deleted
                )

                if not vehicle.get("office"):
                    vehicle["office"] = (
                        existing_vehicle.office or ""
                    )

                update_values = {
                    "plate_area": clean_preview_text(
                        vehicle.get("plate_area")
                    ),
                    "plate_class": clean_preview_text(
                        vehicle.get("plate_class")
                    ),
                    "plate_kana": clean_preview_text(
                        vehicle.get("plate_kana")
                    ),
                    "plate_number": clean_preview_text(
                        vehicle.get("plate_number")
                    ),
                    "gross_vehicle_weight": preview_int(
                        vehicle.get(
                            "gross_vehicle_weight"
                        )
                    ),
                    "model_code": clean_preview_text(
                        vehicle.get("model_code")
                    ),
                    "first_registration_date":
                        clean_preview_text(
                            vehicle.get(
                                "first_registration_date"
                            )
                        ),
                    "inspection_expiry":
                        clean_preview_text(
                            vehicle.get(
                                "inspection_expiry"
                            )
                        ),
                    "manufacturer": clean_preview_text(
                        vehicle.get("vehicle_name")
                    ),
                    "body_type": clean_preview_text(
                        vehicle.get("body_type")
                    ),
                    "max_payload": preview_int(
                        vehicle.get("max_payload")
                    ),
                }

                vehicle_changed = (
                    bool(vehicle.get("recommended_update_id"))
                    or bool(vehicle.get("state_changed"))
                    or clean_preview_text(existing_vehicle.office)
                    != clean_preview_text(vehicle.get("office"))
                )

                for field_name, new_value in (
                    update_values.items()
                ):
                    # Excelが空欄なら既存値を維持
                    if new_value in ("", None):
                        continue

                    old_value = getattr(
                        existing_vehicle,
                        field_name
                    )

                    if isinstance(new_value, int):
                        try:
                            old_value = int(old_value)
                        except (TypeError, ValueError):
                            old_value = None
                    else:
                        old_value = clean_preview_text(
                            old_value
                        )

                    if old_value != new_value:
                        vehicle_changed = True
                        break

                mapped_vehicle_type = clean_preview_text(
                    vehicle.get("mapped_vehicle_type")
                )

                if (
                    mapped_vehicle_type
                    and clean_preview_text(existing_vehicle.type)
                    != mapped_vehicle_type
                ):
                    vehicle_changed = True
                        
                if vehicle_changed:
                    vehicle["import_status"] = "更新"
                else:
                    vehicle["import_status"] = (
                        "変更なし"
                    )

            else:
                vehicle["import_status"] = "新規"

                if not vehicle.get("active_status"):
                    vehicle["active_status"] = "有効"

            vehicle["base_import_status"] = (
                vehicle["import_status"]
            )

            if is_excel_duplicate:
                vehicle["import_status"] = (
                    "Excel内重複"
                )
            processed_import_keys.add(import_key)



        company_vehicles = Vehicle.query.filter_by(
            company_code=company_code
        ).order_by(Vehicle.id.asc()).all()

        excel_plate_rows = {}

        for row_number, vehicle_data in enumerate(
            vehicles_data, start=1
        ):
            plate_key = tuple(
                normalize_vehicle_operation_plate(
                    vehicle_data.get(field_name)
                )
                for field_name in (
                    "plate_area",
                    "plate_class",
                    "plate_kana",
                    "plate_number",
                )
            )

            if all(plate_key):
                excel_plate_rows.setdefault(
                    plate_key, []
                ).append((
                    row_number,
                    str(
                        vehicle_data.get("chassis_number") or ""
                    ).strip(),
                ))

        for row_number, vehicle_data in enumerate(
            vehicles_data, start=1
        ):
            chassis_number = str(
                vehicle_data.get("chassis_number") or ""
            ).strip()

            vehicle_data["plate_conflicts"] = (
                get_vehicle_registration_plate_conflicts(
                    company_code,
                    vehicle_data.get("plate_area"),
                    vehicle_data.get("plate_class"),
                    vehicle_data.get("plate_kana"),
                    vehicle_data.get("plate_number"),
                    chassis_number,
                    existing_vehicles=company_vehicles,
                )
            )

            plate_key = tuple(
                normalize_vehicle_operation_plate(
                    vehicle_data.get(field_name)
                )
                for field_name in (
                    "plate_area",
                    "plate_class",
                    "plate_kana",
                    "plate_number",
                )
            )

            vehicle_data["excel_plate_conflicts"] = [
                {
                    "row_number": other_row,
                    "chassis_number": other_chassis,
                }
                for other_row, other_chassis in (
                    excel_plate_rows.get(plate_key, [])
                )
                if other_row != row_number
                and other_chassis
                and chassis_number
                and other_chassis != chassis_number
            ]

        return render_template(
            "vehicle_import_preview.html",
            vehicles=vehicles_data,
            offices=offices_for_current_company(),
            vehicle_types=vehicle_types_for_current_company(),
            vehicle_type_mapping_dict=vehicle_type_mapping_dict,
            vehicle_plate_candidates=[
                {
                    "id": vehicle.id,
                    "chassis_number": str(
                        vehicle.chassis_number or ""
                    ).strip(),
                    "plate_area": vehicle.plate_area or "",
                    "plate_class": vehicle.plate_class or "",
                    "plate_kana": vehicle.plate_kana or "",
                    "plate_number": vehicle.plate_number or "",
                    "office": vehicle.office or "",
                    "inactive": bool(vehicle.deleted),
                    "vehicle_type": vehicle.type or "",
                    "gross_vehicle_weight": vehicle.gross_vehicle_weight,
                    "model_code": vehicle.model_code or "",
                    "first_registration_date": vehicle.first_registration_date or "",
                    "inspection_expiry": vehicle.inspection_expiry or "",
                    "vehicle_name": vehicle.manufacturer or "",
                    "body_type": vehicle.body_type or "",
                    "max_payload": vehicle.max_payload,
                }
                for vehicle in company_vehicles
            ],
        )
    
    return render_template(
        "vehicle_import.html"
    )

@app.route("/master/vehicles/import/confirm", methods=["POST"])
@limiter.limit("10 per minute")
def confirm_vehicle_import():

    company_code = session.get("company_code")

    vehicle_type_codes = request.form.getlist(
        "vehicle_type_code"
    )

    vehicle_types = request.form.getlist(
        "vehicle_type"
    )

    valid_vehicle_type_names = {
        vehicle_type.name
        for vehicle_type in VehicleType.query.filter_by(
            company_code=company_code
        ).all()
    }

    vehicle_types = [
        str(value or "").strip()
        for value in vehicle_types
    ]

    for i, vehicle_type in enumerate(vehicle_types):
        if vehicle_type and vehicle_type not in valid_vehicle_type_names:
            return return_form_errors([
                (
                    f"{i + 1}件目の車種「{vehicle_type}」は"
                    "車種マスタに登録されていません。"
                    "既存の車種への割り当て、または新規登録を確認してください。",
                    "vehicle_type"
                )
            ])
    
    plate_areas = request.form.getlist("plate_area")
    plate_classes = request.form.getlist("plate_class")
    plate_kanas = request.form.getlist("plate_kana")
    plate_numbers = request.form.getlist("plate_number")

    gross_weights = request.form.getlist("gross_vehicle_weight")
    chassis_numbers = request.form.getlist("chassis_number")
    model_codes = request.form.getlist("model_code")

    first_registration_dates = request.form.getlist(
        "first_registration_date"
    )

    inspection_expiries = request.form.getlist(
        "inspection_expiry"
    )

    vehicle_names = request.form.getlist("vehicle_name")
    body_types = request.form.getlist("body_type")
    max_payloads = request.form.getlist("max_payload")

    offices = request.form.getlist("office")
    active_statuses = request.form.getlist("active_status")

    form_lists = [
        vehicle_type_codes,
        vehicle_types,
        plate_areas,
        plate_classes,
        plate_kanas,
        plate_numbers,
        gross_weights,
        chassis_numbers,
        model_codes,
        first_registration_dates,
        inspection_expiries,
        vehicle_names,
        body_types,
        max_payloads,
        offices,
        active_statuses,
    ]

    form_list_lengths = {
        len(values)
        for values in form_lists
    }

    if len(form_list_lengths) != 1:
        return return_form_errors([
            (
                "取込データの件数が一致しません。"
                "Excel取込画面からやり直してください。",
                ""
            )
        ])

    import_count = len(chassis_numbers)

    if import_count > 5000:
        return return_form_errors([
            (
                "一度に取り込める車両は5000件までです。",
                ""
            )
        ])

    if import_count == 0:
        return return_form_errors([
            (
                "取込対象の車両がありません。",
                ""
            )
        ])

    valid_import_offices = {
        office.name
        for office in Office.query.filter_by(
            company_code=company_code
        ).all()
    }

    offices = [
        str(value or "").strip()
        for value in offices
    ]

    target_deleted_values = []

    for i in range(import_count):
        office = offices[i]
        active_status = str(active_statuses[i] or "").strip()
        vehicle_type_code = str(vehicle_type_codes[i] or "").strip()

        if vehicle_type_code and not vehicle_types[i]:
            return return_form_errors([
                (
                    f"{i + 1}件目の車種コード「{vehicle_type_code}」の"
                    "割り当てが未解決です。"
                    "既存の車種への割り当て、または新規登録を確認してください。",
                    "vehicle_type"
                )
            ])

        if len(office) > 100:
            return return_form_errors([
                (
                    f"{i + 1}件目の営業所は100文字以内で入力してください。",
                    "office"
                )
            ])

        if office and office not in valid_import_offices:
            return return_form_errors([
                (
                    f"{i + 1}件目の営業所「{office}」は"
                    "営業所マスタに登録されていません。",
                    "office"
                )
            ])

        if active_status not in {"有効", "無効"}:
            return return_form_errors([
                (
                    f"{i + 1}件目の有効／無効を選択してください。",
                    "active_status"
                )
            ])

        target_deleted_values.append(active_status == "無効")

    company = Company.query.filter_by(
        company_code=company_code
    ).first()

    current_count = Vehicle.query.filter_by(
        company_code=company_code,
        deleted=False
    ).count()


    def normalize_import_text(value):
        return str(value or "").strip()

    import_chassis_numbers = {
        normalize_import_text(value)
        for value in chassis_numbers
        if normalize_import_text(value)
    }

    existing_vehicle_records = []

    if import_chassis_numbers:
        existing_vehicle_records.extend(
            Vehicle.query.filter(
                Vehicle.company_code == company_code,
                db.func.trim(
                    Vehicle.chassis_number
                ).in_(import_chassis_numbers)
            ).all()
        )

    existing_vehicles_by_chassis = {}

    for existing_vehicle in existing_vehicle_records:

        existing_chassis = normalize_import_text(
            existing_vehicle.chassis_number
        )

        if existing_chassis:
            existing_vehicles_by_chassis[
                existing_chassis
            ] = existing_vehicle

    company_vehicles = Vehicle.query.filter_by(
        company_code=company_code
    ).order_by(Vehicle.id.asc()).all()

    excel_plate_chassis = {}

    for i in range(import_count):
        plate_key = tuple(
            normalize_vehicle_operation_plate(value)
            for value in (
                plate_areas[i],
                plate_classes[i],
                plate_kanas[i],
                plate_numbers[i],
            )
        )
        if all(plate_key):
            excel_plate_chassis.setdefault(
                plate_key, set()
            ).add(normalize_import_text(chassis_numbers[i]))

    vehicle_chassis_corrections = {}
    correction_target_ids = set()
    checked_chassis_numbers = set()
    resolution_errors = []

    for i in range(import_count):
        chassis_number = normalize_import_text(
            chassis_numbers[i]
        )

        if not chassis_number:
            continue

        if chassis_number in checked_chassis_numbers:
            continue

        checked_chassis_numbers.add(chassis_number)

        field_name = f"vehicle_plate_resolution_{i}"
        choice = request.form.get(
            field_name, ""
        ).strip()

        existing_vehicle = existing_vehicles_by_chassis.get(
            chassis_number
        )

        conflicts = get_vehicle_registration_plate_conflicts(
            company_code,
            plate_areas[i],
            plate_classes[i],
            plate_kanas[i],
            plate_numbers[i],
            chassis_number,
            existing_vehicles=company_vehicles,
        )

        plate_key = tuple(
            normalize_vehicle_operation_plate(value)
            for value in (
                plate_areas[i],
                plate_classes[i],
                plate_kanas[i],
                plate_numbers[i],
            )
        )

        excel_conflict = any(
            other_chassis
            and other_chassis != chassis_number
            for other_chassis in (
                excel_plate_chassis.get(plate_key, set())
            )
        )

        if not conflicts and not excel_conflict:
            if choice.startswith("update:"):
                resolution_errors.append((
                    f"No.{i + 1}の車両情報が変更されています。"
                    "車台番号の訂正対象を確認してください。",
                    field_name,
                ))
            continue

        if excel_conflict:
            resolution_errors.append((
                f"No.{i + 1}はExcel内に同じナンバーで異なる"
                "車台番号の行があります。"
                "車台番号またはナンバープレートを確認・訂正してください。",
                field_name,
            ))
            continue

        if existing_vehicle:
            resolution_errors.append((
                f"No.{i + 1}は登録済み車両同士でナンバーが重複しています。"
                "既存車両の重複を解消してから取り込んでください。",
                field_name,
            ))
            continue

        allowed_choices = {}
        conflict_ids = {
            candidate["id"]
            for candidate in conflicts
        }

        for candidate in company_vehicles:
            if candidate.id in conflict_ids:
                allowed_choices[
                    f"update:{candidate.id}"
                ] = candidate

        if choice not in allowed_choices:
            resolution_errors.append((
                f"No.{i + 1}は同じナンバーで異なる"
                "車台番号の車両があります。"
                "登録・更新方法を選択してください。",
                field_name,
            ))
            continue

        if not choice.startswith("update:"):
            continue

        target_vehicle = allowed_choices[choice]
        old_chassis = normalize_import_text(
            target_vehicle.chassis_number
        )

        if (
            target_vehicle.id in correction_target_ids
            or old_chassis in import_chassis_numbers
        ):
            resolution_errors.append((
                f"No.{i + 1}の訂正対象車両は、"
                "今回のExcel内の別の行でも使用されています。"
                "取り込む車台番号を確認してください。",
                field_name,
            ))
            continue

        correction_target_ids.add(target_vehicle.id)
        vehicle_chassis_corrections[chassis_number] = (
            target_vehicle
        )

    if resolution_errors:
        return return_form_errors(resolution_errors)

    for corrected_chassis, target_vehicle in (
        vehicle_chassis_corrections.items()
    ):
        existing_vehicles_by_chassis[
            corrected_chassis
        ] = target_vehicle

    counted_import_keys = set()
    new_vehicle_count = 0
    reactivate_vehicle_count = 0
    deactivate_vehicle_count = 0

    for i in range(import_count):

        chassis_number = normalize_import_text(
            chassis_numbers[i]
        )

        if not chassis_number:
            return return_form_errors([
                (
                    f"{i + 1}行目の車台番号を入力してください。",
                    "chassis_number"
                )
            ])

        import_key = (
            "chassis",
            chassis_number
        )

        if import_key in counted_import_keys:
            continue

        counted_import_keys.add(import_key)

        existing_vehicle = existing_vehicles_by_chassis.get(
            chassis_number
        )
        target_deleted = target_deleted_values[i]

        if existing_vehicle:
            if existing_vehicle.deleted and not target_deleted:
                reactivate_vehicle_count += 1
            elif not existing_vehicle.deleted and target_deleted:
                deactivate_vehicle_count += 1
        elif not target_deleted:
            new_vehicle_count += 1

    # 取込後の有効車両台数で上限チェック
    if company:
        projected_active_count = (
            current_count
            + new_vehicle_count
            + reactivate_vehicle_count
            - deactivate_vehicle_count
        )

        if projected_active_count > company.vehicle_limit:
            return return_form_errors([
                (
                    f"登録上限を超えます。"
                    f"現在の有効車両 {current_count} 台、"
                    f"有効車両の新規登録予定 {new_vehicle_count} 台、"
                    f"再有効化予定 {reactivate_vehicle_count} 台、"
                    f"無効化予定 {deactivate_vehicle_count} 台、"
                    f"取込後の有効車両 {projected_active_count} 台、"
                    f"上限 {company.vehicle_limit} 台です。",
                    ""
                )
            ])
    # 今回のExcel内ですでに処理した車両
    processed_import_keys = set()
    processed_row_indexes = set()
    registered_count = 0
    updated_count = 0
    unchanged_count = 0
    duplicate_skip_count = 0

    def clean_text(value):
        return str(value or "").strip()

    def validate_text_length(
        value,
        field_name,
        max_length,
        row_number
    ):
        value = clean_text(value)

        error = get_vehicle_text_length_error(
            value,
            field_name,
            max_length
        )

        if error:
            return None, f"{row_number}行目の{error}"

        return value, None

    def to_nonnegative_int(value, field_name, row_number):
        value = str("" if value is None else value).strip().replace(",", "")

        if not value:
            return None, None

        try:
            parsed = parse_nonnegative_int(
                value,
                field_name
            )
        except UploadValidationError as error:
            return None, f"{row_number}行目の{error}"

        return parsed, None

    def validate_import_date(value, field_name, row_number):
        value = clean_text(value)

        error = get_vehicle_date_error(
            value,
            field_name
        )

        if error:
            return "", f"{row_number}行目の{error}"

        return value, None

    for i in range(import_count):

        chassis_number, error = validate_text_length(
            normalize_import_text(
                chassis_numbers[i]
            ),
            "車台番号",
            100,
            i + 1
        )

        if error:
            return return_form_errors([
                (error, "chassis_number")
            ])

        plate_area, error = validate_text_length(
            normalize_import_text(
                plate_areas[i]
            ),
            "車番・地域名",
            50,
            i + 1
        )

        if error:
            return return_form_errors([
                (error, "plate_area")
            ])

        plate_class, error = validate_text_length(
            normalize_import_text(
                plate_classes[i]
            ),
            "車番・分類",
            50,
            i + 1
        )

        if error:
            return return_form_errors([
                (error, "plate_class")
            ])

        plate_kana, error = validate_text_length(
            normalize_import_text(
                plate_kanas[i]
            ),
            "車番・ひらがな",
            10,
            i + 1
        )

        if error:
            return return_form_errors([
                (error, "plate_kana")
            ])

        plate_number, error = validate_text_length(
            normalize_import_text(
                plate_numbers[i]
            ),
            "車番",
            50,
            i + 1
        )

        if error:
            return return_form_errors([
                (error, "plate_number")
            ])

        if not chassis_number:
            return return_form_errors([
                (
                    f"{i + 1}行目の車台番号を入力してください。",
                    "chassis_number"
                )
            ])

        import_key = (
            "chassis",
            chassis_number
        )

        existing_vehicle = (
            existing_vehicles_by_chassis.get(
                chassis_number
            )
        )

        # Excel内で同じ車両が重複している場合
        if import_key in processed_import_keys:
            duplicate_skip_count += 1
            continue

        processed_import_keys.add(import_key)
        processed_row_indexes.add(i)
        gross_vehicle_weight, error = to_nonnegative_int(
            gross_weights[i],
            "車両総重量",
            i + 1
        )

        if error:
            return return_form_errors([
                (error, "gross_vehicle_weight")
            ])

        max_payload, error = to_nonnegative_int(
            max_payloads[i],
            "最大積載量",
            i + 1
        )

        if error:
            return return_form_errors([
                (error, "max_payload")
            ])

        first_registration_date, error = validate_import_date(
            first_registration_dates[i],
            "初年度登録日",
            i + 1
        )

        if error:
            return return_form_errors([
                (error, "first_registration_date")
            ])

        inspection_expiry, error = validate_import_date(
            inspection_expiries[i],
            "車検満了日",
            i + 1
        )

        if error:
            return return_form_errors([
                (error, "inspection_expiry")
            ])

        model_code, error = validate_text_length(
            model_codes[i],
            "車体型式",
            100,
            i + 1
        )

        if error:
            return return_form_errors([
                (error, "model_code")
            ])

        manufacturer, error = validate_text_length(
            vehicle_names[i],
            "車両メーカー",
            100,
            i + 1
        )

        if error:
            return return_form_errors([
                (error, "vehicle_name")
            ])

        body_type, error = validate_text_length(
            body_types[i],
            "車両形状",
            100,
            i + 1
        )

        if error:
            return return_form_errors([
                (error, "body_type")
            ])

        selected_vehicle_type, error = validate_text_length(
            vehicle_types[i],
            "車種",
            100,
            i + 1
        )

        if error:
            return return_form_errors([
                (error, "vehicle_type")
            ])
        
        # 車台番号が一致する車両、または確認済みの訂正対象を更新
        if existing_vehicle:
            update_values = {
                "chassis_number": chassis_number,
                "plate_area": clean_text(plate_areas[i]),
                "plate_class": clean_text(plate_classes[i]),
                "plate_kana": clean_text(plate_kanas[i]),
                "plate_number": clean_text(plate_numbers[i]),
                "gross_vehicle_weight": gross_vehicle_weight,
                "model_code": model_code,
                "first_registration_date": first_registration_date,
                "inspection_expiry": inspection_expiry,
                "manufacturer": manufacturer,
                "body_type": body_type,
                "max_payload": max_payload,
                "office": offices[i],
            }

            comparison_values = dict(update_values)
            comparison_values["type"] = selected_vehicle_type
            comparison_values["deleted"] = target_deleted_values[i]

            comparison_differences = {
                key: {
                    "before": getattr(existing_vehicle, key),
                    "submitted": value,
                    "blank_preserved": (
                        key in update_values and value in ("", None)
                    ),
                }
                for key, value in comparison_values.items()
                if getattr(existing_vehicle, key) != value
            }

            if comparison_differences or clean_text(plate_numbers[i]) in (
                "1594", "4624", "71", "553"
            ):
                app.logger.warning(
                    "VEHICLE_IMPORT_COMPARE row=%s id=%s chassis=%s differences=%s",
                    i + 1,
                    existing_vehicle.id,
                    chassis_number,
                    json.dumps(comparison_differences, ensure_ascii=False),
                )

            vehicle_changed = False
            target_deleted = target_deleted_values[i]

            if bool(existing_vehicle.deleted) != target_deleted:
                existing_vehicle.deleted = target_deleted
                vehicle_changed = True

            for field_name, new_value in update_values.items():
                # Excelが空欄なら既存値を残す
                if new_value in ("", None):
                    continue

                if getattr(existing_vehicle, field_name) != new_value:
                    setattr(
                        existing_vehicle,
                        field_name,
                        new_value
                    )
                    vehicle_changed = True


            if clean_text(existing_vehicle.type) != selected_vehicle_type:
                existing_vehicle.type = selected_vehicle_type
                vehicle_changed = True

            if vehicle_changed:
                updated_count += 1
            else:
                unchanged_count += 1

            continue

        vehicle = Vehicle(
            company_code=company_code,

            plate_area=plate_area,
            plate_class=plate_class,
            plate_kana=plate_kana,
            plate_number=plate_number,

            gross_vehicle_weight=gross_vehicle_weight,

            chassis_number=chassis_number,
            model_code=model_code,

            first_registration_date=first_registration_date,
            inspection_expiry=inspection_expiry,

            # 画面上は「車名」だが、
            # 現在のDBでは manufacturer に保存
            manufacturer=manufacturer,

            body_type=body_type,

            max_payload=max_payload,

            type=selected_vehicle_type,
            office=offices[i],

            deleted=target_deleted_values[i],
        )

        db.session.add(vehicle)

        registered_count += 1

    # Excel車種コードごとに今回選ばれた車種を整理
    mapping_candidates = {}

    for i, (
        excel_value,
        vehicle_type_name
    ) in enumerate(
        zip(
            vehicle_type_codes,
            vehicle_types
        )
    ):

        if i not in processed_row_indexes:
            continue
        
        excel_value = str(excel_value or "").strip()
        vehicle_type_name = str(
            vehicle_type_name or ""
        ).strip()

        if not excel_value:
            continue

        if len(excel_value) > 100:
            return return_form_errors([
                (
                    "車種コードは100文字以内で入力してください。",
                    "vehicle_type_code"
                )
            ])

        if len(vehicle_type_name) > 100:
            return return_form_errors([
                (
                    "車種は100文字以内で入力してください。",
                    "vehicle_type"
                )
            ])

        mapping_candidates.setdefault(
            excel_value,
            set()
        ).add(vehicle_type_name)

    # 同じコードの選択内容が一致している場合だけ学習
    for excel_value, selected_types in mapping_candidates.items():

        mapping = VehicleTypeImportMapping.query.filter_by(
            company_code=company_code,
            excel_value=excel_value
        ).first()

        # 同じコードに複数の車種が指定されている
        # → 自動判定できないので学習しない
        if len(selected_types) > 1:
            if mapping:
                db.session.delete(mapping)
            continue

        vehicle_type_name = next(iter(selected_types))

        if vehicle_type_name:
            if mapping:
                mapping.vehicle_type_name = vehicle_type_name
            else:
                db.session.add(
                    VehicleTypeImportMapping(
                        company_code=company_code,
                        excel_value=excel_value,
                        vehicle_type_name=vehicle_type_name
                    )
                )
        elif mapping:
            db.session.delete(mapping)
            
    db.session.commit()

    result = {
        "registered_count": registered_count,
        "updated_count": updated_count,
        "unchanged_count": unchanged_count,
        "duplicate_skip_count": duplicate_skip_count,
    }
    if request.headers.get("X-DKSS-Final-Submit") == "1":
        session["vehicle_import_complete"] = result
        return jsonify(redirect_url=url_for("import_vehicles", complete="1"))

    return render_template("vehicle_import_complete.html", **result)

VEHICLE_MAINTENANCE_ATTRIBUTE_FIELDS = (('engine_code', '\u30a8\u30f3\u30b8\u30f3\u578b\u5f0f', 100),)


def apply_vehicle_form_values(
    vehicle,
    form_data,
    validated_values
):
    for field_key in [
        "plate_area",
        "plate_class",
        "plate_kana",
        "plate_number",
        "model_code",
        "manufacturer",
        "body_type",
    ]:
        setattr(
            vehicle,
            field_key,
            form_data.get(field_key)
        )

    for field_key in [
        "chassis_number",
        "first_registration_date",
        "inspection_expiry",
        "gross_vehicle_weight",
        "max_payload",
        "type",
        "office",
    ]:
        setattr(
            vehicle,
            field_key,
            validated_values[field_key]
        )

    for field_key, field_label, max_length in VEHICLE_MAINTENANCE_ATTRIBUTE_FIELDS:
        if field_key in form_data:
            value = (form_data.get(field_key) or "").strip()
            setattr(vehicle, field_key, value or None)


def validate_vehicle_master_values(
    vehicle_type,
    office,
    company_code
):
    errors = []

    for value, model, field_name, field_key in [
        (vehicle_type, VehicleType, "車種", "type"),
        (office, Office, "営業所", "office"),
    ]:
        if value:
            valid_value = model.query.filter_by(
                company_code=company_code,
                name=value
            ).first()

            if not valid_value:
                errors.append((
                    f"{field_name}が不正です。",
                    field_key
                ))

    return errors


def get_vehicle_operation_import_submission(
    csv_rows,
    company_code,
    form_data,
    allow_pending=False,
    keep_unassigned=False
):
    selected_lines = set(form_data.getlist("include"))
    known_lines = {
        str(row["line_number"])
        for row in csv_rows
    }

    errors = []
    selections = {}
    records = []
    selected_reports = {}

    if not selected_lines:
        errors.append((
            "取り込む行にチェックを付けてください。",
            ""
        ))

    if not selected_lines.issubset(known_lines):
        errors.append((
            "取込対象の行を確認してください。",
            ""
        ))

    valid_vehicle_ids = {
        vehicle.id
        for vehicle in Vehicle.query.filter_by(
            company_code=company_code
        ).all()
    }

    for csv_row in csv_rows:
        line_number = csv_row["line_number"]
        line_key = str(line_number)
        field_name = f"vehicle_{line_number}"
        selected = line_key in selected_lines

        vehicle_id_text = str(
            form_data.get(field_name, "")
        ).strip()

        vehicle_id = None

        if re.fullmatch(r"[1-9][0-9]{0,17}", vehicle_id_text):
            candidate_id = int(vehicle_id_text)

            if candidate_id in valid_vehicle_ids:
                vehicle_id = candidate_id

        selections[line_key] = {
            "include": selected,
            "vehicle_record_id": vehicle_id,
        }

        if not selected:
            continue

        if vehicle_id is None and not (
            keep_unassigned and not vehicle_id_text
        ):
            if allow_pending and not vehicle_id_text:
                continue

            errors.append((
                f"{line_number}行目の登録先車両を選択してください。",
                field_name
            ))
            continue

        try:
            values = parse_vehicle_operation_csv_row(
                csv_row["source_row"],
                line_number
            )
        except UploadValidationError as error:
            errors.append((
                str(error),
                f"include_{line_number}"
            ))
            continue

        report_number = values["report_number"]

        if report_number in selected_reports:
            errors.append((
                f"{line_number}行目の日報番号は"
                f"{selected_reports[report_number]}行目と重複しています。"
                "取り込む行を1つだけ選択してください。",
                f"include_{line_number}"
            ))
            continue

        selected_reports[report_number] = line_number

        records.append({
            "line_number": line_number,
            "vehicle_record_id": vehicle_id,
            "values": values,
        })

    if allow_pending and not records and not errors:
        errors.append((
            "登録先が決まった実績がありません。登録先を選択するか、車両を追加してください。",
            ""
        ))

    return selections, records, errors


def build_vehicle_operation_import_preview(csv_rows, company_code):
    if not company_code:
        raise UploadValidationError(
            "会社情報を確認できませんでした。"
        )

    vehicles, plate_candidates = (
        get_vehicle_operation_plate_candidates(company_code)
    )

    saved_vehicle_mappings = {}
    valid_vehicle_ids = {vehicle.id for vehicle in vehicles}

    mappings = (
        VehicleOperationVehicleMapping.query
        .filter_by(company_code=company_code)
        .all()
    )

    for mapping in mappings:
        source_number = normalize_vehicle_operation_plate(
            mapping.source_vehicle_number
        )

        if mapping.vehicle_record_id not in valid_vehicle_ids:
            continue

        mapping_key = (
            (mapping.source_vehicle_code or "").strip(),
            source_number,
        )
        saved_vehicle_mappings[mapping_key] = (
            mapping.vehicle_record_id
        )

    report_counts = {}

    for csv_row in csv_rows:
        report_number = (
            csv_row["source_row"]
            .get("日報番号", "")
            .strip()
        )

        if report_number:
            report_counts[report_number] = (
                report_counts.get(report_number, 0) + 1
            )

    report_numbers = sorted(report_counts)
    existing_records = {}

    for start in range(0, len(report_numbers), 400):
        records = (
            VehicleOperationRecord.query
            .filter(
                VehicleOperationRecord.company_code == company_code,
                VehicleOperationRecord.report_number.in_(
                    report_numbers[start:start + 400]
                )
            )
            .all()
        )

        for record in records:
            existing_records[record.report_number] = record.id

    preview_rows = []

    for csv_row in csv_rows:
        source_row = csv_row["source_row"]
        line_number = csv_row["line_number"]
        report_number = source_row.get("日報番号", "").strip()

        preview_row = {
            "line_number": line_number,
            "source_row": source_row,
            "values": {},
            "vehicle_record_id": None,
            "candidate_vehicle_ids": [],
            "duplicate_in_file": (
                report_counts.get(report_number, 0) > 1
            ),
            "existing_record_id": existing_records.get(
                report_number
            ),
            "errors": [],
        }

        try:
            values = parse_vehicle_operation_csv_row(
                source_row,
                line_number
            )
        except UploadValidationError as error:
            preview_row["errors"].append(str(error))
        else:
            values.pop("source_row_json", None)

            for field_name in (
                "departure_meter",
                "arrival_meter",
                "distance",
            ):
                if values[field_name] is not None:
                    values[field_name] = str(values[field_name])

            preview_row["values"] = values

            plate = normalize_vehicle_operation_plate(
                values.get("source_vehicle_number")
            )
            candidate_ids = plate_candidates.get(plate, [])

            preview_row["candidate_vehicle_ids"] = list(
                candidate_ids
            )

            mapping_key = (
                str(
                    values.get("source_vehicle_code") or ""
                ).strip(),
                plate,
            )
            mapped_vehicle_id = saved_vehicle_mappings.get(
                mapping_key
            )

            if mapped_vehicle_id is not None:
                preview_row["vehicle_record_id"] = (
                    mapped_vehicle_id
                )
            elif len(candidate_ids) == 1:
                preview_row["vehicle_record_id"] = (
                    candidate_ids[0]
                )

        preview_rows.append(preview_row)

    return vehicles, preview_rows


def get_vehicle_operation_summary(company_code, vehicle_record_id):
    operations = VehicleOperationRecord.query.filter_by(
        company_code=company_code,
        vehicle_record_id=vehicle_record_id,
    ).all()
    maintenance = VehicleMaintenanceRecord.query.filter_by(
        company_code=company_code,
        vehicle_record_id=vehicle_record_id,
    ).all()

    periodic = VehiclePeriodicInspectionRecord.query.filter_by(
        company_code=company_code,
        vehicle_record_id=vehicle_record_id,
    ).all()

    reference = build_vehicle_karte_mileage_reference(
        maintenance,
        operations,
        datetime.now(ZoneInfo("Asia/Tokyo")).date().isoformat(),
        periodic_records=periodic,
    )
    return {
        "current_mileage": reference["value"],
        "mileage_date": reference["date"],
        "mileage_reference": reference,
    }


def get_vehicle_registration_plate_conflicts(
    company_code,
    plate_area,
    plate_class,
    plate_kana,
    plate_number,
    chassis_number,
    exclude_vehicle_id=None,
    existing_vehicles=None
):
    plate_parts = (
        plate_area,
        plate_class,
        plate_kana,
        plate_number,
    )
    normalized_parts = tuple(
        normalize_vehicle_operation_plate(value)
        for value in plate_parts
    )

    # 不完全なナンバーから同一車両と判断しない
    if not all(normalized_parts):
        return []

    if existing_vehicles is None:
        existing_vehicles = Vehicle.query.filter_by(
            company_code=company_code
        ).order_by(Vehicle.id.asc()).all()

    conflicts = []

    for vehicle in existing_vehicles:
        if vehicle.company_code != company_code:
            continue

        if vehicle.id == exclude_vehicle_id:
            continue
        existing_parts = tuple(
            normalize_vehicle_operation_plate(value)
            for value in (
                vehicle.plate_area,
                vehicle.plate_class,
                vehicle.plate_kana,
                vehicle.plate_number,
            )
        )

        if existing_parts != normalized_parts:
            continue

        if (
            str(vehicle.chassis_number or "").strip()
            == str(chassis_number or "").strip()
        ):
            continue

        conflicts.append({
            "id": vehicle.id,
            "chassis_number": vehicle.chassis_number or "",
            "office": vehicle.office or "",
            "inactive": bool(vehicle.deleted),
        })

    return conflicts


def normalize_vehicle_operation_plate(value):
    import unicodedata

    text = unicodedata.normalize(
        "NFKC",
        "" if value is None else str(value)
    ).strip()

    return re.sub(
        r"[\s\-‐‑‒–—―−・･.]+",
        "",
        text
    ).casefold()


def get_vehicle_operation_plate_candidates(company_code):
    vehicles = (
        Vehicle.query
        .filter_by(
            company_code=company_code
        )
        .order_by(Vehicle.id.asc())
        .all()
    )

    plate_candidates = {}

    for vehicle in vehicles:
        if not all((
            vehicle.plate_area,
            vehicle.plate_class,
            vehicle.plate_kana,
            vehicle.plate_number,
        )):
            continue

        plate = normalize_vehicle_operation_plate(
            vehicle_number({
                "plate_area": vehicle.plate_area,
                "plate_class": vehicle.plate_class,
                "plate_kana": vehicle.plate_kana,
                "plate_number": vehicle.plate_number,
            })
        )

        if plate:
            plate_candidates.setdefault(
                plate,
                []
            ).append(vehicle.id)

    return vehicles, plate_candidates


def parse_vehicle_operation_csv_row(source_row, line_number):
    try:
        report_number = source_row.get("日報番号", "").strip()

        if not report_number:
            raise UploadValidationError(
                "日報番号がありません。"
            )

        if len(report_number) > 100:
            raise UploadValidationError(
                "日報番号は100文字以内にしてください。"
            )

        operation_date = parse_vehicle_operation_date(
            source_row.get("運行日"),
            "運行日"
        )

        if operation_date is None:
            raise UploadValidationError(
                "運行日がありません。"
            )

        values = {
            "report_number": report_number,
            "operation_date": operation_date,
            "source_row_json": json.dumps(
                source_row,
                ensure_ascii=False
            ),
        }

        for csv_name, field_name in (
            ("車両コード", "source_vehicle_code"),
            ("車両", "source_vehicle_number"),
        ):
            text = source_row.get(csv_name, "").strip()

            if len(text) > 100:
                raise UploadValidationError(
                    f"{csv_name}は100文字以内にしてください。"
                )

            values[field_name] = text or None

        for csv_name, field_name in (
            ("出庫日時", "departure_at"),
            ("入庫日時", "arrival_at"),
        ):
            values[field_name] = parse_vehicle_operation_date(
                source_row.get(csv_name),
                csv_name,
                with_time=True
            )

        for csv_name, field_name in (
            ("出庫メータ", "departure_meter"),
            ("入庫メータ", "arrival_meter"),
            ("走行距離", "distance"),
        ):
            values[field_name] = parse_vehicle_operation_decimal(
                source_row.get(csv_name),
                csv_name
            )

        return values

    except UploadValidationError as error:
        raise UploadValidationError(
            f"CSVの{line_number}行目：{error}"
        ) from error


def read_vehicle_operation_csv(file_bytes):
    csv_text = None

    for encoding in ("utf-8-sig", "cp932"):
        try:
            csv_text = file_bytes.decode(encoding)
            break
        except UnicodeDecodeError:
            continue

    if csv_text is None:
        raise UploadValidationError(
            "CSVの文字コードを確認してください。"
        )

    if "\x00" in csv_text:
        raise UploadValidationError(
            "CSVファイルの内容が不正です。"
        )

    rows = []

    try:
        reader = csv.reader(
            StringIO(csv_text, newline=""),
            strict=True
        )
        headers = [
            value.strip()
            for value in next(reader, [])
        ]

        if not headers or any(not value for value in headers):
            raise UploadValidationError(
                "CSVの先頭行に項目名を設定してください。"
            )

        if len(headers) != len(set(headers)):
            raise UploadValidationError(
                "CSVの項目名が重複しています。"
            )

        missing_headers = [
            name
            for name in ("日報番号", "運行日")
            if name not in headers
        ]

        if missing_headers:
            raise UploadValidationError(
                "CSVに必要な項目がありません："
                + "、".join(missing_headers)
            )

        if not any(
            name in headers
            for name in ("車両コード", "車両")
        ):
            raise UploadValidationError(
                "CSVに車両コードまたは車両の項目が必要です。"
            )

        for values in reader:
            if not any(value.strip() for value in values):
                continue

            if len(values) != len(headers):
                raise UploadValidationError(
                    f"CSVの{reader.line_num}行目の列数が"
                    "項目名の列数と一致していません。"
                )

            rows.append({
                "line_number": reader.line_num,
                "source_row": dict(zip(headers, values)),
            })

    except csv.Error:
        raise UploadValidationError(
            "CSVの区切り文字・引用符を確認してください。"
        )

    if not rows:
        raise UploadValidationError(
            "CSVに運行実績のデータがありません。"
        )

    return rows


def parse_vehicle_operation_date(value, field_name, with_time=False):
    text = "" if value is None else str(value).strip()

    if not text:
        return None

    if with_time:
        formats = (
            "%Y/%m/%d %H:%M:%S",
            "%Y-%m-%d %H:%M:%S",
            "%Y/%m/%d %H:%M",
            "%Y-%m-%d %H:%M",
        )
        output_format = "%Y-%m-%d %H:%M:%S"
    else:
        formats = (
            "%Y/%m/%d",
            "%Y-%m-%d",
        )
        output_format = "%Y-%m-%d"

    for date_format in formats:
        try:
            parsed = datetime.strptime(text, date_format)
        except ValueError:
            continue

        return parsed.strftime(output_format)

    raise UploadValidationError(
        f"{field_name}の日付・時刻を確認してください。"
    )


def parse_vehicle_operation_decimal(value, field_name):
    text = "" if value is None else str(value).strip()

    if not text:
        return None

    if not re.fullmatch(
        r"(?:[0-9]+|[0-9]{1,3}(?:,[0-9]{3})+)(?:\.[0-9]+)?",
        text
    ):
        raise UploadValidationError(
            f"{field_name}は0以上の数値で入力してください。"
        )

    try:
        parsed = Decimal(text.replace(",", ""))
    except InvalidOperation:
        raise UploadValidationError(
            f"{field_name}の数値を確認してください。"
        )

    if not parsed.is_finite() or parsed > Decimal("999999999999.99"):
        raise UploadValidationError(
            f"{field_name}の値が大きすぎます。"
        )

    try:
        rounded = parsed.quantize(Decimal("0.01"))
    except InvalidOperation:
        raise UploadValidationError(
            f"{field_name}の数値を確認してください。"
        )

    if parsed != rounded:
        raise UploadValidationError(
            f"{field_name}は小数点以下2桁までで入力してください。"
        )

    return rounded


def parse_vehicle_weights(form_data):
    values = {
        "gross_vehicle_weight": 0,
        "max_payload": 0,
    }
    errors = []

    for field_key, field_name in [
        ("gross_vehicle_weight", "車両総重量"),
        ("max_payload", "最大積載量"),
    ]:
        try:
            values[field_key] = parse_nonnegative_int(
                form_data.get(field_key),
                field_name
            )
        except UploadValidationError:
            errors.append((
                f"{field_name}の入力内容を確認してください。",
                field_key
            ))

    return values, errors


def get_vehicle_text_length_error(
    value,
    field_name,
    max_length
):
    if len(value) > max_length:
        return (
            f"{field_name}は"
            f"{max_length}文字以内で入力してください。"
        )

    return None


def get_vehicle_date_error(value, field_name):
    if not value:
        return None

    # Certificate first registration has month precision; never invent a day.
    if field_name == "初年度登録日" and re.fullmatch(r"[0-9]{4}-[0-9]{2}", value):
        year, month = map(int, value.split("-"))
        if 1 <= year <= 9999 and 1 <= month <= 12:
            return None
        return f"{field_name}が不正です。"

    try:
        datetime.strptime(value, "%Y-%m-%d")
    except ValueError:
        return f"{field_name}が不正です。"

    return None


def validate_vehicle_dates(
    first_registration_date,
    inspection_expiry
):
    errors = []

    for value, field_name, field_key in [
        (
            first_registration_date,
            "初年度登録日",
            "first_registration_date"
        ),
        (
            inspection_expiry,
            "車検満了日",
            "inspection_expiry"
        ),
    ]:
        error = get_vehicle_date_error(
            value,
            field_name
        )

        if error:
            errors.append((
                error,
                field_key
            ))

    return errors

def validate_vehicle_text_fields(form_data):
    field_settings = [
        ("plate_area", "車番・地域名", 50),
        ("plate_class", "車番・分類", 50),
        ("plate_kana", "車番・ひらがな", 10),
        ("plate_number", "車番", 50),
        ("chassis_number", "車台番号", 100),
        ("model_code", "車体型式", 100),
        ("manufacturer", "車両メーカー", 100),
        ("body_type", "車両形状", 100),
    ]

    field_settings += list(VEHICLE_MAINTENANCE_ATTRIBUTE_FIELDS)

    errors = []

    for field_key, field_name, max_length in field_settings:
        value = form_data.get(field_key, "").strip()

        error = get_vehicle_text_length_error(
            value,
            field_name,
            max_length
        )

        if error:
            errors.append((
                error,
                field_key
            ))

    return errors


@app.route("/master/vehicles/certificate/extract", methods=["POST"])
@limiter.limit("5 per minute", methods=["POST"])
def extract_vehicle_certificate_route():
    """車検証から登録候補を抽出する。DB更新なし。"""
    from flask import abort
    from vehicle_certificate_ai import extract_vehicle_certificate
    from vehicle_certificate_adapter import prepare_certificate_form

    if not session.get("username") or not session.get("company_code"):
        abort(403)

    max_bytes = 20 * 1024 * 1024

    if request.content_length and request.content_length > max_bytes + 65536:
        return {"error": "ファイルは20MB以下にしてください。"}, 413

    upload = request.files.get("certificate")
    if upload is None or not upload.filename:
        return {"error": "車検証ファイルを選択してください。"}, 400

    filename = upload.filename.rsplit("\\", 1)[-1].rsplit("/", 1)[-1]
    extension = filename.rsplit(".", 1)[-1].lower() if "." in filename else ""

    if extension not in {"pdf", "jpg", "jpeg", "png"}:
        return {"error": "PDF・JPEG・PNGに対応しています。"}, 400

    raw = upload.read(max_bytes + 1)
    if not raw:
        return {"error": "ファイルが空です。"}, 400
    if len(raw) > max_bytes:
        return {"error": "ファイルは20MB以下にしてください。"}, 413

    valid_pdf = extension == "pdf" and raw.startswith(b"%PDF-")
    valid_jpeg = extension in {"jpg", "jpeg"} and raw.startswith(b"\xff\xd8\xff")
    valid_png = extension == "png" and raw.startswith(
        b"\x89PNG\r\n\x1a\n"
    )

    if not (valid_pdf or valid_jpeg or valid_png):
        return {"error": "ファイル形式が拡張子と一致しません。"}, 400

    try:
        extraction = extract_vehicle_certificate(raw, filename)

        vehicle_types = [
            item["name"]
            for item in vehicle_types_for_current_company()
        ]

        prepared = prepare_certificate_form(extraction, vehicle_types)
        try:
            remember_vehicle_certificate_specification_source(raw, filename, extraction)
        except Exception:
            db.session.rollback()
            app.logger.exception("Certificate source preservation failed")
            prepared["warnings"].append(
                "原本との照合情報を保存できませんでした。車両情報の確認・登録は続けられます。"
            )

    except ValueError:
        return {
            "error": "車検証を読み取れませんでした。ファイルを確認してください。"
        }, 422
    except RuntimeError:
        return {
            "error": "AI読み取りに失敗しました。時間をおいて再試行してください。"
        }, 502

    response = jsonify({
        "vehicle": prepared["form"],
        "warnings": prepared["warnings"],
        "needs_review": True,
        "source_filename": filename,
    })
    response.headers["X-Content-Type-Options"] = "nosniff"
    return response, 200


